def _dot_precedes(content, pos):
    i = pos - 1
    while i >= 0 and content[i] in ' \t':
        i -= 1
    return i >= 0 and content[i] == '.'

UI_SCALE = 1.0
UI_DPI = 96.0
LOCK_UI_DIMENSIONS = True
BASE_DPI = 96.0
_DPI_SELECTED_MODE = None
_DPI_THREAD_CONTEXT_ORIGINAL = None
_DPI_WIDGETS = weakref.WeakSet()
_DPI_INTERNAL_APPLY = False
_DPI_WIDGET_PATCHED = False


class _DpiPx(int):
    def __new__(cls, physical_value, logical_value):
        obj = int.__new__(cls, int(physical_value))
        obj.logical_value = float(logical_value)
        return obj


def _try_set_dpi_context(setter_name, context_value):
    try:
        setter = getattr(ctypes.windll.user32, setter_name, None)
        if setter is None:
            return False
        setter.argtypes = [ctypes.c_void_p]
        setter.restype = ctypes.c_int if setter_name == "SetProcessDpiAwarenessContext" else ctypes.c_void_p
        result = setter(ctypes.c_void_p(context_value))
        return bool(result)
    except Exception:
        return False


def enable_process_dpi_awareness():
    global _DPI_SELECTED_MODE, _DPI_THREAD_CONTEXT_ORIGINAL
    if sys.platform != "win32":
        _DPI_SELECTED_MODE = "platform_default"
        return _DPI_SELECTED_MODE

    if _try_set_dpi_context("SetProcessDpiAwarenessContext", -2):
        _DPI_SELECTED_MODE = "system_aware_process"
        return _DPI_SELECTED_MODE

    try:
        if ctypes.windll.shcore.SetProcessDpiAwareness(1) == 0:
            _DPI_SELECTED_MODE = "system_aware_process_legacy"
            return _DPI_SELECTED_MODE
    except Exception:
        pass

    try:
        setter = getattr(ctypes.windll.user32, "SetProcessDPIAware", None)
        if setter is not None:
            setter.argtypes = []
            setter.restype = ctypes.c_int
            if setter():
                _DPI_SELECTED_MODE = "system_aware_process_legacy"
                return _DPI_SELECTED_MODE
    except Exception:
        pass

    try:
        setter = getattr(ctypes.windll.user32, "SetThreadDpiAwarenessContext", None)
        if setter is not None:
            setter.argtypes = [ctypes.c_void_p]
            setter.restype = ctypes.c_void_p
            previous = setter(ctypes.c_void_p(-2))
            if previous:
                _DPI_THREAD_CONTEXT_ORIGINAL = previous
                _DPI_SELECTED_MODE = "system_aware_thread"
                return _DPI_SELECTED_MODE
    except Exception:
        pass

    try:
        setter = getattr(ctypes.windll.user32, "SetThreadDpiAwarenessContext", None)
        if setter is not None:
            setter.argtypes = [ctypes.c_void_p]
            setter.restype = ctypes.c_void_p
            for context_value, mode_name in (
                (-5, "unaware_gdi_scaled_thread"),
                (-1, "unaware_thread"),
            ):
                previous = setter(ctypes.c_void_p(context_value))
                if previous:
                    _DPI_THREAD_CONTEXT_ORIGINAL = previous
                    _DPI_SELECTED_MODE = mode_name
                    return _DPI_SELECTED_MODE
    except Exception:
        pass

    _DPI_SELECTED_MODE = "manifest_or_windows_default"
    return _DPI_SELECTED_MODE


def ui_px(value):
    try:
        logical = value.logical_value if isinstance(value, _DpiPx) else float(value)
        physical = max(1, int(round(logical * UI_SCALE))) if logical > 0 else 0
        return _DpiPx(physical, logical)
    except Exception:
        return int(value)


def _dpi_px_from_current_pixels(value):
    try:
        physical = int(round(float(value)))
        scale = max(0.01, float(UI_SCALE))
        return _DpiPx(physical, physical / scale)
    except Exception:
        return value


def _centered_group_pixel_offset(container_width, group_width, leading_inset, trailing_inset):
    container_center = float(container_width) / 2.0
    anchor_offset = int(group_width) // 2
    ideal_offset = (float(trailing_inset) - float(leading_inset)) / 2.0
    first_offset = int(math.floor(ideal_offset)) - 2
    last_offset = int(math.ceil(ideal_offset)) + 2
    best = None
    for offset in range(first_offset, last_offset + 1):
        group_left = int(math.floor(container_center - anchor_offset + offset + 0.5))
        visual_center = (
            group_left + float(group_width) / 2.0
            + (float(leading_inset) - float(trailing_inset)) / 2.0
        )
        error = visual_center - container_center
        candidate = (abs(error), abs(offset - ideal_offset), abs(offset), offset)
        if best is None or candidate < best:
            best = candidate
    return best[3] if best is not None else 0


def _dpi_dimension_base(value):
    if isinstance(value, _DpiPx):
        return value.logical_value
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, tuple):
        return tuple(_dpi_dimension_base(item) for item in value)
    if isinstance(value, list):
        return [_dpi_dimension_base(item) for item in value]
    if isinstance(value, str):
        text = value.strip()
        try:
            return float(text)
        except (TypeError, ValueError):
            parts = text.split()
            if len(parts) > 1:
                try:
                    return tuple(float(part) for part in parts)
                except ValueError:
                    pass
    return value


def _dpi_dimension_scaled(base, scale):
    if isinstance(base, bool):
        return base
    if isinstance(base, (int, float)):
        return int(round(float(base) * scale))
    if isinstance(base, tuple):
        return tuple(_dpi_dimension_scaled(item, scale) for item in base)
    if isinstance(base, list):
        return [_dpi_dimension_scaled(item, scale) for item in base]
    return base


_PIXEL_COMMON_OPTIONS = {
    "padx", "pady", "ipadx", "ipady", "borderwidth", "bd",
    "highlightthickness", "insertwidth", "insertborderwidth",
    "selectborderwidth", "wraplength", "spacing1", "spacing2", "spacing3",
    "sashwidth", "sashpad", "handlepad", "handlesize", "sliderlength",
    "troughcolor_width",
}
_PIXEL_FRAME_WIDGETS = {
    "frame", "labelframe", "canvas", "panedwindow", "message", "scrollbar",
    "ttk::frame", "ttk::labelframe", "ttk::canvas", "ttk::panedwindow",
    "ttk::scrollbar", "ttk::separator",
}
_PIXEL_LENGTH_WIDGETS = {"scale", "ttk::scale", "ttk::progressbar"}


def _dpi_option_is_dimension(widget_name, option):
    name = str(widget_name or "").lower()
    option = str(option or "").lstrip("-").lower()
    if option in _PIXEL_COMMON_OPTIONS:
        return True
    if option == "padding" and name.startswith("ttk::"):
        return True
    if option in ("width", "height") and name in _PIXEL_FRAME_WIDGETS:
        return True
    if option == "length" and name in _PIXEL_LENGTH_WIDGETS:
        return True
    return False


def _merge_tk_options(cnf, kw):
    if cnf is None and not kw:
        return {}
    if isinstance(cnf, str):
        return None
    try:
        merged = tk._cnfmerge((cnf, kw))
        return dict(merged) if isinstance(merged, dict) else None
    except (TypeError, tk.TclError):
        return None


def install_dpi_widget_scaling():
    global _DPI_WIDGET_PATCHED
    if _DPI_WIDGET_PATCHED:
        return
    _DPI_WIDGET_PATCHED = True

    original_base_init = tk.BaseWidget.__init__
    def dpi_base_init(self, master, widget_name, cnf={}, kw={}, extra=()):
        merged = _merge_tk_options(cnf, kw)
        if merged is None:
            return original_base_init(self, master, widget_name, cnf, kw, extra)
        base_dimensions = {}
        for key, value in list(merged.items()):
            if isinstance(key, str) and _dpi_option_is_dimension(widget_name, key):
                base = _dpi_dimension_base(value)
                base_dimensions[key.lstrip("-")] = base
                merged[key] = _dpi_dimension_scaled(base, UI_SCALE)
        result = original_base_init(self, master, widget_name, merged, {}, extra)
        self._pycode_dpi_widget_name = widget_name
        self._pycode_dpi_base_options = base_dimensions
        self._pycode_dpi_manager_name = None
        self._pycode_dpi_manager_options = {}
        _DPI_WIDGETS.add(self)
        return result
    tk.BaseWidget.__init__ = dpi_base_init

    def patch_configure(cls):
        original = cls.configure
        def dpi_configure(self, cnf=None, **kw):
            if _DPI_INTERNAL_APPLY:
                return original(self, cnf=cnf, **kw)
            merged = _merge_tk_options(cnf, kw)
            if merged is None or not merged:
                return original(self, cnf=cnf, **kw)
            widget_name = getattr(self, "_pycode_dpi_widget_name", getattr(self, "widget_name", ""))
            base_options = self.__dict__.setdefault("_pycode_dpi_base_options", {})
            scaled = dict(merged)
            changed = False
            for key, value in merged.items():
                if isinstance(key, str) and _dpi_option_is_dimension(widget_name, key):
                    base = _dpi_dimension_base(value)
                    name = key.lstrip("-")
                    base_options[name] = base
                    scaled[key] = _dpi_dimension_scaled(base, UI_SCALE)
                    changed = True
            return original(self, cnf=scaled if changed or merged else cnf, **({} if changed or merged else kw))
        cls.configure = dpi_configure
        cls.config = dpi_configure

    patch_configure(tk.Misc)
    try:
        patch_configure(ttk.Widget)
    except Exception:
        pass

    def patch_manager(cls, manager_name, method_names, dimension_names):
        for method_name in method_names:
            original = getattr(cls, method_name, None)
            if original is None:
                continue
            def make_wrapper(original_method, manager=manager_name, allowed=dimension_names):
                def dpi_manager(self, cnf={}, **kw):
                    if _DPI_INTERNAL_APPLY:
                        return original_method(self, cnf=cnf, **kw)
                    merged = _merge_tk_options(cnf, kw)
                    if merged is None or not merged:
                        return original_method(self, cnf=cnf, **kw)
                    scaled = dict(merged)
                    base_options = self.__dict__.setdefault("_pycode_dpi_manager_options", {})
                    for key, value in merged.items():
                        if key not in allowed:
                            continue
                        if manager == "place" and key in ("x", "y") and not isinstance(value, _DpiPx):
                            continue
                        base_options[key] = _dpi_dimension_base(value)
                        scaled[key] = _dpi_dimension_scaled(base_options[key], UI_SCALE)
                    self._pycode_dpi_manager_name = manager
                    return original_method(self, cnf=scaled)
                return dpi_manager
            setattr(cls, method_name, make_wrapper(original))

    patch_manager(tk.Pack, "pack", ("pack_configure", "pack"), {"padx", "pady", "ipadx", "ipady"})
    patch_manager(tk.Grid, "grid", ("grid_configure", "grid"), {"padx", "pady", "ipadx", "ipady"})
    patch_manager(tk.Place, "place", ("place_configure", "place"), {"width", "height", "x", "y"})


def _apply_dpi_widget_scale(new_scale):
    global _DPI_INTERNAL_APPLY
    _DPI_INTERNAL_APPLY = True
    try:
        for widget in list(_DPI_WIDGETS):
            try:
                if not widget.winfo_exists():
                    continue
            except (tk.TclError, AttributeError):
                continue
            bases = getattr(widget, "_pycode_dpi_base_options", {})
            if bases:
                configured = {
                    key: _dpi_dimension_scaled(base, new_scale)
                    for key, base in bases.items()
                }
                try:
                    widget.configure(**configured)
                except (tk.TclError, TypeError, ValueError):
                    pass
            manager = getattr(widget, "_pycode_dpi_manager_name", None)
            manager_bases = getattr(widget, "_pycode_dpi_manager_options", {})
            if manager and manager_bases:
                configured = {
                    key: _dpi_dimension_scaled(base, new_scale)
                    for key, base in manager_bases.items()
                }
                try:
                    if manager == "pack":
                        tk.Pack.pack_configure(widget, **configured)
                    elif manager == "grid":
                        tk.Grid.grid_configure(widget, **configured)
                    elif manager == "place":
                        tk.Place.place_configure(widget, **configured)
                except (tk.TclError, TypeError, ValueError):
                    pass
    finally:
        _DPI_INTERNAL_APPLY = False


def get_window_dpi(window):
    if sys.platform == "win32":
        try:
            hwnd = window.winfo_id()
            getter = getattr(ctypes.windll.user32, "GetDpiForWindow", None)
            if getter is not None:
                getter.argtypes = [ctypes.c_void_p]
                getter.restype = ctypes.c_uint
                dpi = int(getter(ctypes.c_void_p(hwnd)))
                if dpi > 0:
                    return float(dpi)
        except Exception:
            pass
        try:
            dpi = int(ctypes.windll.user32.GetDpiForSystem())
            if dpi > 0:
                return float(dpi)
        except Exception:
            pass
    try:
        dpi = float(window.winfo_fpixels("1i"))
        if dpi > 0:
            return dpi
    except Exception:
        pass
    return 96.0


def get_window_dpi_awareness(window):
    if sys.platform != "win32":
        return None
    try:
        user32 = ctypes.windll.user32
        get_context = getattr(user32, "GetWindowDpiAwarenessContext", None)
        get_awareness = getattr(user32, "GetAwarenessFromDpiAwarenessContext", None)
        if get_context is None or get_awareness is None:
            return None
        get_context.argtypes = [ctypes.c_void_p]
        get_context.restype = ctypes.c_void_p
        get_awareness.argtypes = [ctypes.c_void_p]
        get_awareness.restype = ctypes.c_int
        context = get_context(ctypes.c_void_p(int(window.winfo_id())))
        if not context:
            return None
        value = int(get_awareness(context))
        return value if value in (0, 1, 2) else None
    except Exception:
        return None


