MATERIAL_SYMBOL_FONT = ("Material Symbols Sharp Filled", 11, "normal", "roman")
_EMBEDDED_FONT_STATUS = {}


def _read_ttf_legacy_family_name(font_path):
    try:
        import struct
        with open(font_path, "rb") as font_file:
            data = font_file.read()
        if len(data) < 12:
            return None
        table_count = struct.unpack_from(">H", data, 4)[0]
        name_offset = name_length = None
        for index in range(table_count):
            record_offset = 12 + index * 16
            if record_offset + 16 > len(data):
                return None
            tag = data[record_offset:record_offset + 4]
            if tag == b"name":
                name_offset, name_length = struct.unpack_from(">II", data, record_offset + 8)
                break
        if name_offset is None or name_offset + 6 > len(data):
            return None
        _fmt, count, strings_offset = struct.unpack_from(">HHH", data, name_offset)
        records_start = name_offset + 6
        candidates = []
        for index in range(count):
            rec = records_start + index * 12
            if rec + 12 > len(data):
                break
            platform, encoding, _language, name_id, length, offset = struct.unpack_from(">HHHHHH", data, rec)
            if name_id != 1 or length <= 0:
                continue
            start = name_offset + strings_offset + offset
            end = start + length
            if end > len(data):
                continue
            raw = data[start:end]
            try:
                if platform in (0, 3):
                    value = raw.decode("utf-16-be", errors="strict")
                elif platform == 1:
                    value = raw.decode("mac_roman", errors="strict")
                else:
                    continue
                value = " ".join(value.replace("\x00", "").split())
                if value:
                    priority = 0 if platform == 3 and encoding in (1, 10) else (1 if platform == 0 else 2)
                    candidates.append((priority, value))
            except (UnicodeDecodeError, LookupError):
                continue
        if candidates:
            candidates.sort(key=lambda item: item[0])
            return candidates[0][1]
    except (OSError, ValueError, TypeError, ImportError):
        return None
    return None


def material_symbol_font_for_toolbar_action(action, root=None):
    return MATERIAL_SYMBOL_FONT


def material_symbol(name):
    if not _EMBEDDED_FONT_STATUS.get("material_symbols", {}).get("loaded"):
        return None
    return ICON_CONFIG["glyphs"].get(str(name))


def icon_element_spec(element_id):
    return ICON_CONFIG.get("elements", {}).get(str(element_id), {})


def icon_element_color_role(element_id):
    return icon_element_spec(element_id).get("color_role")


def material_element_symbol(element_id, *, fallback_name=None):
    spec = icon_element_spec(element_id)
    glyph_name = spec.get("glyph") or fallback_name
    return material_symbol(glyph_name) if glyph_name else None


def material_menu_symbol(label):
    text = str(label)
    return material_element_symbol(
        f"dropdown.{text}", fallback_name=ICON_CONFIG.get("menu_items", {}).get(text)
    )


def material_menu_accent_role(label):
    text = str(label)
    role = icon_element_color_role(f"dropdown.{text}")
    if role is not None:
        return role
    return ICON_CONFIG.get("menu_item_accent_roles", {}).get(text)


def material_popup_category_symbol(title, namespace="shortcuts"):
    text = str(title)
    fallback = ICON_CONFIG.get("popup_category_icons", {}).get(text)
    return material_element_symbol(f"{namespace}.category.{text}", fallback_name=fallback)


