def icon_pastel_color(role):
    if role == "save_turquoise":
        # Same turquoise as the toolbar Save button (follows the active theme).
        accent = COLORS.get("save_button_accent")
        if IS_LIGHT_THEME:
            return accent
        return lighten_color(accent, 0.35)
    colors = _ICON_PASTEL_COLORS.get(str(role or ""))
    if not colors:
        return None
    return colors[1] if IS_LIGHT_THEME else colors[0]


_RASTER_ICON_SS = 8
_RASTER_ICON_CACHE = {}


def _render_centered_icon_alpha(font_path, glyph, nominal_px, box, ss=_RASTER_ICON_SS):
    from PIL import Image as _Img, ImageDraw, ImageFont
    resample = getattr(getattr(_Img, "Resampling", _Img), "BOX")
    box8 = int(box) * ss
    nominal8 = max(1, int(round(float(nominal_px) * ss)))

    def measure(size8):
        font = ImageFont.truetype(font_path, size8)
        side = max(box8, 3 * size8) + 16
        canvas = _Img.new("L", (side, side), 0)
        ImageDraw.Draw(canvas).text(
            (side // 4, (side * 3) // 4), glyph, font=font, fill=255, anchor="ls",
        )
        bbox = canvas.point(lambda value: 255 if value >= 128 else 0).getbbox()
        return canvas, bbox

    def misalignment(extent8):
        target_parity = int(box) % 2
        best = None
        for whole in range(0, int(box) + 1):
            if whole % 2 != target_parity:
                continue
            gap = abs(extent8 - whole * ss)
            if best is None or gap < best:
                best = gap
        return best if best is not None else 0

    best = None
    for delta in sorted(range(-12, 13), key=abs):
        size8 = nominal8 + delta
        if size8 < 1:
            continue
        canvas, bbox = measure(size8)
        if not bbox:
            continue
        w8, h8 = bbox[2] - bbox[0], bbox[3] - bbox[1]
        if w8 > box8 or h8 > box8:
            continue
        score = misalignment(w8) + misalignment(h8) + abs(delta) * 0.25
        if best is None or score < best[0]:
            best = (score, canvas, bbox)
        if score <= 0.25 * abs(delta) + 0.5:
            break
    if best is None:
        return None
    _score, canvas, bbox = best
    w8, h8 = bbox[2] - bbox[0], bbox[3] - bbox[1]
    offset_x = (box8 - w8) // 2 - bbox[0]
    offset_y = (box8 - h8) // 2 - bbox[1]
    big = _Img.new("L", (box8, box8), 0)
    big.paste(canvas, (offset_x, offset_y))
    return big.resize((int(box), int(box)), resample)


def _raster_icon_photo(widget, glyph, font, fg, box):
    if Image is None or not glyph or not box:
        return None
    family = str(font[0] if isinstance(font, (tuple, list)) and font else font).lower()
    font_style = "regular" if "cascadia" in family else "material_symbols"
    font_path = _EMBEDDED_FONT_STATUS.get(font_style, {}).get("path")
    if not font_path or not os.path.isfile(font_path):
        return None
    points = abs(float(font[1])) if isinstance(font, (tuple, list)) and len(font) > 1 else 11.0
    nominal_px = max(1, int(round(points * float(widget.winfo_fpixels("1p")))))
    red, green, blue = (channel >> 8 for channel in widget.winfo_rgb(fg))
    key = (glyph, font_path, nominal_px, int(box), red, green, blue)
    cached = _RASTER_ICON_CACHE.get(key)
    if cached is not None:
        return cached
    mask = _render_centered_icon_alpha(font_path, glyph, nominal_px, int(box))
    if mask is None:
        return None
    import base64
    rgba = Image.new("RGBA", mask.size, (red, green, blue, 0))
    rgba.putalpha(mask)
    buffer = io.BytesIO()
    rgba.save(buffer, format="PNG")
    photo = tk.PhotoImage(master=widget, data=base64.b64encode(buffer.getvalue()))
    try:
        # Visible ink inside the transparent square, used to center icon+title
        # groups on what is actually drawn rather than on the empty box.
        photo._pycode_ink_bbox = mask.point(lambda value: 255 if value >= 64 else 0).getbbox()
    except Exception:
        photo._pycode_ink_bbox = None
    if len(_RASTER_ICON_CACHE) > 256:
        _RASTER_ICON_CACHE.clear()
    _RASTER_ICON_CACHE[key] = photo
    return photo


class _RasterIconLabel(tk.Label):
    _RASTER_KEYS = frozenset(("fg", "foreground", "text", "font"))

    def __init__(self, master, **kwargs):
        self._raster_box = 0
        self._raster_active = False
        self._raster_photo = None
        self._raster_ink_bbox = None
        self._raster_font = kwargs.get("font")
        super().__init__(master, **kwargs)

    def enable_raster(self, box):
        self._raster_box = int(box)
        return self._refresh_raster()

    def _refresh_raster(self):
        if not self._raster_box:
            return False
        try:
            photo = _raster_icon_photo(
                self, str(tk.Label.cget(self, "text")), self._raster_font,
                tk.Label.cget(self, "fg"), self._raster_box,
            )
            if photo is None:
                tk.Label.configure(self, image="", compound="none")
                self._raster_active = False
                return False
            self._raster_photo = photo
            self._raster_ink_bbox = getattr(photo, "_pycode_ink_bbox", None)
            # Tk accepts "none" for an image-only Label; "image" is not a
            # valid compound value and silently forced every raster icon into
            # the font-text fallback instead of using its centered alpha mask.
            tk.Label.configure(self, image=photo, compound="none")
            self._raster_active = True
            return True
        except Exception:
            self._raster_active = False
            return False

    def configure(self, cnf=None, **kwargs):
        options = dict(cnf) if isinstance(cnf, dict) else {}
        options.update(kwargs)
        if "font" in options:
            self._raster_font = options["font"]
        result = tk.Label.configure(self, cnf, **kwargs)
        if self._raster_box and self._RASTER_KEYS.intersection(options):
            self._refresh_raster()
        return result

    config = configure


def create_material_icon_label(
    master, glyph, bg, fg, *, font=None, cursor="arrow", anchor="center",
    padx=0, pady=0, raster=False,
):
    if not glyph:
        return None
    return (_RasterIconLabel if raster else tk.Label)(
        master, text=glyph, bg=bg, fg=fg,
        font=font or MATERIAL_SYMBOL_FONT,
        bd=0, highlightthickness=0, padx=padx, pady=pady,
        anchor=anchor, justify="center", cursor=cursor,
    )


def create_popup_category_heading(
    master, text, icon_name, *, namespace=None,
    font=("Cascadia Mono", 10, "normal", "roman"),
    fg=None, padx=8, pady=(0, 6), gap=6,
):
    bg = COLORS["bg_main"]
    fg = fg or COLORS["popup_category_text"]
    row = tk.Frame(master, bg=bg, bd=0, highlightthickness=0)
    glyph = (
        material_popup_category_symbol(text, namespace)
        if namespace else (material_symbol(icon_name) if icon_name else None)
    )
    if glyph:
        icon_label = create_material_icon_label(
            row, glyph, bg, fg, font=MATERIAL_SYMBOL_FONT, cursor="arrow",
        )
        if icon_label is not None:
            icon_label._pycode_popup_category = True
            icon_label.pack(side="left", padx=(0, ui_px(gap)), anchor="center")
    text_label = tk.Label(
        row, text=text, font=font, bg=bg, fg=fg,
        anchor="w", bd=0, highlightthickness=0,
    )
    text_label._pycode_popup_category = True
    text_label.pack(side="left", anchor="center")
    row.pack(fill="x", padx=ui_px(padx), pady=pady)
    row._pycode_category_icon = icon_label if glyph else None
    row._pycode_category_label = text_label
    return row


def _set_widget_tree_colors(root, bg, fg=None):
    if root is None:
        return
    pending = [root]
    while pending:
        widget = pending.pop()
        try:
            widget.configure(bg=bg)
        except (tk.TclError, AttributeError):
            pass
        if fg is not None:
            try:
                widget.configure(fg=fg)
            except (tk.TclError, AttributeError):
                pass
        try:
            pending.extend(widget.winfo_children())
        except (tk.TclError, AttributeError):
            pass


_SEARCH_GHOST_TEXT_GAP = 5
_SEARCH_GHOST_OUTER_INSET = 5
# Classic Tk Entry keeps a small, physical-pixel left inset even with a flat
# border. Unlike our explicit layout dimensions, Tk's internal inset is not
# passed through ui_px(), so compensate for it without scaling it a second time.
_SEARCH_ENTRY_INTERNAL_INSET = 2


def _search_entry_external_gap():
    target_gap = int(ui_px(_SEARCH_GHOST_TEXT_GAP))
    return max(0, target_gap - _SEARCH_ENTRY_INTERNAL_INSET)


def _search_entry_icon_pack_padding():
    """Outer inset + external gap for a non-overlapping magnifier gutter."""
    return (
        ui_px(_SEARCH_GHOST_OUTER_INSET),
        _dpi_px_from_current_pixels(_search_entry_external_gap()),
    )


_ICON_BEARING_CACHE = {}
_ENTRY_TRIM_CACHE = {}


def _font_pixel_size(widget, font):
    """Return (tkfont.Font, em size in physical pixels) for a Tk font spec."""
    import tkinter.font as tkfont
    actual = tkfont.Font(root=widget, font=font)
    size = float(actual.actual("size"))
    em_px = abs(size) if size < 0 else size * float(widget.winfo_fpixels("1p"))
    return actual, em_px


def _icon_label_right_bearing_px(icon_widget):
    """Blank pixels between a glyph's ink and the right edge of its Label.

    A Label is as wide as the glyph's advance, which for icon fonts includes
    side bearings.  Measuring them keeps the visible magnifier-to-text gap
    equal to the configured gap instead of gap + bearing.
    """
    if icon_widget is None or Image is None:
        return 0
    try:
        text = str(icon_widget.cget("text"))
        status = _EMBEDDED_FONT_STATUS.get("material_symbols", {})
        path = status.get("path")
        if not text or not status.get("loaded") or not path or not os.path.isfile(path):
            return 0
        font, em_px = _font_pixel_size(icon_widget, icon_widget.cget("font"))
        if "cascadia" in str(font.actual("family")).lower():
            return 0
        px = max(1, int(round(em_px)))
        key = (path, text, px)
        cached = _ICON_BEARING_CACHE.get(key)
        if cached is None:
            from PIL import ImageFont
            pil_font = ImageFont.truetype(path, px)
            advance = float(pil_font.getlength(text))
            _left, _top, right, _bottom = pil_font.getbbox(text, anchor="ls")
            cached = int(max(0, math.floor(advance - right)))
            _ICON_BEARING_CACHE[key] = cached
        return int(max(0, min(int(ui_px(6)), cached)))
    except Exception:
        return 0


def _entry_optical_trim_px(widget, font, body_ratio=0.30):
    """Pixels to lift a native Entry's text line so it reads as centered.

    Tk centers the (ascent + descent) box, which puts the baseline
    (ascent - descent) / 2 below the Entry's middle.  Glyph bodies only reach
    about ``body_ratio`` em above the baseline, so fonts with a tall ascent
    (Cascadia Mono on Windows) look 1-2 px too low.  The correction comes from
    the real font metrics, so it scales with DPI and is 0 for fonts that are
    already optically centered.  The caret is part of the same text line, so
    text, placeholder and caret always move together.
    """
    try:
        font_obj, em_px = _font_pixel_size(widget, font)
        key = (
            str(font_obj.actual("family")), str(font_obj.actual("weight")),
            round(em_px, 2), round(float(body_ratio), 3),
        )
        cached = _ENTRY_TRIM_CACHE.get(key)
        if cached is None:
            metrics = font_obj.metrics()
            trim = (float(metrics["ascent"]) - float(metrics["descent"])) / 2.0 - body_ratio * em_px
            cached = int(max(0, min(int(ui_px(3)), int(trim + 0.5))))
            _ENTRY_TRIM_CACHE[key] = cached
        return cached
    except Exception:
        return 0


_TITLE_INK_REFERENCE = "FileEditCodeToolInfo"
_TITLE_LIFT_CACHE = {}


def _title_ink_lift_px(widget, font):
    """Signed pixels to raise a Tk title so its glyph ink is vertically centered.

    Tk centers the font box (ascent + descent). The real ink of the launcher
    titles runs from the ascender/cap height down to the baseline, so the ink
    center sits at a measured distance from the box center. The distance comes
    from the actual font file at the actual physical size, so it is right at any
    DPI; without the font file it falls back to the Entry metric estimate.
    """
    try:
        font_obj, em_px = _font_pixel_size(widget, font)
        metrics = font_obj.metrics()
        ascent, descent = float(metrics["ascent"]), float(metrics["descent"])
        key = (str(font_obj.actual("family")), str(font_obj.actual("weight")),
               round(em_px, 2), int(ascent), int(descent))
        cached = _TITLE_LIFT_CACHE.get(key)
        if cached is not None:
            return cached
        lift = None
        font_path = _EMBEDDED_FONT_STATUS.get("regular", {}).get("path")
        if (Image is not None and font_path and os.path.isfile(font_path)
                and "cascadia" in str(font_obj.actual("family")).lower()):
            from PIL import ImageFont
            pil_font = ImageFont.truetype(font_path, max(1, int(round(em_px))))
            _x0, top, _x1, bottom = pil_font.getbbox(_TITLE_INK_REFERENCE, anchor="ls")
            ink_center = ascent + (top + bottom) / 2.0
            # Ink below the box center -> positive lift (raise the text).
            lift = int(round(ink_center - (ascent + descent) / 2.0))
        if lift is None:
            lift = int(_entry_optical_trim_px(widget, font, body_ratio=0.33))
        lift = max(-int(ui_px(3)), min(int(ui_px(3)), lift))
        _TITLE_LIFT_CACHE[key] = lift
        return lift
    except Exception:
        return 0


def _entry_optical_trim_pady(widget, font, body_ratio=0.30):
    """Return bottom padding that lifts the Entry line by the measured pixels.

    Font metrics are already reported in physical pixels. Mark the resulting
    padding accordingly so the DPI-aware pack wrapper does not scale it twice.
    The Entry text and insertion caret share this native line and stay aligned.
    """
    trim_px = _entry_optical_trim_px(widget, font, body_ratio=body_ratio)
    return (0, _dpi_px_from_current_pixels(2 * trim_px))


def _search_entry_optical_trim_pady(widget, font, body_ratio=0.30):
    """Use a one-logical-pixel smaller lift for search text and its ghost."""
    trim_px = max(
        0,
        int(_entry_optical_trim_px(widget, font, body_ratio=body_ratio))
        - int(ui_px(1)),
    )
    return (0, _dpi_px_from_current_pixels(2 * trim_px))


class _SearchEntryPlaceholder:
    """Native Entry placeholder: text and caret share Tk's exact text layout."""

    def __init__(self, entry, query_variable, placeholder):
        self.entry = entry
        self.query_variable = query_variable
        self.placeholder = str(placeholder)
        self.display_variable = tk.StringVar(master=entry, value="")
        self._placeholder_active = False
        self._syncing = False
        self._restore_job = None

        entry.configure(textvariable=self.display_variable)
        self.display_variable.trace_add("write", self._on_display_changed)
        query_variable.trace_add("write", self._on_query_changed)
        entry.bind("<KeyPress>", self._before_keypress, add="+")
        entry.bind("<<Paste>>", self._before_paste, add="+")
        for sequence in ("<<SelectAll>>", "<<Copy>>", "<<Cut>>"):
            entry.bind(sequence, self._prevent_placeholder_selection, add="+")
        entry.bind("<Button-2>", self._before_middle_paste, add="+")
        entry.bind("<Button-1>", self._after_click, add="+")
        entry.bind("<B1-Motion>", self._prevent_placeholder_selection, add="+")
        entry.bind("<Shift-Button-1>", self._prevent_placeholder_selection, add="+")
        entry.bind("<Double-Button-1>", self._prevent_placeholder_selection, add="+")
        entry.bind("<Triple-Button-1>", self._prevent_placeholder_selection, add="+")
        entry.bind("<FocusIn>", self._after_focus_in, add="+")
        entry.bind("<FocusOut>", self._after_focus_out, add="+")
        self.refresh_from_query()

    @property
    def placeholder_active(self):
        return bool(self._placeholder_active)

    def _entry_exists(self):
        try:
            return bool(self.entry.winfo_exists())
        except tk.TclError:
            return False

    def _set_display(self, value, placeholder_active):
        value = str(value)
        self._syncing = True
        try:
            self._placeholder_active = bool(placeholder_active)
            if self.display_variable.get() != value:
                self.display_variable.set(value)
        finally:
            self._syncing = False
        self.apply_style()
        if self._placeholder_active:
            self._schedule_caret_to_start()

    def refresh_from_query(self):
        """Synchronize display text after programmatic query/focus/theme changes."""
        try:
            value = self.query_variable.get()
        except tk.TclError:
            value = ""
        is_empty = not bool(value)
        display = self.placeholder if is_empty else value
        if (self.display_variable.get() != display
                or self._placeholder_active != is_empty):
            self._set_display(display, is_empty)
        else:
            self.apply_style()
        return is_empty

    def _on_query_changed(self, *_args):
        self.refresh_from_query()

    def _on_display_changed(self, *_args):
        if self._syncing:
            return
        value = self.display_variable.get()
        if self._placeholder_active and value == self.placeholder:
            return
        self._placeholder_active = False
        try:
            if self.query_variable.get() != value:
                self.query_variable.set(value)
        except tk.TclError:
            return
        self.apply_style()
        if not value:
            self._schedule_restore_if_empty()

    def _clear_placeholder_for_input(self):
        if not self._placeholder_active:
            return
        self._syncing = True
        try:
            self._placeholder_active = False
            self.display_variable.set("")
        finally:
            self._syncing = False
        self.apply_style()

    def _before_keypress(self, event):
        if not self._placeholder_active:
            return None
        keysym = str(getattr(event, "keysym", ""))
        lowered = keysym.lower()
        state = int(getattr(event, "state", 0) or 0)
        control_down = bool(state & 0x4)
        shift_down = bool(state & 0x1)

        # Tab keeps its normal focus traversal, but must never preserve a
        # selection range over the visual placeholder while leaving the Entry.
        if keysym in ("Tab", "ISO_Left_Tab"):
            self._clear_placeholder_selection()
            return None
        # Backspace/Delete on an empty query must not eat the visible hint.
        if keysym in ("BackSpace", "Delete", "KP_Delete"):
            return "break"
        # Cursor navigation must not move into non-data placeholder characters.
        if keysym in ("Left", "Right", "Home", "End", "KP_Left", "KP_Right", "KP_Home", "KP_End"):
            self._schedule_caret_to_start()
            return "break"
        # Select-all/copy/cut have no user data to operate on while the hint is shown.
        if control_down and lowered == "a":
            self._schedule_caret_to_start()
            return "break"
        if control_down and lowered in ("c", "x"):
            return "break"
        # Clipboard paste must replace the hint, never append after it.
        if ((control_down and lowered == "v")
                or (shift_down and keysym == "Insert")):
            self._clear_placeholder_for_input()
            self._schedule_restore_if_empty()
            return None
        char = getattr(event, "char", "")
        if char and char.isprintable():
            self._clear_placeholder_for_input()
        return None

    def _before_paste(self, _event=None):
        if self._placeholder_active:
            self._clear_placeholder_for_input()
        self._schedule_restore_if_empty()
        return None

    def _before_middle_paste(self, _event=None):
        if self._placeholder_active:
            self._clear_placeholder_for_input()
            try:
                self.entry.icursor(0)
            except tk.TclError:
                pass
        self._schedule_restore_if_empty()
        return None

    def _schedule_restore_if_empty(self):
        if self._restore_job is not None or not self._entry_exists():
            return
        try:
            self._restore_job = self.entry.after_idle(self._restore_if_empty)
        except tk.TclError:
            self._restore_job = None

    def _restore_if_empty(self):
        self._restore_job = None
        if not self._entry_exists():
            return
        try:
            if not self.display_variable.get() and not self.query_variable.get():
                self._set_display(self.placeholder, True)
        except tk.TclError:
            pass

    def _schedule_caret_to_start(self):
        if not self._entry_exists():
            return
        try:
            self.entry.after_idle(self._place_caret_before_placeholder)
        except tk.TclError:
            pass

    def _place_caret_before_placeholder(self):
        if not self._entry_exists() or not self._placeholder_active:
            return
        try:
            if self.entry.focus_get() is self.entry:
                self.entry.selection_clear()
                self.entry.icursor(0)
                self.entry.xview_moveto(0)
        except tk.TclError:
            pass

    def _clear_placeholder_selection(self):
        """Clear any range over the visible hint, even while focus is leaving."""
        if not self._entry_exists() or not self._placeholder_active:
            return
        try:
            self.entry.selection_clear()
            self.entry.icursor(0)
            self.entry.xview_moveto(0)
        except tk.TclError:
            pass

    def _prevent_placeholder_selection(self, _event=None):
        """Keep the visual hint out of mouse and virtual-event selections."""
        if not self._placeholder_active:
            return None
        self._clear_placeholder_selection()
        self._schedule_caret_to_start()
        return "break"

    def _after_click(self, _event=None):
        if self._placeholder_active:
            self._schedule_caret_to_start()
        return None

    def _after_focus_in(self, _event=None):
        self.refresh_from_query()
        if self._placeholder_active:
            self._schedule_caret_to_start()

    def _after_focus_out(self, _event=None):
        if self._placeholder_active:
            # Tk can retain an Entry selection after Tab/Shift+Tab changes focus.
            # Clear it without requiring the Entry to remain focused.
            self._clear_placeholder_selection()
        if not self.display_variable.get() and not self.query_variable.get():
            self._schedule_restore_if_empty()
        self.apply_style()

    def apply_style(self):
        """Keep placeholder muted and all user-entered text theme-foreground."""
        if not self._entry_exists():
            return
        try:
            foreground = COLORS["info_text"] if self._placeholder_active else COLORS["fg_strong"]
            self.entry.configure(
                fg=foreground,
                insertbackground=COLORS["fg_caret"],
                selectbackground=COLORS.get("select_bg", COLORS["info_text"]),
                selectforeground=COLORS.get("select_fg", COLORS["info_bg"]),
            )
        except (tk.TclError, KeyError):
            pass


def create_search_ghost(master, text, bg=None):
    """Create only the compact search icon; placeholder text lives in its Entry."""
    bg = bg or COLORS["info_bg"]
    frame = tk.Frame(master, bg=bg, bd=0, highlightthickness=0, cursor="xterm")
    glyph = material_element_symbol(
        "search.placeholder", fallback_name=ICON_CONFIG["search_fields"]["placeholder"]
    )
    if glyph:
        icon_label = create_material_icon_label(
            frame, glyph, bg, COLORS["info_text"], cursor="xterm",
        )
    else:
        icon_label = tk.Label(
            frame, text="⌕", bg=bg, fg=COLORS["info_text"],
            font=("Segoe UI Symbol", 12, "normal"),
            bd=0, highlightthickness=0, padx=0, pady=0,
            anchor="center", justify="center", cursor="xterm",
        )
    icon_label.pack(side="left", padx=0, pady=0, anchor="center")
    # The Entry itself renders the ghost, so Tk positions its insertion cursor
    # in front of the hint and uses identical font metrics for both text states.
    return frame, icon_label, None


def resource_path(relative_path):
    relative_path = os.fspath(relative_path)

    try:
        base_path = os.path.dirname(os.path.abspath(__file__))
        candidate = os.path.join(base_path, relative_path)
        if os.path.exists(candidate):
            return candidate
    except Exception:
        pass

    try:
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            candidate = os.path.join(meipass, relative_path)
            if os.path.exists(candidate):
                return candidate
    except Exception:
        pass

    return os.path.abspath(relative_path)


# Python file association
PYCODE_FILE_PROGID = "PyCode.PythonFile.1"
PYCODE_FILE_ICON_NAME = "PyCode_File.ico"


def _pycode_file_association_paths():
    if sys.platform != "win32":
        return None

    try:
        local_appdata = os.environ.get("LOCALAPPDATA") or os.path.expanduser("~\\AppData\\Local")
        icon_dir = os.path.join(local_appdata, "PyCode")
        os.makedirs(icon_dir, exist_ok=True)
        persistent_icon = os.path.join(icon_dir, PYCODE_FILE_ICON_NAME)
    except Exception:
        return None

    source_icon = resource_path(PYCODE_FILE_ICON_NAME)
    return source_icon, persistent_icon


def _install_persistent_file_icon():
    paths = _pycode_file_association_paths()
    if not paths:
        return None

    source_icon, persistent_icon = paths
    if not os.path.isfile(source_icon):
        return None

    try:
        needs_copy = True
        if os.path.isfile(persistent_icon):
            try:
                needs_copy = (
                    os.path.getsize(source_icon) != os.path.getsize(persistent_icon) or
                    int(os.path.getmtime(source_icon)) != int(os.path.getmtime(persistent_icon))
                )
            except OSError:
                needs_copy = True

        if needs_copy:
            shutil.copyfile(source_icon, persistent_icon)
        return persistent_icon
    except (OSError, IOError):
        return None


def _get_current_py_default_progid():
    if sys.platform != "win32":
        return None

    try:
        import winreg
        key_path = (
            r"Software\Microsoft\Windows\CurrentVersion"
            r"\Explorer\FileExts\.py\UserChoice"
        )
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path, 0, winreg.KEY_READ)
        try:
            value, _ = winreg.QueryValueEx(key, "ProgId")
            return str(value).strip() or None
        finally:
            winreg.CloseKey(key)
    except (FileNotFoundError, OSError, TypeError, ValueError):
        return None


def register_py_file_association():
    if sys.platform != "win32":
        return False

    icon_path = _install_persistent_file_icon()
    if not icon_path:
        return False

    try:
        import winreg

        if getattr(sys, "frozen", False):
            command = f'"{os.path.abspath(sys.executable)}" "%1"'
            application_name = os.path.basename(sys.executable)
        else:
            script_path = os.path.abspath(__file__)
            command = f'"{os.path.abspath(sys.executable)}" "{script_path}" "%1"'
            application_name = os.path.basename(script_path)

        classes_root = r"Software\Classes"
        progid_root = classes_root + "\\" + PYCODE_FILE_PROGID
        app_key_root = classes_root + "\\Applications\\" + application_name
        changed = False

        def set_value(key_path, name, value):
            nonlocal changed
            try:
                with winreg.OpenKey(winreg.HKEY_CURRENT_USER, key_path, 0, winreg.KEY_READ) as key:
                    current, _kind = winreg.QueryValueEx(key, name)
                if current == value:
                    return
            except OSError:
                pass
            with winreg.CreateKeyEx(
                winreg.HKEY_CURRENT_USER, key_path, 0, winreg.KEY_WRITE
            ) as key:
                winreg.SetValueEx(key, name, 0, winreg.REG_SZ, value)
            changed = True

        set_value(progid_root, "", "Python file (PyCode)")
        set_value(progid_root + r"\DefaultIcon", "", icon_path)
        set_value(progid_root + r"\shell\open\command", "", command)
        set_value(classes_root + r"\.py\OpenWithProgids", PYCODE_FILE_PROGID, "")
        set_value(app_key_root + r"\shell\open\command", "", command)
        set_value(app_key_root + r"\DefaultIcon", "", icon_path)
        set_value(app_key_root + r"\SupportedTypes", ".py", "")

        if changed:
            try:
                ctypes.windll.shell32.SHChangeNotify(
                    0x08000000,
                    0x0000,
                    None,
                    None,
                )
            except Exception:
                pass

        default_progid = _get_current_py_default_progid()
        return {
            "registered": True,
            "pycode_is_default": default_progid in (
                PYCODE_FILE_PROGID, "Applications\\" + application_name
            ),
            "default_progid": default_progid,
        }
    except Exception:
        return False


def _find_embedded_font(style):
    for filename in EMBEDDED_FONT_ASSETS.get(style, ()):
        path = resource_path(filename)
        if os.path.isfile(path):
            return filename, path
    return None, None


def load_embedded_font():
    global MATERIAL_SYMBOL_FONT
    _EMBEDDED_FONT_STATUS.clear()
    fontconfig_cache_dirty = False

    for style, _candidates in EMBEDDED_FONT_ASSETS.items():
        font_file, font_path = _find_embedded_font(style)
        if not font_path:
            _EMBEDDED_FONT_STATUS[style] = {
                "loaded": False,
                "filename": None,
                "path": None,
                "error": "resource not found",
            }
            continue

        loaded = False
        error = None
        try:
            if sys.platform == "win32":
                import ctypes
                count = int(ctypes.windll.gdi32.AddFontResourceExW(
                    font_path, 0x10, None
                ))
                loaded = count > 0
                if not loaded:
                    error = "AddFontResourceExW returned 0"
            elif sys.platform == "darwin":
                import ctypes, ctypes.util
                ct = ctypes.cdll.LoadLibrary(ctypes.util.find_library("CoreText"))
                cf = ctypes.cdll.LoadLibrary(ctypes.util.find_library("CoreFoundation"))
                encoded = os.fsencode(font_path)
                url = cf.CFURLCreateFromFileSystemRepresentation(
                    None, encoded, len(encoded), False
                )
                if url:
                    loaded = bool(ct.CTFontManagerRegisterFontsForURL(url, 1, None))
                    cf.CFRelease(url)
                if not loaded:
                    error = "CTFontManagerRegisterFontsForURL failed"
            else:
                import shutil
                font_dir = os.path.expanduser("~/.local/share/fonts")
                os.makedirs(font_dir, exist_ok=True)
                dest = os.path.join(font_dir, font_file)
                needs_copy = not os.path.isfile(dest)
                if not needs_copy:
                    try:
                        needs_copy = (
                            os.path.getsize(dest) != os.path.getsize(font_path) or
                            int(os.path.getmtime(dest)) != int(os.path.getmtime(font_path))
                        )
                    except OSError:
                        needs_copy = True
                if needs_copy:
                    shutil.copy2(font_path, dest)
                    fontconfig_cache_dirty = True
                loaded = os.path.isfile(dest)
                if not loaded:
                    error = "font copy failed"
        except Exception as exc:
            error = f"{type(exc).__name__}: {exc}"

        _EMBEDDED_FONT_STATUS[style] = {
            "loaded": bool(loaded),
            "filename": font_file,
            "path": font_path,
            "error": error,
        }
        if style == "material_symbols" and loaded:
            material_family = _read_ttf_legacy_family_name(font_path)
            if not material_family:
                material_family = "Material Symbols Sharp Filled"
            MATERIAL_SYMBOL_FONT = (material_family, 11, "normal", "roman")
            _EMBEDDED_FONT_STATUS[style]["tk_family"] = material_family

    if fontconfig_cache_dirty:
        try:
            import subprocess
            fc_cache = shutil.which("fc-cache")
            if fc_cache:
                subprocess.run(
                    [fc_cache, "-f"], stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL, timeout=20, check=False,
                )
        except Exception:
            pass


