THEME_PALETTES = {THEME_DARK: _PALETTE_DARK, THEME_GLOW: _PALETTE_GLOW}


_THEME_PREFERENCE_MEMORY = DEFAULT_THEME_PREFERENCE
_THEME_REGISTRY_KEY = r"Software\PyCode"
_THEME_REGISTRY_VALUE = "Theme"


def load_theme_preference():
    if sys.platform == "win32":
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _THEME_REGISTRY_KEY, 0, winreg.KEY_READ) as key:
                name, _value_type = winreg.QueryValueEx(key, _THEME_REGISTRY_VALUE)
            return name if name in THEME_ORDER else DEFAULT_THEME_PREFERENCE
        except (OSError, ImportError, ValueError, TypeError):
            pass
    name = _THEME_PREFERENCE_MEMORY
    return name if name in THEME_ORDER else DEFAULT_THEME_PREFERENCE


def save_theme_preference(name):
    global _THEME_PREFERENCE_MEMORY
    if name not in THEME_ORDER:
        return False
    if sys.platform == "win32":
        try:
            import winreg
            with winreg.CreateKeyEx(
                winreg.HKEY_CURRENT_USER, _THEME_REGISTRY_KEY, 0, winreg.KEY_SET_VALUE
            ) as key:
                winreg.SetValueEx(key, _THEME_REGISTRY_VALUE, 0, winreg.REG_SZ, name)
            _THEME_PREFERENCE_MEMORY = name
            return True
        except (OSError, ImportError, ValueError, TypeError):
            return False
    _THEME_PREFERENCE_MEMORY = name
    return True


_SETTINGS_REGISTRY_VALUE = "Settings"
_SETTINGS_MEMORY = {}
_SETTINGS_SCHEMA = {
    "autocomplete_enabled": (bool, True),
    "auto_pairing_enabled": (bool, True),
    "console_auto_pairing_enabled": (bool, True),
    "highlight_effects_enabled": (bool, True),
    "show_shortcut_hint": (bool, False),
    "show_console_run_init_message": (bool, True),
    "_root_console_size_mode": (str, "OFF"),
    "_terminal_size_mode": (str, "OFF"),
}
_SIZE_MODE_CHOICES = ("OFF", "x1", "x2", "x3", "FS")


def _sanitize_settings(raw):
    clean = {}
    if not isinstance(raw, dict):
        return clean
    for key, (kind, _default) in _SETTINGS_SCHEMA.items():
        value = raw.get(key)
        if kind is bool and isinstance(value, bool):
            clean[key] = value
        elif kind is str and value in _SIZE_MODE_CHOICES:
            clean[key] = value
    return clean


def load_app_settings():
    if sys.platform == "win32":
        try:
            import winreg, json
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _THEME_REGISTRY_KEY, 0, winreg.KEY_READ) as key:
                text, _value_type = winreg.QueryValueEx(key, _SETTINGS_REGISTRY_VALUE)
            return _sanitize_settings(json.loads(text))
        except (OSError, ImportError, ValueError, TypeError):
            pass
    return dict(_SETTINGS_MEMORY)


def save_app_settings(values):
    clean = _sanitize_settings(values)
    if sys.platform == "win32":
        try:
            import winreg, json
            payload = json.dumps(clean, separators=(",", ":"), sort_keys=True)
            with winreg.CreateKeyEx(
                winreg.HKEY_CURRENT_USER, _THEME_REGISTRY_KEY, 0, winreg.KEY_SET_VALUE
            ) as key:
                winreg.SetValueEx(key, _SETTINGS_REGISTRY_VALUE, 0, winreg.REG_SZ, payload)
        except (OSError, ImportError, ValueError, TypeError):
            return False
    _SETTINGS_MEMORY.clear()
    _SETTINGS_MEMORY.update(clean)
    return True


def detect_system_theme():
    try:
        if sys.platform == "win32":
            import winreg
            with winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize",
                0, winreg.KEY_READ,
            ) as key:
                value, _value_type = winreg.QueryValueEx(key, "AppsUseLightTheme")
            return THEME_GLOW if int(value) else THEME_DARK
        import subprocess
        if sys.platform == "darwin":
            result = subprocess.run(
                ["defaults", "read", "-g", "AppleInterfaceStyle"],
                capture_output=True, text=True, timeout=1.5,
            )
            return THEME_DARK if (result.returncode == 0 and "dark" in result.stdout.lower()) else THEME_GLOW
        for key_name in ("color-scheme", "gtk-theme"):
            try:
                result = subprocess.run(
                    ["gsettings", "get", "org.gnome.desktop.interface", key_name],
                    capture_output=True, text=True, timeout=1.5,
                )
            except (OSError, subprocess.SubprocessError):
                break
            answer = result.stdout.strip().strip("'\"").lower()
            if result.returncode != 0 or not answer:
                continue
            if "dark" in answer:
                return THEME_DARK
            if answer == "prefer-light" or key_name == "gtk-theme":
                return THEME_GLOW
        gtk_theme = os.environ.get("GTK_THEME", "").lower()
        if gtk_theme:
            return THEME_DARK if "dark" in gtk_theme else THEME_GLOW
    except Exception:
        pass
    return DEFAULT_THEME


def resolve_theme(preference):
    if preference == THEME_SYSTEM:
        return detect_system_theme()
    return preference if preference in THEME_PALETTES else DEFAULT_THEME


def build_palette(theme_name):
    palette = dict(_PALETTE_DARK)
    overrides = THEME_PALETTES.get(theme_name)
    if overrides is not None and overrides is not _PALETTE_DARK:
        palette.update(overrides)
    return palette


THEME_PREFERENCE = load_theme_preference()
ACTIVE_THEME = resolve_theme(THEME_PREFERENCE)
IS_LIGHT_THEME = ACTIVE_THEME != THEME_DARK
COLORS = build_palette(ACTIVE_THEME)

PYCODE_VERSION = "6.95"
VERSION = f"v.{PYCODE_VERSION}"
FONT_MAIN = ("Cascadia Mono", 11, "normal", "roman")
FONT_CONSOLE = ("Cascadia Mono", 10, "normal", "roman")
MAX_EDITOR_LINES = 999_999
MAX_PASTE_CHARACTERS = 100_000
MAX_CONSOLE_PASTE_CHARACTERS = 4_096
PYTHON_INDENT_UNIT = "    "

LARGE_DOCUMENT_LINE_THRESHOLD = 350
LARGE_DOCUMENT_CHAR_THRESHOLD = 35_000
LARGE_DOCUMENT_CONTEXT_LINES = 20
HUGE_DOCUMENT_LINE_THRESHOLD = 3_000
HUGE_DOCUMENT_CHAR_THRESHOLD = 150_000
LARGE_DOCUMENT_VIEW_CONTEXT_LINES = 20
LARGE_DOCUMENT_BRACKET_CONTEXT_LINES = 40
LARGE_DOCUMENT_MAX_OCCURRENCES = 250
LARGE_DOCUMENT_BACKGROUND_BUDGET_MS = 2.5
LARGE_DOCUMENT_BACKGROUND_MAX_TOKENS = 800
LARGE_DOCUMENT_BACKGROUND_DEBOUNCE_MS = 75
LARGE_DOCUMENT_BACKGROUND_IDLE_MS = 900
LARGE_LOCAL_WINDOW_MAX_LINES = 220
