LARGE_PASTE_CHAR_THRESHOLD = 150_000
LARGE_PASTE_LINE_THRESHOLD = 1_000


_LIGHTEN_CACHE = {}


def lighten_color(color, amount=0.32):
    if not isinstance(color, str) or not color.startswith("#") or len(color) != 7:
        return COLORS["white"]
    key = (color, amount)
    cached = _LIGHTEN_CACHE.get(key)
    if cached is not None:
        return cached
    try:
        r = int(color[1:3], 16)
        g = int(color[3:5], 16)
        b = int(color[5:7], 16)
    except ValueError:
        return COLORS["white"]

    amt = max(0.0, min(1.0, amount))
    r = round(r + (255 - r) * amt)
    g = round(g + (255 - g) * amt)
    b = round(b + (255 - b) * amt)
    result = f"#{r:02X}{g:02X}{b:02X}"
    _LIGHTEN_CACHE[key] = result
    return result


def _hex_rgb(color, widget=None):
    if isinstance(color, str) and color.startswith("#") and len(color) == 7:
        try:
            return tuple(int(color[i:i + 2], 16) for i in (1, 3, 5))
        except ValueError:
            return None
    if widget is not None:
        cacheable = isinstance(color, str) and not color.startswith("System")
        if cacheable:
            hit = _NAMED_RGB_CACHE.get(color)
            if hit is not None:
                return hit
        try:
            r16, g16, b16 = widget.winfo_rgb(color)
            rgb = (r16 // 257, g16 // 257, b16 // 257)
        except Exception:
            return None
        if cacheable:
            _NAMED_RGB_CACHE[color] = rgb
        return rgb
    return None


_NAMED_RGB_CACHE = {}
_COLOR_MIX_CACHE = {}


def _is_plain_hex(color):
    return isinstance(color, str) and color.startswith("#") and len(color) == 7


def tooltip_display_text(text):
    raw = str(text if text is not None else "").replace("\r\n", "\n").replace("\r", "\n")
    cleaned = []
    for raw_line in raw.split("\n"):
        line = re.sub(r"[ \t]+", " ", raw_line.strip())
        while line.endswith((".", ",", ";")):
            line = line[:-1].rstrip()
        if line:
            cleaned.append(line)
        elif cleaned and cleaned[-1] != "":
            cleaned.append("")
    while cleaned and not cleaned[0]:
        cleaned.pop(0)
    while cleaned and not cleaned[-1]:
        cleaned.pop()
    return "\n".join(cleaned)


_TOOLTIP_EMPHASIS_RE = re.compile(
    r"\[(yellow|blue|cyan|orange|green|red|purple|magenta|pink|gray|white)\](.*?)\[/\1\]",
    re.DOTALL | re.IGNORECASE,
)
_TOOLTIP_COLOR_PALETTE_KEYS = {
    "yellow": "ansi_bright_yellow",
    "blue": "ansi_bright_blue",
    "cyan": "ansi_bright_cyan",
    "orange": "syn_keyword",
    "green": "ansi_bright_green",
    "red": "ansi_bright_red",
    "purple": "syn_class",
    "magenta": "ansi_bright_magenta",
    "pink": "regex_group_name",
    "gray": "ansi_bright_black",
    "white": "ansi_bright_white",
}
_TOOLTIP_TEXT_FONT = ("Cascadia Mono", 8, "normal", "roman")
_TOOLTIP_WRAP_WIDTH = 54


def _tooltip_rich_content(text):
    display = tooltip_display_text(text)
    chunks = []
    spans = []
    offset = 0
    cursor = 0
    for match in _TOOLTIP_EMPHASIS_RE.finditer(display):
        prefix = display[cursor:match.start()]
        if prefix:
            chunks.append(prefix)
            offset += len(prefix)
        emphasized = match.group(2)
        if emphasized:
            start = offset
            chunks.append(emphasized)
            offset += len(emphasized)
            tag = f"tooltip_{match.group(1).lower()}"
            spans.append((start, offset, tag))
        cursor = match.end()
    suffix = display[cursor:]
    if suffix:
        chunks.append(suffix)

    plain_text = "".join(chunks) or " "
    wrapped_lines = []
    for paragraph in plain_text.split("\n"):
        if not paragraph:
            wrapped_lines.append("")
        else:
            wrapped_lines.extend(textwrap.wrap(
                paragraph, width=_TOOLTIP_WRAP_WIDTH, break_long_words=True,
                break_on_hyphens=False, replace_whitespace=False,
            ) or [""])
    width = max(1, min(_TOOLTIP_WRAP_WIDTH, max((len(line) for line in wrapped_lines), default=1)))
    height = max(1, len(wrapped_lines))
    return plain_text, spans, width, height


def tooltip_create_rich_text(parent, text, *, background=None, justify="left"):
    bg = background or COLORS["breadcrumb_tooltip_bg"]
    text_widget = tk.Text(
        parent, bg=bg, fg=COLORS["tooltip_fg"], font=_TOOLTIP_TEXT_FONT,
        width=1, height=1, wrap="word",
        relief="flat", borderwidth=0, highlightthickness=0,
        padx=ui_px(6), pady=0, spacing1=0, spacing2=0, spacing3=0,
        cursor="arrow", takefocus=0, exportselection=False,
    )
    tooltip_update_rich_text(text_widget, text, background=bg, justify=justify)
    return text_widget


_TOOLTIP_SHORTCUT_GAP = "\u00a0\u00a0\u00a0"


def tooltip_with_shortcut(title, shortcut):
    """Tooltip text: title, then the shortcut in gray on the line below.

    With an empty title only the shortcut is shown (dropdown launchers).
    """
    shortcut = str(shortcut or "").strip()
    title = str(title or "").strip()
    if not shortcut:
        return title
    if not title:
        return f"[gray]{shortcut}[/gray]"
    return f"{title}\n[gray]{shortcut}[/gray]"


def tooltip_rich_text_pady(widget):
    """Asymmetric pady (top, bottom) that centers the ink of the tooltip text.

    Tk centers the ascent+descent box, not the glyph bodies. The offset between the
    two comes from the real font file (same measure as the launcher titles), so the
    text reads vertically centered in the frame whatever the DPI. The padding is
    kept small (2 px each side before the optical correction).
    """
    base = int(ui_px(2))
    try:
        lift = int(_title_ink_lift_px(widget, _TOOLTIP_TEXT_FONT))
    except Exception:
        lift = 0
    lift = max(-base, min(base, lift))
    return (_dpi_px_from_current_pixels(base - lift), _dpi_px_from_current_pixels(base + lift))


def tooltip_update_rich_text(widget, text, *, background=None, justify="left"):
    plain_text, spans, width, height = _tooltip_rich_content(text)
    try:
        bg = background or COLORS["breadcrumb_tooltip_bg"]
        widget.configure(
            bg=bg,
            fg=COLORS["tooltip_fg"],
            font=_TOOLTIP_TEXT_FONT,
            width=width,
            height=height,
            wrap="word",
        )
        for color_name, palette_key in _TOOLTIP_COLOR_PALETTE_KEYS.items():
            widget.tag_configure(
                f"tooltip_{color_name}",
                foreground=COLORS.get(palette_key, COLORS["tooltip_fg"]),
            )
        alignment = "center" if str(justify).lower() == "center" else "left"
        widget.tag_configure("pycode_tooltip_center", justify=alignment)
        widget.configure(state="normal")
        widget.delete("1.0", "end")
        widget.insert("1.0", plain_text)
        widget.tag_add("pycode_tooltip_center", "1.0", "end-1c")
        for start, end, tag in spans:
            widget.tag_add(tag, f"1.0+{start}c", f"1.0+{end}c")
        widget.configure(state="disabled")
    except tk.TclError:
        pass


def color_mix(color_a, color_b, amount_b=0.5, widget=None):
    amount_b = max(0.0, min(1.0, float(amount_b)))

    cacheable = _is_plain_hex(color_a) and _is_plain_hex(color_b)
    if cacheable:
        cache_key = (color_a, color_b, amount_b)
        cached = _COLOR_MIX_CACHE.get(cache_key)
        if cached is not None:
            return cached

    rgb_a = _hex_rgb(color_a, widget)
    rgb_b = _hex_rgb(color_b, widget)
    if rgb_a is None or rgb_b is None:
        return color_a
    rgb = tuple(round(a * (1.0 - amount_b) + b * amount_b) for a, b in zip(rgb_a, rgb_b))
    result = "#%02X%02X%02X" % rgb

    if cacheable:
        _COLOR_MIX_CACHE[cache_key] = result
    return result


def notification_error_border_color(error_bg):
    """Inner border of the danger notification: a lighter red than the body,
    so the card edge reads clearly against the red fill and the dark outline."""
    return color_mix(error_bg, "#FFFFFF", 0.38)


# One darkening strength and one colour function for every modal / menu overlay.
# Every place that paints a "dimmed" colour goes through modal_dim_color().
MODAL_DIM_AMOUNT = 0.48


_MODAL_RECOLOR_ENABLED = True


def _set_modal_recolor(enabled):
    """Off while a translucent overlay darkens the window: colours stay untouched."""
    global _MODAL_RECOLOR_ENABLED
    _MODAL_RECOLOR_ENABLED = bool(enabled)


def modal_dim_color(color, widget=None, amount=None):
    """The unique darkening used while a modal window dims the editor."""
    if amount is None and not _MODAL_RECOLOR_ENABLED:
        return color
    return color_mix(color, "#000000",
                     MODAL_DIM_AMOUNT if amount is None else amount, widget=widget)


def darken_color(color, amount=MODAL_DIM_AMOUNT, widget=None):
    return modal_dim_color(color, widget=widget, amount=amount)


def _build_dimmed_logo_rgba(source_image, header_bg, dim_amount=None):
    dim_amount = MODAL_DIM_AMOUNT if dim_amount is None else dim_amount
    if Image is None:
        raise RuntimeError("Pillow is required to dim a transparent logo cleanly")
    rgba = source_image.convert("RGBA")
    source_alpha = rgba.getchannel("A")
    modal_bg = modal_dim_color(header_bg)
    bg_rgb = _hex_rgb(modal_bg, None) or (0, 0, 0)
    black_layer = Image.new("RGB", rgba.size, (0, 0, 0))
    blended_rgb = Image.blend(
        rgba.convert("RGB"), black_layer,
        max(0.0, min(1.0, float(dim_amount))),
    )
    red, green, blue = blended_rgb.split()

    transparent_pixels = source_alpha.point(lambda value: 255 if value == 0 else 0)
    for channel, background_component in zip((red, green, blue), bg_rgb):
        channel.paste(int(background_component), mask=transparent_pixels)

    return Image.merge("RGBA", (red, green, blue, source_alpha))


def _build_dimmed_logo_png_fallback(source_path, header_bg, dim_amount=None):
    dim_amount = MODAL_DIM_AMOUNT if dim_amount is None else dim_amount
    import struct
    import zlib

    with open(source_path, "rb") as source_file:
        data = source_file.read()
    signature = b"\x89PNG\r\n\x1a\n"
    if not data.startswith(signature):
        raise ValueError("Not a PNG image")

    offset = len(signature)
    width = height = bit_depth = color_type = interlace = None
    idat_parts = []
    transparent_rgb = None
    while offset + 12 <= len(data):
        length = struct.unpack(">I", data[offset:offset + 4])[0]
        kind = data[offset + 4:offset + 8]
        start = offset + 8
        end = start + length
        if end + 4 > len(data):
            raise ValueError("Truncated PNG chunk")
        payload = data[start:end]
        if kind == b"IHDR":
            width, height, bit_depth, color_type, compression, filtering, interlace = struct.unpack(
                ">IIBBBBB", payload
            )
            if compression != 0 or filtering != 0:
                raise ValueError("Unsupported PNG encoding")
        elif kind == b"IDAT":
            idat_parts.append(payload)
        elif kind == b"tRNS" and color_type == 2 and len(payload) >= 6:
            transparent_rgb = tuple(value & 0xFF for value in struct.unpack(">HHH", payload[:6]))
        elif kind == b"IEND":
            break
        offset = end + 4

    if (not width or not height or bit_depth != 8 or color_type not in (2, 6)
            or interlace != 0 or not idat_parts):
        raise ValueError("Unsupported PNG format for alpha-preserving fallback")

    channels = 4 if color_type == 6 else 3
    bytes_per_pixel = channels
    stride = width * channels
    inflated = zlib.decompress(b"".join(idat_parts))
    if len(inflated) != height * (stride + 1):
        raise ValueError("Unexpected PNG scanline data size")

    def paeth_predictor(left, up, upper_left):
        estimate = left + up - upper_left
        distances = (abs(estimate - left), abs(estimate - up), abs(estimate - upper_left))
        return (left, up, upper_left)[distances.index(min(distances))]

    rows = []
    previous = bytearray(stride)
    cursor = 0
    for _y in range(height):
        filter_type = inflated[cursor]
        row = bytearray(inflated[cursor + 1:cursor + 1 + stride])
        cursor += stride + 1
        if filter_type not in (0, 1, 2, 3, 4):
            raise ValueError("Unknown PNG row filter")
        for i in range(stride):
            left = row[i - bytes_per_pixel] if i >= bytes_per_pixel else 0
            up = previous[i]
            upper_left = previous[i - bytes_per_pixel] if i >= bytes_per_pixel else 0
            if filter_type == 1:
                predictor = left
            elif filter_type == 2:
                predictor = up
            elif filter_type == 3:
                predictor = (left + up) // 2
            elif filter_type == 4:
                predictor = paeth_predictor(left, up, upper_left)
            else:
                predictor = 0
            row[i] = (row[i] + predictor) & 0xFF
        rows.append(row)
        previous = row

    modal_bg = modal_dim_color(header_bg)
    bg_rgb = _hex_rgb(modal_bg, None) or (0, 0, 0)
    blend = max(0.0, min(1.0, float(dim_amount)))
    rgba_rows = []
    for row in rows:
        rgba_row = bytearray(width * 4)
        for x in range(width):
            src_index = x * channels
            dst_index = x * 4
            red, green, blue = row[src_index:src_index + 3]
            alpha = row[src_index + 3] if color_type == 6 else 255
            if transparent_rgb is not None and (red, green, blue) == transparent_rgb:
                alpha = 0
            rgb = (red, green, blue)
            for channel_index, component in enumerate(rgb):
                if alpha == 0:
                    rgba_row[dst_index + channel_index] = bg_rgb[channel_index]
                else:
                    rgba_row[dst_index + channel_index] = int(round(
                        component * (1.0 - blend)
                    ))
            rgba_row[dst_index + 3] = alpha
        rgba_rows.append(rgba_row)

    def png_chunk(kind, payload):
        body = kind + payload
        return struct.pack(">I", len(payload)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", width, height, 8, 6, 0, 0, 0)
    raw_scanlines = b"".join(b"\x00" + bytes(row) for row in rgba_rows)
    compressed = zlib.compress(raw_scanlines, level=6)
    return (
        signature + png_chunk(b"IHDR", ihdr) + png_chunk(b"IDAT", compressed)
        + png_chunk(b"IEND", b"")
    )


_GLOW_EDGE_STRENGTH = 0.55
_BUTTON_BORDER_STRENGTH = 0.16


def emphasize_color(color, amount=0.20):
    if not IS_LIGHT_THEME:
        return lighten_color(color, amount)
    return color_mix(color, COLORS["edge_target"], min(1.0, amount * _GLOW_EDGE_STRENGTH))


def button_border_color(color, amount=_BUTTON_BORDER_STRENGTH):
    amount = max(0.0, min(0.55, float(amount)))
    if not IS_LIGHT_THEME:
        if abs(amount - 0.16) < 0.002:
            amount = 0.18
        elif abs(amount - 0.18) < 0.002:
            amount = 0.30
        return lighten_color(color, amount)
    # Strengthen only the button's own border.  The outer shadow is still
    # driven by modal_outline and is intentionally left untouched.
    # The extra mix makes the inner border unambiguously visible on pale UI
    # surfaces while keeping it neutral rather than adding a colored outline.
    amount = min(0.58, amount + 0.16)
    target = COLORS.get("edge_target", "#202630")
    return color_mix(color, target, amount)


def _color_luma(color):
    if not isinstance(color, str) or not color.startswith("#") or len(color) != 7:
        return None
    try:
        r, g, b = (int(color[i:i + 2], 16) for i in (1, 3, 5))
    except ValueError:
        return None
    return (0.2126 * r + 0.7152 * g + 0.0722 * b) / 255.0


def hover_border_color(normal_bg, hover_bg, normal_border, base_hover_border):
    normal_luma = _color_luma(normal_bg)
    hover_luma = _color_luma(hover_bg)
    if normal_luma is None or hover_luma is None or hover_luma <= normal_luma + 0.004:
        return base_hover_border
    border_luma = _color_luma(normal_border)
    base_luma = _color_luma(base_hover_border)
    if border_luma is None or base_luma is None or base_luma >= border_luma + 0.03:
        return base_hover_border
    return lighten_color(normal_border, 0.28)


def _saturated_lighten_color(color, lightness_delta=0.10, saturation_gain=1.10):
    try:
        import colorsys
        rgb = tuple(int(color[i:i + 2], 16) / 255.0 for i in (1, 3, 5))
        hue, lightness, saturation = colorsys.rgb_to_hls(*rgb)
        lightness = min(0.94, lightness + max(0.0, float(lightness_delta)))
        saturation = min(1.0, saturation * max(1.0, float(saturation_gain)))
        red, green, blue = colorsys.hls_to_rgb(hue, lightness, saturation)
        return "#%02X%02X%02X" % tuple(round(channel * 255) for channel in (red, green, blue))
    except (TypeError, ValueError, IndexError):
        return lighten_color(color, lightness_delta)


def soft_accent_button_palette(accent_color):
    """Return a restrained accent surface: darker on hover in the light theme, lighter in the dark theme."""
    if IS_LIGHT_THEME:
        normal_bg = color_mix(accent_color, "#000000", 0.10)
        normal_border = color_mix(accent_color, "#000000", 0.30)
        hover_bg = color_mix(normal_bg, "#000000", 0.14)
        hover_border = color_mix(normal_border, "#000000", 0.14)
        if (_color_luma(hover_bg) or 0.0) >= (_color_luma(normal_bg) or 0.0):
            hover_bg = darken_color(normal_bg, 0.14)
        if (_color_luma(hover_border) or 0.0) >= (_color_luma(normal_border) or 0.0):
            hover_border = darken_color(normal_border, 0.14)
        return normal_bg, hover_bg, normal_border, hover_border

    neutral = COLORS["console_button_bg"]
    normal_bg = color_mix(neutral, accent_color, 0.44)
    normal_bg = color_mix(normal_bg, "#000000", 0.13)
    normal_border = color_mix(normal_bg, accent_color, 0.64)
    is_save_accent = str(accent_color).lower() == str(COLORS.get("save_button_accent", "")).lower()
    if is_save_accent:
        normal_border = _saturated_lighten_color(normal_border, 0.10, 1.10)
    hover_tint = _saturated_lighten_color(accent_color, 0.065, 1.10)
    hover_bg = color_mix(normal_bg, hover_tint, 0.22)
    hover_border = _saturated_lighten_color(normal_border, 0.18, 1.14)
    if (_color_luma(hover_bg) or 0.0) <= (_color_luma(normal_bg) or 0.0):
        hover_bg = _saturated_lighten_color(normal_bg, 0.075, 1.08)
    return normal_bg, hover_bg, normal_border, hover_border


def apply_soft_accent_hover_style(button, accent_role, foreground_role=None):
    def refresh():
        try:
            accent = COLORS.get(accent_role, COLORS["ansi_bright_blue"])
            normal_bg, hover_bg, normal_border, hover_border = soft_accent_button_palette(accent)
            normal_fg = COLORS.get(foreground_role, COLORS["fg_strong"])
            disabled_bg = COLORS["console_button_disabled_bg"]
            disabled_fg = COLORS["console_button_disabled_fg"]
            disabled_border = (
                button_border_color(disabled_bg, 0.16) if IS_LIGHT_THEME
                else emphasize_color(disabled_bg, 0.22)
            )
            button._normal_button_bg = normal_bg
            button._normal_button_fg = normal_fg
            button._normal_active_bg = hover_bg
            button._normal_active_fg = normal_fg
            button.normal_border = normal_border
            button.hover_border = hover_border
            button.disabled_bg = disabled_bg
            button.disabled_fg = disabled_fg
            button.disabled_border = disabled_border
            enabled = bool(getattr(button, "_enabled", True))
            hovered = bool(enabled and getattr(button, "_hovered", False))
            shown_bg = (hover_bg if hovered else normal_bg) if enabled else disabled_bg
            shown_fg = normal_fg if enabled else disabled_fg
            shown_border = (hover_border if hovered else normal_border) if enabled else disabled_border
            button.btn.configure(
                state="normal", bg=shown_bg, fg=shown_fg,
                disabledforeground=shown_fg,
                activebackground=(hover_bg if enabled else disabled_bg),
                activeforeground=(normal_fg if enabled else disabled_fg),
                highlightbackground=shown_bg, highlightcolor=shown_bg,
                relief="flat", overrelief="flat", bd=0, highlightthickness=0,
                takefocus=0, default="normal", cursor=(button._normal_cursor if enabled else "arrow"),
            )
            button.configure(bg=COLORS["modal_outline"], cursor="arrow")
            button._button_border_frame.configure(
                bg=shown_border, cursor=(button._normal_cursor if enabled else "arrow")
            )
            button._sync_icon_colors(shown_bg, shown_fg)
            button._sync_modal_dimming()
        except (tk.TclError, AttributeError, TypeError, ValueError):
            pass

    button._pycode_soft_accent_role = str(accent_role)
    button._pycode_theme_roles = {}
    button._pycode_theme_refresh = refresh
    refresh()


def disabled_accent_bg(color, dark_amount=0.5):
    if not IS_LIGHT_THEME:
        return darken_color(color, max(0.0, min(1.0, float(dark_amount))))
    return color_mix(color, COLORS["bg_main"], 0.72)


def disabled_accent_fg(color):
    if not IS_LIGHT_THEME:
        try:
            if str(color).lower() == str(COLORS.get("save_bg", "")).lower():
                return COLORS["save_disabled_fg"]
        except (AttributeError, TypeError):
            pass
        return COLORS["accent_disabled_fg"]
    return COLORS.get("accent_disabled_fg", "#737B88")


# Toolbar buttons
def focus_without_raise(widget):
    try:
        if widget.focus_displayof() is None:
            widget.focus_force()
        else:
            widget.focus_set()
    except tk.TclError:
        pass


SCROLLBAR_MIN_THUMB = 20


def _scrollbar_thumb_canvas_coords(width, height, top, thumb_height, lit=False):
    """Return symmetric, safely inset Canvas coordinates for a scrollbar thumb.

    The one-pixel minimum inset keeps the complete outline inside the Canvas
    clip area.  Left and right insets are always equal, so the thumb is centred
    on the canvas axis (the same axis as the rail) in every state; the idle
    thumb is simply narrower than the hovered one.  Hovering extends the thumb by one
    pixel at the top and at the bottom, symmetrically.
    """
    width = max(4, int(width))
    height = max(4, int(height))
    top_edge = int(round(float(top)))
    bottom_edge = int(round(float(top) + float(thumb_height)))

    inset = 1.0 if lit else float(max(2, int(round(width / 4.0))))
    x1 = inset
    x2 = float(width) - inset
    if x2 - x1 < 2.0:
        x1, x2 = 1.0, float(width) - 1.0
    if x2 <= x1:
        x1, x2 = 0.5, float(width) - 0.5

    y1 = max(1.0, min(float(height) - 2.0, float(top_edge) + 1.0))
    y2 = max(y1 + 1.0, min(float(height) - 1.0, float(bottom_edge) - 1.0))
    if y2 > float(height) - 1.0:
        y2 = float(height) - 1.0
        y1 = min(y1, y2 - 1.0)
    if lit:
        # At a rail endpoint let the bright thumb reach the Canvas edge. The
        # half-pixel inset used for interior positions otherwise leaves a fine
        # idle-colored seam where the hovered thumb should cover the idle rim.
        y1 = 0.0 if top_edge <= 0 else max(0.5, y1 - 1.0)
        y2 = float(height) if bottom_edge >= height else min(float(height) - 0.5, y2 + 1.0)
    return x1, y1, x2, y2


def scrollbar_item_colors(lit, thumb_color, hover_color=None):
    """Return (fill, outline, rail) for the scrollbar thumb in the active theme.

    Dark theme
      * outline: light gray when idle, black when hovered/dragged
      * idle: neutral gray thumb; hovered/dragged: white thumb + dark rail
    Light theme (softer, no heavy dark borders)
      * outline: dark gray when idle, white when hovered/dragged
      * idle: soft gray thumb
      * hovered/dragged: dark gray thumb + gray rail
    """
    if IS_LIGHT_THEME:
        idle_fill = lighten_color(thumb_color, 0.30)
        fill = "#596270" if lit else idle_fill
        return fill, ("#FFFFFF" if lit else "#7B8494"), "#A4ABB7"
    idle_fill = thumb_color
    return ("#FFFFFF" if lit else idle_fill), ("#000000" if lit else "#7A7A7A"), "#454545"


class ThinScrollbar(tk.Canvas):
    """Compact scrollbar rendered entirely on one Canvas for stable alignment."""

    def __init__(self, master, command, bg, thumb, thumb_hover, width=6, min_thumb=24,
                 is_blocked=None):
        self._track_bg = bg
        super().__init__(master, bg=bg, width=width, height=1, bd=0,
                         highlightthickness=0, cursor="arrow", takefocus=0)
        self._command = command
        self._thumb_color = thumb
        self._thumb_hover = thumb_hover
        self._min_thumb = min_thumb
        self._is_blocked = is_blocked or (lambda: False)
        self._first, self._last = 0.0, 1.0
        self._hover = False
        self._lit_amount = 0.0
        self._lit_fade = None
        self._dragging = False
        self._drag_dy = 0.0
        self._drag_start_root_y = None
        self._drag_moved = False
        self._suppress_hover_until_leave = False
        self._hover_after_id = None
        self._update_after_id = None
        self._rail_item = None
        self._thumb_item = None
        self._background_spans = []
        self._background_items = []

        # Keep both visible elements in one coordinate system.  The previous
        # implementation placed a child Frame over the Canvas, which caused
        # half-pixel offsets and a second layout pass during fast scrolling.
        self.bind("<Button-1>", self._on_press, add="+")
        self.bind("<B1-Motion>", self._on_drag, add="+")
        self.bind("<ButtonRelease-1>", self._on_release, add="+")
        for sequence in ("<Enter>", "<Leave>", "<Motion>"):
            self.bind(sequence, self._schedule_hover_sync, add="+")
        self.bind("<Configure>", self._on_configure, add="+")
        self._paint()

    def configure(self, cnf=None, **kwargs):
        options = dict(cnf) if isinstance(cnf, dict) else {}
        options.update(kwargs)
        result = tk.Canvas.configure(self, cnf, **kwargs)
        new_track_bg = options.get("bg", options.get("background"))
        if new_track_bg is not None and hasattr(self, "_hover"):
            self._track_bg = new_track_bg
            self._schedule_visual_update()
        return result

    config = configure

    def set_theme_colors(self, *, track_bg=None, thumb=None, thumb_hover=None):
        if track_bg is not None:
            self._track_bg = track_bg
        if thumb is not None:
            self._thumb_color = thumb
        if thumb_hover is not None:
            self._thumb_hover = thumb_hover
        self._schedule_visual_update()

    def set(self, first, last):
        try:
            self._first, self._last = float(first), float(last)
        except (TypeError, ValueError):
            return
        self._schedule_visual_update()

    def set_background_spans(self, spans):
        """Paint row-band colors through the scrollbar's track, beneath its thumb.

        Each span is (top, bottom, color) in scrollbar-local pixels. This keeps
        full-width table row highlighting visually continuous when the thumb is
        layered over the right edge of the table.
        """
        normalized = []
        for span in spans or ():
            try:
                top, bottom, color = span
                top = max(0.0, float(top))
                bottom = min(float(max(1, self.winfo_height())), float(bottom))
                if bottom > top and color:
                    normalized.append((top, bottom, str(color)))
            except (TypeError, ValueError):
                continue
        self._background_spans = normalized
        self._schedule_visual_update()

    def _paint_background_spans(self, width, height):
        spans = self._background_spans
        while len(self._background_items) < len(spans):
            item = self.create_rectangle(
                0, 0, width, 1, fill=self._track_bg, outline="", width=0,
                tags=("pycode_scrollbar_managed", "pycode_scrollbar_band"),
            )
            self._background_items.append(item)
        for index, item in enumerate(self._background_items):
            if index >= len(spans):
                self.itemconfigure(item, state="hidden")
                continue
            top, bottom, color = spans[index]
            top = max(0.0, min(float(height), top))
            bottom = max(top, min(float(height), bottom))
            self.coords(item, 0, top, width, bottom)
            self.itemconfigure(item, fill=color, outline="", width=0, state="normal")
            self.tag_lower(item)

    def _geometry(self):
        height = self.winfo_height()
        span = min(1.0, max(0.0, self._last - self._first))
        if height <= 1 or span >= 0.9999:
            return None
        thumb_h = min(float(height), max(float(self._min_thumb), height * span))
        room = max(1e-9, 1.0 - span)
        first = min(room, max(0.0, self._first))
        top = (first / room) * (height - thumb_h)
        return min(max(0.0, top), height - thumb_h), thumb_h

    def _on_configure(self, _event=None):
        self._schedule_visual_update()

    def _schedule_visual_update(self):
        """Coalesce consecutive yscroll/configure callbacks into one draw."""
        if self._update_after_id is not None:
            return
        try:
            self._update_after_id = self.after_idle(self._flush_visual_update)
        except tk.TclError:
            self._update_after_id = None

    def _flush_visual_update(self):
        self._update_after_id = None
        try:
            if self.winfo_exists():
                self._paint()
        except tk.TclError:
            pass

    def _paint(self):
        try:
            width = max(4, int(self.winfo_width()))
            height = max(4, int(self.winfo_height()))
            geometry = self._geometry()
            try:
                blocked = bool(self._is_blocked())
            except Exception:
                blocked = False
            lit = bool((self._hover or self._dragging) and geometry is not None and not blocked)
            tk.Canvas.configure(self, bg=self._track_bg)
            self._paint_background_spans(width, height)

            if geometry is None:
                self._cancel_lit_fade(reset=True)
                if self._rail_item is not None:
                    self.itemconfigure(self._rail_item, state="hidden")
                if self._thumb_item is not None:
                    self.itemconfigure(self._thumb_item, state="hidden")
                return

            top, thumb_h = geometry
            target = 1.0 if lit else 0.0
            amount = self._lit_amount
            if amount != target:
                amount = self._advance_lit_amount(target, blocked)
            thumb_coords = _scrollbar_thumb_canvas_coords(
                width, height, top, thumb_h, amount >= 0.5
            )
            center_x = float(width) / 2.0

            thumb_fill, thumb_outline, rail_color = self._faded_colors(amount)
            if blocked:
                thumb_fill = modal_dim_color(thumb_fill)
                thumb_outline = modal_dim_color(thumb_outline)
            rail_shown = amount > 0.0
            if 0.0 < amount < 1.0:
                if _is_plain_hex(self._track_bg) and _is_plain_hex(rail_color):
                    rail_color = color_mix(self._track_bg, rail_color, round(amount * 12) / 12)
                else:
                    rail_shown = amount >= 0.5
            if rail_shown:
                rail_coords = (center_x, 0.5, center_x, float(height) - 0.5)
                if self._rail_item is None:
                    self._rail_item = self.create_line(
                        *rail_coords, fill=rail_color, width=1,
                        tags=("pycode_scrollbar_managed", "pycode_scrollbar_rail"),
                    )
                else:
                    self.coords(self._rail_item, *rail_coords)
                    self.itemconfigure(
                        self._rail_item, fill=rail_color, width=1, state="normal"
                    )
            elif self._rail_item is not None:
                self.itemconfigure(self._rail_item, state="hidden")

            if self._thumb_item is None:
                self._thumb_item = self.create_rectangle(
                    *thumb_coords, fill=thumb_fill, outline=thumb_outline,
                    width=1, tags=("pycode_scrollbar_managed", "pycode_scrollbar_thumb"),
                )
            else:
                self.coords(self._thumb_item, *thumb_coords)
                self.itemconfigure(
                    self._thumb_item, fill=thumb_fill, outline=thumb_outline,
                    width=1, state="normal",
                )
            if self._rail_item is not None:
                if getattr(self, "_pycode_rail_over_background_spans", False):
                    self.tag_raise(self._rail_item)
                else:
                    self.tag_lower(self._rail_item)
            self.tag_raise(self._thumb_item)
        except tk.TclError:
            pass

    def _cancel_lit_fade(self, reset=False):
        fade = self._lit_fade
        self._lit_fade = None
        if fade is not None:
            state = fade.get("state")
            if state is not None:
                try:
                    state["cancel"]()
                except (tk.TclError, KeyError, TypeError):
                    pass
        if reset:
            self._lit_amount = 0.0

    def _advance_lit_amount(self, target, snap):
        fade = self._lit_fade
        if fade is not None and fade["target"] == target:
            return self._lit_amount
        self._cancel_lit_fade()
        tween = None
        try:
            top = self.winfo_toplevel()
            tween = getattr(top, "_tween", None)
            can_fade = (not snap and callable(tween) and self.winfo_ismapped()
                        and not getattr(top, "_theme_transition_in_progress", False)
                        and not getattr(top, "_shutting_down", False))
        except tk.TclError:
            can_fade = False
        if not can_fade:
            self._lit_amount = target
            return target
        start = self._lit_amount
        fade = {"target": target, "state": None}
        self._lit_fade = fade

        def step(eased):
            if self._lit_fade is not fade:
                return
            self._lit_amount = start + (target - start) * eased
            self._paint()

        def done():
            if self._lit_fade is not fade:
                return
            self._lit_fade = None
            self._lit_amount = target
            self._paint()

        fade["state"] = tween(HOVER_FADE_MS, step, done=done, ease=_ease_in_out_sine)
        return start

    def _faded_colors(self, amount):
        idle = scrollbar_item_colors(False, self._thumb_color, self._thumb_hover)
        if amount <= 0.0:
            return idle
        lit = scrollbar_item_colors(True, self._thumb_color, self._thumb_hover)
        if amount >= 1.0:
            return lit
        if not all(_is_plain_hex(c) for c in (idle[0], idle[1], lit[0], lit[1])):
            return lit if amount >= 0.5 else idle
        steps = round(amount * 12) / 12
        return (color_mix(idle[0], lit[0], steps), color_mix(idle[1], lit[1], steps), lit[2])

    def _schedule_hover_sync(self, _event=None):
        if self._hover_after_id is not None:
            return
        try:
            self._hover_after_id = self.after_idle(self._sync_hover_from_pointer)
        except tk.TclError:
            self._hover_after_id = None

    def _sync_hover_from_pointer(self):
        self._hover_after_id = None
        try:
            if not self.winfo_exists():
                return
            pointer_x = self.winfo_pointerx()
            pointer_y = self.winfo_pointery()
            left = self.winfo_rootx()
            top = self.winfo_rooty()
            hovered = (
                left <= pointer_x < left + self.winfo_width()
                and top <= pointer_y < top + self.winfo_height()
            )
            if self._suppress_hover_until_leave:
                if not hovered:
                    self._suppress_hover_until_leave = False
                if self._hover:
                    self._hover = False
                    self._paint()
                return
            if hovered != self._hover:
                self._hover = hovered
                self._paint()
        except tk.TclError:
            pass

    def _on_press(self, event):
        geometry = self._geometry()
        if geometry is None or self._is_blocked():
            return "break"
        self._suppress_hover_until_leave = False
        self._drag_moved = False
        self._drag_start_root_y = event.y_root
        top, thumb_h = geometry
        y = event.y_root - self.winfo_rooty()
        self._dragging = True
        self._hover = True
        self._drag_dy = (y - top) if top <= y <= top + thumb_h else thumb_h / 2.0
        self._paint()
        self._on_drag(event)
        return "break"

    def _on_drag(self, event):
        geometry = self._geometry()
        if geometry is None or not self._dragging:
            return "break"
        if self._drag_start_root_y is not None:
            if abs(float(event.y_root) - float(self._drag_start_root_y)) >= 2:
                self._drag_moved = True
        _top, thumb_h = geometry
        y = event.y_root - self.winfo_rooty()
        span = self._last - self._first
        free = max(1.0, self.winfo_height() - thumb_h)
        fraction = min(max(0.0, (y - self._drag_dy) / free), 1.0) * max(0.0, 1.0 - span)
        try:
            self._command("moveto", fraction)
        except tk.TclError:
            pass
        return "break"

    def _on_release(self, _event=None):
        was_dragged = bool(self._dragging and self._drag_moved)
        self._dragging = False
        self._drag_start_root_y = None
        try:
            pointer_x = self.winfo_pointerx()
            pointer_y = self.winfo_pointery()
            left = self.winfo_rootx()
            top = self.winfo_rooty()
            pointer_inside = (
                left <= pointer_x < left + self.winfo_width()
                and top <= pointer_y < top + self.winfo_height()
            )
        except tk.TclError:
            pointer_inside = False
        # The thumb stays in its hovered look while the pointer is still over
        # the scrollbar, even right after the button is released.
        self._suppress_hover_until_leave = False
        self._hover = bool(pointer_inside)
        self._paint()
        self._schedule_hover_sync()
        return "break"


def _material_glyph_optical_offset(widget, glyph, font):
    try:
        family = str(font[0] if isinstance(font, (tuple, list)) and font else font).lower()
        font_style = "regular" if "cascadia" in family else "material_symbols"
        font_path = _EMBEDDED_FONT_STATUS.get(font_style, {}).get("path")
        if not font_path or not os.path.isfile(font_path):
            return -1, 0
        from PIL import ImageFont
        import tkinter.font as tkfont

        points = abs(float(font[1])) if isinstance(font, (tuple, list)) and len(font) > 1 else 11.0
        pixels_per_point = float(widget.winfo_fpixels("1p"))
        pixel_size = max(1, int(round(points * pixels_per_point)))
        pil_font = ImageFont.truetype(font_path, pixel_size)
        glyph = str(glyph or "")
        if not glyph:
            return 0, 0

        bbox = pil_font.getbbox(glyph, anchor="ls")
        if not bbox:
            return 0, 0
        ascent, descent = pil_font.getmetrics()
        ink_center_y = (float(bbox[1]) + float(bbox[3])) / 2.0
        line_center_y = (float(ascent) - float(descent)) / 2.0

        try:
            tk_font = tkfont.Font(root=widget, font=font)
            advance = float(tk_font.measure(glyph))
        except (tk.TclError, TypeError, ValueError):
            advance = float(pil_font.getlength(glyph))

        ink_center_x = (float(bbox[0]) + float(bbox[2])) / 2.0
        getmask2 = getattr(pil_font, "getmask2", None)
        if callable(getmask2):
            try:
                mask, mask_offset = getmask2(glyph, mode="L", anchor="ls")
                mask_width, mask_height = mask.size
                raw = mask.tobytes()
                column_weights = [0] * mask_width
                for y in range(mask_height):
                    row_start = y * mask_width
                    for x in range(mask_width):
                        column_weights[x] += raw[row_start + x]
                total_weight = sum(column_weights)
                if total_weight:
                    centroid = sum(
                        (x + 0.5) * weight for x, weight in enumerate(column_weights)
                    ) / total_weight
                    ink_center_x = float(mask_offset[0]) + centroid
            except (AttributeError, TypeError, ValueError, IndexError):
                pass

        return (
            int(round(advance / 2.0 - ink_center_x)),
            int(round(-line_center_y - ink_center_y)),
        )
    except Exception:
        return -1, 0


def _material_glyph_ink_box(widget, glyph, font):
    try:
        family = str(font[0] if isinstance(font, (tuple, list)) and font else font).lower()
        font_style = "regular" if "cascadia" in family else "material_symbols"
        font_path = _EMBEDDED_FONT_STATUS.get(font_style, {}).get("path")
        glyph = str(glyph or "")
        if not glyph or not font_path or not os.path.isfile(font_path):
            return None
        from PIL import ImageFont
        import tkinter.font as tkfont

        points = abs(float(font[1])) if isinstance(font, (tuple, list)) and len(font) > 1 else 11.0
        pixel_size = max(1, int(round(points * float(widget.winfo_fpixels("1p")))))
        pil_font = ImageFont.truetype(font_path, pixel_size)
        left, top, right, bottom = pil_font.getbbox(glyph, anchor="ls")
        if right <= left or bottom <= top:
            return None
        tk_font = tkfont.Font(root=widget, font=font)
        tk_ascent = float(tk_font.metrics("ascent"))
        return ((left + right) / 2.0, tk_ascent + (top + bottom) / 2.0)
    except Exception:
        return None


_UNDERLINE_INK_CACHE = {}
_UNDERLINE_FALLBACK_INK = {
    "g": (0.13, 0.90), "j": (0.13, 0.64), "p": (0.13, 0.38),
    "q": (0.64, 0.90), "y": (0.13, 0.64), "Q": (0.51, 0.90),
}


def _underline_em_px(widget, font_obj):
    size = float(font_obj.actual("size"))
    return abs(size) if size < 0 else size * float(widget.winfo_fpixels("1p"))


def _underline_font_path(font_obj):
    """Return the embedded Cascadia Mono file matching a Tk font, or None."""
    try:
        if "cascadia" not in str(font_obj.actual("family")).lower():
            return None
        bold = str(font_obj.actual("weight")) == "bold"
        italic = str(font_obj.actual("slant")) == "italic"
        style = ("bold_italic" if bold and italic else "bold" if bold
                 else "italic" if italic else "regular")
        for key in (style, "regular"):
            path = _EMBEDDED_FONT_STATUS.get(key, {}).get("path")
            if path and os.path.isfile(path):
                return path
    except Exception:
        pass
    return None


def _letter_underline_ink(font_path, em_px, character):
    """Horizontal ink span (pixels from the pen origin) of a letter's descender.

    The span is measured on the glyph itself, on the pixel rows touched by an
    underline drawn one row under the baseline, so the gap is centred on the part
    of the letter that really crosses the line (the stem of p/q, the hook of g...).
    Returns None for letters that do not reach the underline.
    """
    px = max(1, int(round(em_px)))
    key = (font_path, px, character)
    if key in _UNDERLINE_INK_CACHE:
        return _UNDERLINE_INK_CACHE[key]
    result = None
    measured = False
    if font_path and Image is not None:
        try:
            from PIL import ImageDraw, ImageFont
            pil_font = ImageFont.truetype(font_path, px)
            pad = px
            width = int(math.ceil(pil_font.getlength(character))) + 2 * pad
            height = 3 * px
            baseline = 2 * px
            canvas = Image.new("L", (width, height), 0)
            ImageDraw.Draw(canvas).text(
                (pad, baseline), character, font=pil_font, fill=255, anchor="ls"
            )
            raw = canvas.tobytes()
            reaches_line = False
            columns = []
            for row in range(baseline, height):
                depth = row - baseline
                inked = [
                    col - pad for col in range(width) if raw[row * width + col] >= 40
                ]
                if not inked:
                    continue
                if depth >= 1:
                    reaches_line = True
                if depth <= 2:
                    columns.extend(inked)
            if reaches_line and columns:
                result = (min(columns), max(columns) + 1)
            measured = True
        except Exception:
            measured = False
    if not measured:
        fraction = _UNDERLINE_FALLBACK_INK.get(character)
        if fraction is not None:
            advance = em_px * 0.6
            result = (int(round(advance * fraction[0])), int(round(advance * fraction[1])))
    _UNDERLINE_INK_CACHE[key] = result
    return result


def _skip_ink_underline_segments(cells, left, right, font_path, em_px):
    """Split [left, right) into underline runs that leave a gap under descenders.

    ``cells`` is a list of ``(character, x_left, x_right)``.  Only letters get a
    gap; digits, punctuation, brackets and underscores never do.  Every gap is
    the descender's ink span plus the same clearance on both sides.
    """
    clearance = max(1, int(round(em_px / 12.0)))
    gaps = []
    for character, cell_left, cell_right in cells:
        if not character.isalpha():
            continue
        ink = _letter_underline_ink(font_path, em_px, character)
        if ink is None:
            continue
        gaps.append((cell_left + ink[0] - clearance, cell_left + ink[1] + clearance))
    gaps.sort()
    segments = []
    cursor = left
    for gap_left, gap_right in gaps:
        gap_left = max(left, gap_left)
        gap_right = min(right, gap_right)
        if gap_right <= gap_left:
            continue
        if gap_left > cursor:
            segments.append((cursor, gap_left))
        cursor = max(cursor, gap_right)
    if cursor < right:
        segments.append((cursor, right))
    return segments


def _widget_contains_root_point(widget, root_x, root_y):
    if widget is None:
        return False
    try:
        if not widget.winfo_exists() or not widget.winfo_ismapped():
            return False
        left, top = int(widget.winfo_rootx()), int(widget.winfo_rooty())
        width, height = int(widget.winfo_width()), int(widget.winfo_height())
        return left <= int(root_x) < left + width and top <= int(root_y) < top + height
    except (tk.TclError, TypeError, ValueError, AttributeError):
        return False


def _is_dropdown_menu_entry_widget(widget):
    current = widget
    while current is not None:
        if getattr(current, "_pycode_menu_entry", False):
            return True
        current = getattr(current, "master", None)
    return False


def _toplevel_has_open_dropdown(top):
    if getattr(top, "current_menu", None) is not None:
        return True
    checker = getattr(top, "_external_dropdown_is_open", None)
    if callable(checker):
        try:
            return bool(checker())
        except tk.TclError:
            return False
    return False


def _capture_local_button_grab(widget):
    if widget is None:
        return False
    try:
        if getattr(widget, "_pycode_click_grab_active", False):
            return True
        previous = widget.grab_current()
        if previous is not None:
            try:
                if previous.winfo_toplevel() is not widget.winfo_toplevel():
                    return False
            except (tk.TclError, AttributeError):
                return False
        widget._pycode_previous_click_grab = previous
        widget.grab_set()
        widget._pycode_click_grab_active = True
        return True
    except (tk.TclError, AttributeError):
        return False


def _release_local_button_grab(widget):
    if widget is None or not getattr(widget, "_pycode_click_grab_active", False):
        return
    previous = getattr(widget, "_pycode_previous_click_grab", None)
    widget._pycode_click_grab_active = False
    widget._pycode_previous_click_grab = None
    try:
        current = widget.grab_current()
        if current is widget:
            widget.grab_release()
            current = widget.grab_current()
        if current is None and previous is not None:
            try:
                if previous.winfo_exists():
                    previous.grab_set()
            except (tk.TclError, AttributeError):
                pass
    except (tk.TclError, AttributeError):
        pass


def _bind_scrollbar_wheel_to_text(scrollbar, text_widget):
    def on_wheel(event):
        if event.num == 4:
            units = -3
        elif event.num == 5:
            units = 3
        elif getattr(event, "delta", 0):
            units = -3 if event.delta > 0 else 3
        else:
            return "break"
        try:
            text_widget.yview_scroll(units, "units")
        except tk.TclError:
            pass
        return "break"
    for sequence in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
        scrollbar.bind(sequence, on_wheel, add="+")


class HoverButton(tk.Frame):
    def __init__(self, master, text, command, bg, fg, hbg, hfg, font=None, width=None, cursor="arrow", keep_hover_on_click=False, invoke_on_press=False, icon=None, icon_font=None, icon_width=None, icon_only=False, icon_accent_role=None, icon_raster=False):
        icon_font = icon_font or MATERIAL_SYMBOL_FONT
        self._icon_raster = bool(icon_raster or icon_only)
        self._icon_only = bool(icon_only)
        self._icon_accent_role = str(icon_accent_role or "")
        icon_initial_fg = icon_pastel_color(self._icon_accent_role) or fg
        popup_accent_role = None
        popup_accent_sources = (
            ("run_green", "ansi_bright_green"),
            ("stop_red", "ansi_bright_red"),
            ("save_bg", "save_button_accent"),
            ("notification_error_bg", "syn_error"),
            ("toggle_on_bg", "ansi_bright_green"),
            ("toggle_off_bg", "ansi_bright_red"),
            ("export_button_accent", "export_button_accent"),
        )
        for source_role, accent_role in popup_accent_sources:
            source_color = COLORS.get(source_role)
            if isinstance(bg, str) and isinstance(source_color, str) and bg.lower() == source_color.lower():
                popup_accent_role = accent_role
                accent = COLORS.get(accent_role, source_color)
                bg, hbg, _soft_border, _soft_hover_border = soft_accent_button_palette(accent)
                fg = COLORS.get("on_accent", fg)
                hfg = fg
                break
        self._pycode_popup_accent_role = popup_accent_role
        self.normal_border = (button_border_color(bg, 0.16) if IS_LIGHT_THEME
                              else emphasize_color(bg, 0.20))
        self.hover_border = hover_border_color(
            bg, hbg, self.normal_border,
            (button_border_color(hbg, 0.18) if IS_LIGHT_THEME else emphasize_color(hbg, 0.30)),
        )
        self.disabled_bg = COLORS["console_button_disabled_bg"]
        self.disabled_fg = COLORS["border_dark"]
        self.disabled_border = (button_border_color(self.disabled_bg, 0.16) if IS_LIGHT_THEME
                                else emphasize_color(self.disabled_bg, 0.22))
        self._enabled = True
        self._command = command
        self._normal_active_bg = hbg
        self._normal_active_fg = hfg
        self._normal_cursor = cursor or "arrow"
        self._keep_hover_on_click = bool(keep_hover_on_click)
        self._invoke_on_press = bool(invoke_on_press)

        super().__init__(master, bg=COLORS["modal_outline"], padx=1, pady=1, cursor="arrow")
        self._pycode_popup_outline = True
        self._button_border_frame = tk.Frame(
            self, bg=self.normal_border, padx=1, pady=1,
            bd=0, highlightthickness=0, cursor=self._normal_cursor,
        )
        self._button_border_frame._pycode_button_inner_border = True
        self._button_border_frame.pack(fill="both", expand=True)

        self._button_content_frame = None
        self._button_group_frame = None
        self._icon_slot = None
        self._icon_label = None
        self._icon_pressed = False
        self._icon_slot_width = 0
        self._icon_gap = 0
        self._icon_left_pad = 0
        self._icon_right_pad = 0
        self._icon_target_text_width = None
        self._icon_target_group_width = None
        self._icon_font = icon_font
        button_parent = self._button_border_frame
        if icon or self._icon_only:
            self._button_content_frame = tk.Frame(
                self._button_border_frame, bg=bg, bd=0,
                highlightthickness=0, cursor=self._normal_cursor,
            )
            self._button_content_frame.pack(fill="both", expand=True)
            if self._icon_only:
                if icon:
                    self._icon_label = create_material_icon_label(
                        self._button_content_frame, icon, bg, icon_initial_fg,
                        font=icon_font, cursor=self._normal_cursor,
                        raster=self._icon_raster,
                    )
                button_parent = self._button_content_frame
            else:
                icon_layout = ICON_CONFIG["layout"]
                requested_slot_width = int(
                    icon_width or ui_px(icon_layout["toolbar_slot_width"])
                )
                self._icon_slot_width = max(
                    ui_px(icon_layout["toolbar_slot_min_width"]),
                    min(ui_px(icon_layout["toolbar_slot_width"]), requested_slot_width),
                )
                self._icon_gap = ui_px(icon_layout["toolbar_gap"])
                self._icon_left_pad = ui_px(icon_layout["toolbar_side_padding"])
                self._icon_right_pad = ui_px(icon_layout["toolbar_side_padding"])
                self._button_group_frame = tk.Frame(
                    self._button_content_frame, bg=bg, bd=0,
                    highlightthickness=0, cursor=self._normal_cursor,
                )
                self._button_group_frame.pack_propagate(False)
                self._icon_slot = tk.Frame(
                    self._button_group_frame, bg=bg, width=self._icon_slot_width,
                    bd=0, highlightthickness=0, cursor=self._normal_cursor,
                )
                self._icon_slot.pack(side="left", fill="y")
                self._icon_slot.pack_propagate(False)
                self._icon_label = create_material_icon_label(
                    self._icon_slot, icon, bg, icon_initial_fg,
                    font=icon_font, cursor=self._normal_cursor,
                    raster=self._icon_raster,
                )
                self._icon_label.place(relx=1.0, rely=0.5, y=ui_px(1), anchor="e")
                if self._icon_raster:
                    self._icon_slot.bind(
                        "<Configure>", self._on_icon_group_slot_configure, add="+",
                    )
                button_parent = self._button_group_frame

        self.btn = tk.Button(
            button_parent,
            text=(" " if self._icon_only else text),
            command=(None if self._invoke_on_press else self._invoke_if_enabled),
            bg=bg,
            fg=fg,
            activebackground=hbg,
            activeforeground=hfg,
            relief="flat",
            borderwidth=0,
            highlightthickness=0,
            highlightcolor=bg,
            highlightbackground=bg,
            takefocus=0,
            default="disabled",
            overrelief="flat",
            cursor=self._normal_cursor,
            font=font or ("Cascadia Mono", 9, "normal", "roman"),
            anchor="center",
            justify="center",
            padx=(ui_px(0) if (icon or self._icon_only) else ui_px(10)),
            pady=ui_px(2),
            width=(0 if icon and width is None else width)
        )
        self._normal_button_bg = bg
        self._normal_button_fg = fg

        def _find_role(value, candidates):
            if not isinstance(value, str):
                return None
            for candidate in candidates:
                candidate_value = COLORS.get(candidate)
                if isinstance(candidate_value, str) and candidate_value.lower() == value.lower():
                    return candidate
            return None

        normal_bg_role = _find_role(bg, (
            "save_bg", "run_green", "stop_red", "notification_error_bg",
            "toggle_on_bg", "toggle_off_bg", "button_secondary_bg", "menu_bg",
            "surface_dark", "console_button_bg", "info_bg", "line_entry_bg",
            "bg_editor", "bg_main",
        ))
        active_bg_role = _find_role(hbg, (
            "save_hover_bg", "button_secondary_hover_bg", "menu_hover",
            "surface_hover", "console_button_hover", "run_green_hover_previous",
            "stop_red", "run_green",
        ))
        role_bundle = {}
        if normal_bg_role:
            role_bundle["normal_bg"] = normal_bg_role
            if normal_bg_role in ("save_bg", "run_green", "stop_red", "notification_error_bg"):
                role_bundle["normal_fg"] = "on_accent" if isinstance(fg, str) and fg.lower() == str(COLORS.get("on_accent", "")).lower() else _find_role(
                    fg, ("fg_strong", "fg_text", "secondary_text", "info_text", "muted_text", "on_accent")
                )
                if normal_bg_role in ("save_bg", "run_green", "stop_red") and active_bg_role is None:
                    role_bundle["active_from"] = normal_bg_role
                    role_bundle["active_amount"] = 0.42
            elif normal_bg_role in ("button_secondary_bg", "menu_bg"):
                role_bundle["normal_fg"] = "button_secondary_fg"
            elif normal_bg_role == "surface_dark":
                role_bundle["normal_fg"] = "fg_strong"
            elif normal_bg_role == "console_button_bg":
                role_bundle["normal_fg"] = "fg_strong"
            else:
                role_bundle["normal_fg"] = _find_role(
                    fg, ("fg_strong", "fg_text", "secondary_text", "info_text", "muted_text", "tooltip_fg")
                )
            if active_bg_role:
                role_bundle["active_bg"] = active_bg_role
            elif "active_from" not in role_bundle:
                role_bundle["active_bg"] = _find_role(
                    hbg, ("surface_hover", "button_secondary_hover_bg", "menu_hover", "console_button_hover")
                )
            if role_bundle.get("normal_fg"):
                role_bundle["active_fg"] = "on_accent" if normal_bg_role in ("save_bg", "run_green", "stop_red", "notification_error_bg") else role_bundle["normal_fg"]
                if normal_bg_role in ("save_bg", "run_green", "stop_red", "notification_error_bg"):
                    role_bundle["disabled_from"] = normal_bg_role
                    role_bundle["disabled_amount"] = 0.62
                    role_bundle["disabled_fg_from"] = normal_bg_role
                else:
                    role_bundle["disabled_bg"] = "console_button_disabled_bg"
                    role_bundle["disabled_fg"] = "border_dark"
                role_bundle["disabled_border_mix"] = 0.16
        if role_bundle:
            self._pycode_theme_roles = role_bundle
            accent_role = role_bundle.get("disabled_fg_from", role_bundle.get("disabled_from"))
            if accent_role and accent_role in COLORS:
                accent_color = COLORS[accent_role]
                self.disabled_bg = disabled_accent_bg(accent_color, 0.62)
                self.disabled_fg = disabled_accent_fg(accent_color)
                self.disabled_border = (button_border_color(self.disabled_bg, 0.16) if IS_LIGHT_THEME
                                        else emphasize_color(self.disabled_bg, 0.18))

        if self._icon_only:
            self.btn.pack(fill="both", expand=True)
            requested_size = max(
                int(self.btn.winfo_reqwidth()), int(self.btn.winfo_reqheight())
            )
            square_content = max(1, requested_size)
            self._icon_only_size = square_content
            self._button_content_frame.configure(
                width=_dpi_px_from_current_pixels(square_content),
                height=_dpi_px_from_current_pixels(square_content),
            )
            self._button_content_frame.pack_propagate(False)
            if self._icon_label is not None:
                if self._icon_raster and hasattr(self._icon_label, "enable_raster"):
                    self._icon_label.enable_raster(square_content)
                self._position_icon_only_label()
            self.configure(
                width=_dpi_px_from_current_pixels(square_content + ui_px(4)),
                height=_dpi_px_from_current_pixels(square_content + ui_px(4)),
            )
            self.pack_propagate(False)
            self._icon_layout_metrics = {
                "icon_only": True,
                "content_width": square_content,
                "content_height": square_content,
                "frame_width": square_content + ui_px(4),
                "frame_height": square_content + ui_px(4),
            }
        elif self._icon_label is not None:
            self.btn.pack(side="left", fill="y", expand=False, padx=0)
            try:
                if width is not None:
                    self._icon_target_text_width = max(1, int(self.btn.winfo_reqwidth()))
                    self._icon_target_group_width = (
                        self._icon_slot_width + self._icon_gap
                        + self._icon_target_text_width
                    )
                    self.btn.configure(width=0)
                self._layout_icon_group()
            except (tk.TclError, TypeError, ValueError):
                pass
        else:
            self.btn.pack(fill="both")

        self._hovered = False
        self._border_armed = False
        self._hover_sync_after_id = None
        for hover_target in (self.btn, self._button_border_frame, self._button_content_frame,
                             self._button_group_frame, self._icon_slot, self._icon_label):
            if hover_target is None:
                continue
            hover_target.bind("<Enter>", self._sync_hover_from_pointer, add="+")
            hover_target.bind("<Leave>", self._sync_hover_from_pointer, add="+")
            hover_target.bind("<Motion>", self._sync_hover_from_pointer, add="+")
        for icon_target in (self._icon_slot, self._icon_label):
            if icon_target is None:
                continue
            icon_target.bind("<ButtonPress-1>", self._icon_button_press, add="+")
            icon_target.bind("<ButtonRelease-1>", self._icon_button_release, add="+")
        self.btn.bind("<ButtonPress-1>", self._guard_mouse_press, add="+")
        self.btn.bind("<ButtonRelease-1>", self._clear_button_focus, add="+")
        self.btn.bind("<FocusIn>", self._clear_button_focus, add="+")
        self._button_border_frame.bind("<ButtonPress-1>", self._border_press, add="+")
        self._button_border_frame.bind("<ButtonRelease-1>", self._border_release, add="+")
        if popup_accent_role:
            apply_soft_accent_hover_style(self, popup_accent_role, foreground_role="on_accent")

    def set_mnemonic_underline(self, index):
        """Underline one title character with an exact 1 px line (any DPI).

        Tk's native -underline thickness follows the font and can reach 2 px at
        high DPI. The line is instead a transparent image the size of the text
        box, drawn by the Button itself (compound="center") so it is repainted
        with the text on hover, press and theme changes.
        """
        text = str(self.btn.cget("text"))
        if not (0 <= int(index) < len(text)):
            return
        self._mnemonic_index = int(index)
        if self.__dict__.get("_mnemonic_original_configure") is None:
            original_configure = self.btn.configure
            self._mnemonic_original_configure = original_configure

            def synced_configure(cnf=None, **kw):
                result = original_configure(cnf, **kw)
                if any(key in kw for key in ("fg", "foreground", "font", "text")):
                    self._refresh_mnemonic_image()
                return result

            self.btn.configure = synced_configure
            self.btn.config = synced_configure
        self._refresh_mnemonic_image()

    def _refresh_mnemonic_image(self):
        index = self.__dict__.get("_mnemonic_index")
        original_configure = self.__dict__.get("_mnemonic_original_configure")
        if index is None or original_configure is None:
            return
        try:
            import tkinter.font as tkfont
            btn = self.btn
            text = str(btn.cget("text"))
            if index >= len(text):
                return
            image = self.__dict__.get("_mnemonic_image")
            render_key = (text, index, str(btn.cget("font")), str(btn.cget("fg")))
            if (image is not None and self.__dict__.get("_mnemonic_key") == render_key
                    and str(btn.cget("image")) == str(image)):
                return  # same text, font and colour: the underline image is already right
            font = tkfont.Font(root=self, font=btn.cget("font"))
            metrics = font.metrics()
            ascent, descent = int(metrics["ascent"]), int(metrics["descent"])
            height = max(1, int(metrics["linespace"]))
            width = max(1, int(font.measure(text)))
            left = int(font.measure(text[:index]))
            right = min(width, left + max(1, int(font.measure(text[index]))))
            row = min(height - 1, ascent + descent // 2)
            image = self.__dict__.get("_mnemonic_image")
            if image is None:
                image = tk.PhotoImage(master=btn, width=width, height=height)
                self._mnemonic_image = image
            image.blank()
            image.configure(width=width, height=height)
            image.put(str(btn.cget("fg")), to=(left, row, right, row + 1))
            original_configure(image=image, compound="center")
            self._mnemonic_key = render_key
        except (tk.TclError, TypeError, ValueError, KeyError):
            pass

    def _icon_only_optical_offset(self):
        if self._icon_label is None:
            return 0, 0
        return _material_glyph_optical_offset(
            self, self._icon_label.cget("text"), self._icon_font
        )

    def _position_icon_only_label(self):
        """Fill the square button face with a centered icon surface.

        Raster icons contain a transparent square whose visible glyph ink has
        already been centered pixel-for-pixel.  When rasterization is unavailable,
        a full-size Label delegates centering to Tk instead of estimating a font
        baseline and applying fragile per-glyph offsets.
        """
        if self._icon_label is None:
            return
        try:
            size = max(1, int(getattr(self, "_icon_only_size", 0) or 0))
            if self._icon_raster and hasattr(self._icon_label, "enable_raster"):
                self._icon_label.enable_raster(size)
            self._icon_label.place(
                relx=0, rely=0, relwidth=1, relheight=1,
                x=_dpi_px_from_current_pixels(0),
                y=_dpi_px_from_current_pixels(0),
                anchor="nw",
            )
            if hasattr(self._icon_label, "tkraise"):
                self._icon_label.tkraise()
            self._icon_only_center_metrics = {
                "method": "ink_bounds_raster" if getattr(self._icon_label, "_raster_active", False) else "full_surface_tk_center",
                "offset_x": 0,
                "placement_offset_x": 0,
                "offset_y": 0,
                "content_width": int(self._button_content_frame.winfo_width() or size),
                "content_height": int(self._button_content_frame.winfo_height() or size),
            }
        except (tk.TclError, TypeError, ValueError, AttributeError):
            pass

    def _position_icon_group_label(self, slot_width=None, slot_height=None):
        """Center a launcher icon inside a DPI-scaled square, ink-centered surface.

        This mirrors the full-surface placement used by square toolbar buttons.
        Rasterization centers the glyph's actual ink rather than the font's
        ascent/descent box, which avoids a font-baseline drift across DPI values.
        """
        if self._icon_label is None or self._icon_slot is None:
            return
        try:
            if slot_width is None:
                slot_width = int(self._icon_slot.winfo_width() or 0)
            if slot_height is None:
                slot_height = int(self._icon_slot.winfo_height() or 0)
            if slot_width <= 1:
                slot_width = int(self._icon_slot_width or 1)
            if slot_height <= 1:
                slot_height = int(self.btn.winfo_reqheight() or 1)
            box = max(1, min(int(slot_width), int(slot_height)))

            if self._icon_raster and hasattr(self._icon_label, "enable_raster"):
                self._icon_label.enable_raster(box)
                if getattr(self._icon_label, "_raster_active", False):
                    ink_bbox = getattr(self._icon_label, "_raster_ink_bbox", None)
                    if getattr(self, "_pycode_text_optical_lift", False) and ink_bbox:
                        # Put the icon's real ink center on the slot's center row
                        # (integer pixels) instead of trusting the box center.
                        ink_center_y = (float(ink_bbox[1]) + float(ink_bbox[3])) / 2.0
                        top = int(round(float(slot_height) / 2.0 - ink_center_y))
                        self._icon_label.place(
                            relx=0.5, rely=0.0, anchor="n",
                            x=_dpi_px_from_current_pixels(0),
                            y=_dpi_px_from_current_pixels(top),
                            width=_dpi_px_from_current_pixels(box),
                            height=_dpi_px_from_current_pixels(box),
                        )
                    else:
                        self._icon_label.place(
                            relx=0.5, rely=0.5, anchor="center",
                            width=_dpi_px_from_current_pixels(box),
                            height=_dpi_px_from_current_pixels(box),
                        )
                    self._icon_label.tkraise()
                    self._icon_group_icon_center_metrics = {
                        "method": "ink_bounds_raster",
                        "box": box,
                        "slot_width": int(slot_width),
                        "slot_height": int(slot_height),
                    }
                    return

            # Font fallback: retain Tk's centered text layout if raster assets
            # are unavailable, while keeping the icon anchored to the slot.
            self._icon_label.place(relx=1.0, rely=0.5, y=ui_px(1), anchor="e")
            self._icon_group_icon_center_metrics = {
                "method": "tk_font_center_fallback",
                "box": box,
                "slot_width": int(slot_width),
                "slot_height": int(slot_height),
            }
        except (tk.TclError, TypeError, ValueError, AttributeError):
            pass

    def _on_icon_group_slot_configure(self, event=None):
        """Refresh the raster box after a DPI or layout-size change."""
        try:
            width = int(getattr(event, "width", 0) or self._icon_slot.winfo_width())
            height = int(getattr(event, "height", 0) or self._icon_slot.winfo_height())
            self._position_icon_group_label(width, height)
        except (tk.TclError, TypeError, ValueError, AttributeError):
            pass

    def _layout_icon_group(self):
        if self._icon_label is None:
            return
        if self._icon_only:
            self._position_icon_only_label()
            return
        import tkinter.font as tkfont

        button_req_width = max(1, int(self.btn.winfo_reqwidth()))
        button_req_height = max(1, int(self.btn.winfo_reqheight()))
        if self._icon_raster:
            self._position_icon_group_label(
                slot_width=int(self._icon_slot_width or 1),
                slot_height=button_req_height,
            )
        icon_width = max(1, int(self._icon_label.winfo_reqwidth()))
        try:
            title_font = tkfont.Font(root=self, font=self.btn.cget("font"))
            title_width = max(1, int(title_font.measure(str(self.btn.cget("text") or ""))))
        except (tk.TclError, TypeError, ValueError):
            title_width = button_req_width

        icon_visual_leading_inset = float(self._icon_slot_width - icon_width)
        ink_bbox = getattr(self._icon_label, "_raster_ink_bbox", None)
        if (
            self._icon_raster
            and getattr(self._icon_label, "_raster_active", False)
            and ink_bbox
        ):
            # The raster square is centered in the slot and its glyph ink is
            # narrower than the square, so empty pixels sit left of the icon.
            # Count them as leading inset so the visible icon+title group is
            # centered instead of drifting right.
            raster_box = int(getattr(self._icon_label, "_raster_box", 0) or 0)
            icon_visual_leading_inset = max(
                0.0,
                (float(self._icon_slot_width) - raster_box) / 2.0 + float(ink_bbox[0]),
            )
        icon_visual_trailing_inset = 0.0
        title_visual_inset = max(0.0, (button_req_width - min(title_width, button_req_width)) / 2.0)
        effective_gap = max(
            0, int(round(
                self._icon_gap - icon_visual_trailing_inset - title_visual_inset
            ))
        )
        text_lift = 0
        if getattr(self, "_pycode_text_optical_lift", False):
            # Same measured correction as native Entries: Tk centers the font box,
            # so tall-ascent fonts read low next to the ink-centered icon. The
            # lift comes from real font metrics and therefore follows the DPI.
            text_lift = int(_title_ink_lift_px(self.btn, self.btn.cget("font")))
        self._text_optical_lift_px = text_lift
        optical_pad_top = _dpi_px_from_current_pixels(2 * max(0, -text_lift))
        optical_pad_bottom = _dpi_px_from_current_pixels(2 * max(0, text_lift))
        self.btn.pack_configure(
            padx=(_dpi_px_from_current_pixels(effective_gap), 0),
            pady=(optical_pad_top, optical_pad_bottom),
        )
        # pack() reserves external pady in addition to the Button's requested
        # height. The group used to keep the pre-padding height, which clipped
        # that extra space and shifted both the icon and title off the center.
        group_width = max(
            1, self._icon_slot_width + effective_gap + button_req_width
        )

        target_text_width = max(
            button_req_width, int(self._icon_target_text_width or 0)
        )
        target_group_width = max(
            group_width,
            int(self._icon_target_group_width or 0),
            (self._icon_slot_width + self._icon_gap + target_text_width)
            if self._icon_target_group_width is None and self._icon_target_text_width is not None
            else 0,
        )
        group_height = max(
            1, button_req_height + int(optical_pad_top) + int(optical_pad_bottom)
        )
        content_width = target_group_width + self._icon_left_pad + self._icon_right_pad
        visual_center_offset = _centered_group_pixel_offset(
            content_width, group_width, icon_visual_leading_inset, title_visual_inset
        )
        content_height = group_height
        icon_frame_width = content_width + ui_px(4)
        icon_frame_height = group_height + ui_px(4)

        self._button_content_frame.configure(
            width=_dpi_px_from_current_pixels(content_width),
            height=_dpi_px_from_current_pixels(content_height),
        )
        self._button_content_frame.pack_propagate(False)
        self._button_group_frame.configure(
            width=_dpi_px_from_current_pixels(group_width),
            height=_dpi_px_from_current_pixels(group_height),
        )
        if self._icon_raster:
            # The icon slot is as tall as the whole group, optical padding included.
            # Position the icon ink against that real height (not the bare button
            # height) so icon and title share one centre line at every DPI instead
            # of depending on which Configure event arrives last.
            self._position_icon_group_label(
                slot_width=int(self._icon_slot_width or 1),
                slot_height=group_height,
            )
        vertical_offset = float(
            getattr(self, "_pycode_icon_group_vertical_offset", 0.0) or 0.0
        )
        self._button_group_frame.place(
            relx=0.5, rely=0.5, anchor="center",
            x=_dpi_px_from_current_pixels(visual_center_offset),
            y=_DpiPx(int(round(vertical_offset * UI_SCALE)), vertical_offset),
            width=_dpi_px_from_current_pixels(group_width),
            height=_dpi_px_from_current_pixels(group_height),
        )
        self.configure(
            width=_dpi_px_from_current_pixels(icon_frame_width),
            height=_dpi_px_from_current_pixels(icon_frame_height),
        )
        self.pack_propagate(False)
        self._icon_layout_metrics = {
            "button_width": button_req_width,
            "slot_width": self._icon_slot_width,
            "icon_advance_width": icon_width,
            "title_advance_width": title_width,
            "icon_visual_leading_inset": icon_visual_leading_inset,
            "icon_visual_trailing_inset": icon_visual_trailing_inset,
            "title_visual_inset": title_visual_inset,
            "visual_center_offset": visual_center_offset,
            "configured_gap": self._icon_gap,
            "effective_pack_gap": effective_gap,
            "visual_gap": effective_gap + icon_visual_trailing_inset + title_visual_inset,
            "group_width": group_width,
            "target_group_width": target_group_width,
            "content_width": content_width,
            "frame_width": icon_frame_width,
            "side_padding": (self._icon_left_pad, self._icon_right_pad),
        }

    def set_icon(self, icon, icon_font=None):
        if not icon:
            return False
        try:
            if icon_font is not None:
                self._icon_font = icon_font
            if self._icon_only:
                if self._icon_label is None:
                    bg = self.btn.cget("bg")
                    fg = self.btn.cget("fg")
                    self._icon_label = create_material_icon_label(
                        self._button_content_frame, icon, bg, fg,
                        font=self._icon_font, cursor=self._normal_cursor,
                        raster=self._icon_raster,
                    )
                    if self._icon_label is None:
                        return False
                    self._icon_label.bind("<Enter>", self._sync_hover_from_pointer, add="+")
                    self._icon_label.bind("<Leave>", self._sync_hover_from_pointer, add="+")
                    self._icon_label.bind("<Motion>", self._sync_hover_from_pointer, add="+")
                    self._icon_label.bind("<ButtonPress-1>", self._icon_button_press, add="+")
                    self._icon_label.bind("<ButtonRelease-1>", self._icon_button_release, add="+")
                self._icon_label.configure(text=icon, font=self._icon_font)
                self._sync_icon_colors()
                self._position_icon_only_label()
                return True

            if self._icon_label is None:
                return False
            self._icon_label.configure(text=icon, font=self._icon_font)
            self._sync_icon_colors()
            self._layout_icon_group()
            return True
        except (tk.TclError, TypeError, ValueError):
            return False

    def _sync_icon_colors(self, bg=None, fg=None):
        if self._icon_label is None:
            return
        try:
            if bg is None:
                bg = self.btn.cget("bg")
            if fg is None:
                fg = self.btn.cget("fg")
            icon_fg = fg
            if self._enabled and self._icon_accent_role:
                icon_fg = icon_pastel_color(self._icon_accent_role) or fg
            top = self.winfo_toplevel()
            restore_state = getattr(top, "_modal_dim_state", {})
            if (getattr(top, "_modal_dim_active", False)
                    and self._icon_label in restore_state):
                # Keep the true theme colour as the restore value. The icon is
                # dimmed here, so _sync_modal_dimming must not save this already
                # dimmed foreground a second time.
                restore_state[self._icon_label]["fg"] = icon_fg
                icon_fg = modal_dim_color(icon_fg, widget=self._icon_label)
            for target in (self._button_content_frame, self._button_group_frame,
                           self._icon_slot, self._icon_label):
                if target is not None:
                    target.configure(bg=bg)
            self._icon_label.configure(fg=icon_fg)
        except tk.TclError:
            pass

    def _icon_button_press(self, event=None):
        if self._guard_mouse_press(event) == "break":
            self._icon_pressed = False
            return "break"
        target = getattr(event, "widget", None) or self._icon_label
        _capture_local_button_grab(target)
        self._icon_pressed = True
        self._icon_pressed_widget = target
        return None

    def _icon_button_release(self, event=None):
        pressed = bool(self._icon_pressed)
        target = getattr(event, "widget", None) or getattr(self, "_icon_pressed_widget", None)
        self._icon_pressed = False
        self._icon_pressed_widget = None
        _release_local_button_grab(target)
        if pressed and self._enabled and self._pointer_over_button_area():
            self._invoke_if_enabled()
            self._clear_button_focus()
        return None

    def _pointer_over_button_area(self):
        try:
            return _widget_contains_root_point(
                self._button_border_frame,
                self.winfo_pointerx(), self.winfo_pointery(),
            )
        except (tk.TclError, AttributeError):
            return False

    def _sync_hover_from_pointer(self, _event=None):
        if _event is not None:
            if self._hover_sync_after_id is not None:
                return
            try:
                self._hover_sync_after_id = self.after_idle(
                    lambda: self._sync_hover_from_pointer()
                )
            except tk.TclError:
                self._hover_sync_after_id = None
            return
        self._hover_sync_after_id = None
        try:
            top = self.winfo_toplevel()
            switching_dropdown = (
                getattr(self, "_pycode_dropdown_hover_switch", False)
                and _toplevel_has_open_dropdown(top)
                and getattr(top, "_active_menu_button", None) is not self
            )
        except tk.TclError:
            switching_dropdown = False
        if switching_dropdown:
            if getattr(self, "_hovered", False):
                self._on_leave()
            return
        over = self._pointer_over_button_area()
        hovered = bool(getattr(self, "_hovered", False))
        if over and not hovered:
            self._on_enter()
        elif not over and hovered:
            self._on_leave()

    def _border_press(self, event=None):
        if self._guard_mouse_press(event) == "break":
            return "break"
        target = getattr(event, "widget", None) or self._button_border_frame
        _capture_local_button_grab(target)
        self._border_armed = True
        self._border_pressed_widget = target
        return None

    def _border_release(self, event=None):
        armed = bool(getattr(self, "_border_armed", False))
        target = getattr(event, "widget", None) or getattr(self, "_border_pressed_widget", None)
        self._border_armed = False
        self._border_pressed_widget = None
        _release_local_button_grab(target)
        if armed and self._enabled and self._pointer_over_button_area():
            self._invoke_if_enabled()
            self._clear_button_focus()
        else:
            self._clear_button_focus()
        return None

    def _restore_hover_after_click(self):
        if not self._enabled:
            return
        try:
            if self._pointer_over_button_area():
                self._on_enter()
            else:
                self._on_leave()
        except tk.TclError:
            pass

    def _invoke_if_enabled(self, ignore_enabled=False):
        if not self._enabled and not ignore_enabled:
            return None
        suppress_tooltip = getattr(self, "_pycode_tooltip_suppress_callback", None)
        if callable(suppress_tooltip):
            suppress_tooltip()
        command = self._command
        try:
            return command() if command is not None else None
        finally:
            try:
                top = self.winfo_toplevel()
                modal_open = bool(
                    getattr(top, "_modal_dim_active", False) or
                    getattr(top, "_native_file_dialog_open", False)
                )
                if modal_open:
                    self._hovered = False
                elif self._enabled and self._keep_hover_on_click:
                    self.after_idle(self._restore_hover_after_click)
                elif self._enabled:
                    self.btn.config(bg=self._normal_button_bg, fg=self._normal_button_fg)
                    self._sync_icon_colors(self._normal_button_bg, self._normal_button_fg)
                    self._button_border_frame.configure(bg=self.normal_border)
                    self.after(65, self._restore_hover_after_click)
            except tk.TclError:
                pass

    def _close_open_menu_on_press(self):
        try:
            top = self.winfo_toplevel()
            if getattr(top, "current_menu", None) is None:
                return
            if getattr(top, "_active_menu_button", None) is self:
                return
            close_menu = getattr(top, "close_current_menu", None)
            if callable(close_menu):
                close_menu()
        except (tk.TclError, AttributeError):
            pass

    def _guard_mouse_press(self, _event=None):
        if not self._enabled or str(self.btn.cget("state")) == "disabled":
            try:
                top = self.winfo_toplevel()
                current_menu = getattr(top, "current_menu", None)
                active_button = getattr(top, "_active_menu_button", None)
                close_menu = getattr(top, "close_current_menu", None)
                if current_menu is not None and callable(close_menu):
                    close_menu()
                    if active_button is self:
                        return "break"
                    if self._enabled:
                        return None
                elif active_button is self:
                    self.set_enabled(True)
                    return None
            except (tk.TclError, AttributeError):
                pass
            if not self._enabled:
                try:
                    self.btn.configure(cursor="arrow", relief="flat", overrelief="flat")
                    self.configure(cursor="arrow")
                except tk.TclError:
                    pass
                return "break"
        try:
            self._focus_before_mouse_click = self.winfo_toplevel().focus_get()
        except tk.TclError:
            self._focus_before_mouse_click = None
        if self._invoke_on_press:
            self._close_open_menu_on_press()
            self._invoke_if_enabled(ignore_enabled=True)
            return "break"
        return None

    def set_enabled(self, enabled):
        enabled = bool(enabled)
        _cancel_hover_fade(self)
        self._enabled = enabled
        if enabled:
            self.btn.config(
                state="normal",
                bg=self._normal_button_bg,
                fg=self._normal_button_fg,
                disabledforeground=self._normal_button_fg,
                activebackground=self._normal_active_bg,
                activeforeground=self._normal_active_fg,
                relief="flat",
                bd=0,
                highlightthickness=0,
                highlightbackground=self._normal_button_bg,
                highlightcolor=self._normal_button_bg,
                takefocus=0,
                default="normal",
                cursor=self._normal_cursor,
            )
            self.configure(bg=COLORS["modal_outline"], cursor="arrow")
            self._button_border_frame.configure(bg=self.normal_border, cursor=self._normal_cursor)
            self._sync_icon_colors(self._normal_button_bg, self._normal_button_fg)

            # Tk may not emit a new <Enter> event when a control is re-enabled
            # while the pointer is still over it. Reconcile hover from the
            # current pointer position using the shared HoverButton logic.
            self._sync_hover_from_pointer()
        else:
            try:
                top = self.winfo_toplevel()
                if getattr(self.btn, "_pycode_editor_help_tooltip", None) is not None:
                    top._editor_help_tooltip_hide(self.btn)
            except (AttributeError, tk.TclError):
                pass
            self.btn.config(
                state="normal",
                bg=self.disabled_bg,
                fg=self.disabled_fg,
                disabledforeground=self.disabled_fg,
                activebackground=self.disabled_bg,
                activeforeground=self.disabled_fg,
                relief="flat",
                bd=0,
                highlightthickness=0,
                highlightbackground=self.disabled_bg,
                highlightcolor=self.disabled_bg,
                takefocus=0,
                default="normal",
                cursor="arrow",
            )
            self.configure(bg=COLORS["modal_outline"], cursor="arrow")
            self._button_border_frame.configure(bg=self.disabled_border, cursor="arrow")
            self._sync_icon_colors(self.disabled_bg, self.disabled_fg)

        self._sync_modal_dimming()
        try:
            top = self.winfo_toplevel()
            refresh_tooltip = getattr(top, "_refresh_icon_only_tooltip_foreground", None)
            if callable(refresh_tooltip):
                refresh_tooltip(self)
        except tk.TclError:
            pass

    def _sync_modal_dimming(self):
        try:
            top = self.winfo_toplevel()
            if not getattr(top, "_modal_dim_active", False):
                return
            active_modal = getattr(top, "_active_modal_widget", None)
            current = self
            while current is not None:
                if active_modal is not None and current is active_modal:
                    return
                current = getattr(current, "master", None)

            restore_state = getattr(top, "_modal_dim_state", None)
            if not isinstance(restore_state, dict):
                return
            options = (
                "bg", "fg", "disabledforeground", "activebackground", "activeforeground",
                "insertbackground", "selectbackground", "selectforeground",
                "highlightbackground", "highlightcolor",
            )
            for target in (
                self, self._button_border_frame, self._button_content_frame,
                self._button_group_frame, self._icon_slot, self._icon_label, self.btn,
            ):
                if target is None:
                    continue
                try:
                    if not target.winfo_exists():
                        continue
                except tk.TclError:
                    continue
                saved = restore_state.setdefault(target, {})
                dimmed = {}
                for option in options:
                    try:
                        value = target.cget(option)
                    except tk.TclError:
                        continue
                    if value in (None, ""):
                        continue
                    if target is self._icon_label and option == "fg" and option in saved:
                        # _sync_icon_colors has already updated this canonical
                        # value and applied modal dimming to the live Label.
                        value = saved[option]
                    else:
                        saved[option] = value
                    try:
                        dimmed[option] = modal_dim_color(value, widget=target)
                    except Exception:
                        dimmed[option] = value
                if dimmed:
                    try:
                        target.configure(**dimmed)
                    except tk.TclError:
                        for option, value in dimmed.items():
                            try:
                                target.configure(**{option: value})
                            except tk.TclError:
                                pass
        except (tk.TclError, AttributeError):
            pass

    def is_enabled(self):
        return self._enabled

    def _popup_hover_allowed(self):
        try:
            top = self.winfo_toplevel()
            if (getattr(top, "_pycode_native_dialog_active", False) or
                    getattr(top, "_native_file_dialog_open", False)):
                return False
            if not getattr(top, "_modal_dim_active", False):
                return True

            active_modal = getattr(top, "_active_modal_widget", None)
            if active_modal is not None:
                try:
                    if active_modal.winfo_exists():
                        current = self
                        while current is not None:
                            if getattr(current, "_pycode_native_dialog_active", False):
                                return False
                            if current is active_modal:
                                return True
                            current = getattr(current, "master", None)
                        return False
                except tk.TclError:
                    pass

            grab = top.grab_current()
            if isinstance(grab, str):
                try:
                    grab = top.nametowidget(grab)
                except tk.TclError:
                    return False
            current = self
            while current is not None:
                if getattr(current, "_pycode_native_dialog_active", False):
                    return False
                if grab is not None and current is grab:
                    return True
                current = getattr(current, "master", None)
            return False
        except tk.TclError:
            return False

    def _on_enter(self, _event=None):
        if not self._enabled:
            return
        try:
            blocker = getattr(self.winfo_toplevel(), "_pointer_hover_blocked_by_keyboard", None)
            if callable(blocker) and blocker():
                return
        except (tk.TclError, AttributeError):
            pass
        try:
            top = self.winfo_toplevel()
            if (getattr(self, "_pycode_dropdown_hover_switch", False)
                    and _toplevel_has_open_dropdown(top)
                    and getattr(top, "_active_menu_button", None) is not self):
                self._hovered = False
                return
        except tk.TclError:
            pass
        try:
            ancestor = self
            while ancestor is not None:
                if (getattr(ancestor, "_pycode_native_dialog_active", False) or
                        getattr(ancestor, "_native_file_dialog_open", False)):
                    return
                ancestor = getattr(ancestor, "master", None)
        except Exception:
            pass
        if not self._popup_hover_allowed():
            return
        self._hovered = True
        self._paint_hover_state(True)

    def _on_leave(self, _event=None):
        if not self._enabled:
            return
        try:
            ancestor = self
            while ancestor is not None:
                if (getattr(ancestor, "_pycode_native_dialog_active", False) or
                        getattr(ancestor, "_native_file_dialog_open", False)):
                    return
                ancestor = getattr(ancestor, "master", None)
        except Exception:
            pass
        if not self._popup_hover_allowed():
            return
        self._hovered = False
        self._paint_hover_state(False)

    def _hover_state_colors(self, hovered):
        if hovered:
            return (self._normal_active_bg, self._normal_active_fg, self.hover_border)
        return (self.normal_button_bg, self.normal_button_fg, self.normal_border)

    def _paint_hover_colors(self, bg, fg, border):
        self.btn.config(bg=bg, fg=fg)
        self._sync_icon_colors(bg, fg)
        self._button_border_frame.configure(bg=border)

    def _paint_hover_state(self, hovered):
        """Fade to the hover / normal look; fall back to an instant repaint."""
        target = self._hover_state_colors(hovered)
        try:
            start = (str(self.btn.cget("bg")), str(self.btn.cget("fg")),
                     str(self._button_border_frame.cget("bg")))
            signature = (self._normal_active_bg, self.normal_button_bg,
                         self.hover_border, self.normal_border)

            def valid():
                return (self._enabled and not self._is_modal_dimmed()
                        and bool(self._hovered) == bool(hovered)
                        and signature == (self._normal_active_bg, self.normal_button_bg,
                                          self.hover_border, self.normal_border))

            if _hover_fade_colors(
                    self, start, target, self._paint_hover_colors,
                    live_end=lambda: self._hover_state_colors(bool(self._hovered)),
                    valid=valid):
                return
        except (tk.TclError, AttributeError):
            _cancel_hover_fade(self)
        self._paint_hover_colors(*target)

    def _is_modal_dimmed(self):
        try:
            top = self.winfo_toplevel()
            if not getattr(top, "_modal_dim_active", False):
                return False
            state = getattr(top, "_modal_dim_state", None)
            return isinstance(state, dict) and self.btn in state
        except tk.TclError:
            return False

    def reset_visual_state(self, force=False):
        if not self._enabled:
            return
        _cancel_hover_fade(self)
        self._hovered = False
        if not force and self._is_modal_dimmed():
            return
        try:
            # Already in its normal state: nothing to repaint (a repaint re-renders
            # the icon/underline images, which made every window switch costly).
            if (str(self.btn.cget("bg")) == str(self.normal_button_bg)
                    and str(self.btn.cget("fg")) == str(self.normal_button_fg)
                    and str(self._button_border_frame.cget("bg")) == str(self.normal_border)):
                return
        except (tk.TclError, AttributeError):
            pass
        try:
            self.btn.config(bg=self.normal_button_bg, fg=self.normal_button_fg)
            self._sync_icon_colors(self.normal_button_bg, self.normal_button_fg)
            self._button_border_frame.configure(bg=self.normal_border)
        except tk.TclError:
            pass

    def _clear_button_focus(self, _event=None):
        if getattr(self, "_pycode_opens_dropdown_menu", False):
            return
        try:
            top = self.winfo_toplevel()
            target_name = getattr(self, "_pycode_focus_target", None)
            explicit_target = target_name in ("editor", "console")
            if target_name == "editor":
                target = getattr(top, "text", None) or top
            elif target_name == "console":
                target = getattr(top, "console", None) or top
            else:
                target = getattr(self, "_focus_before_mouse_click", None)
                try:
                    if target is not None and not target.winfo_exists():
                        target = None
                except (tk.TclError, AttributeError):
                    target = None
                if target is None or target is self.btn:
                    target = top

            def restore_focus_if_unclaimed(target=target, window=top, explicit=explicit_target):
                try:
                    if (getattr(window, "_modal_dim_active", False)
                            or getattr(window, "_native_file_dialog_open", False)):
                        return
                    current = window.focus_get()
                    if not explicit and current not in (None, self.btn, self, window):
                        return
                    focus_without_raise(target)
                except (tk.TclError, AttributeError):
                    pass

            top.after_idle(restore_focus_if_unclaimed)
        except tk.TclError:
            pass

    @property
    def normal_button_bg(self):
        return getattr(self, "_normal_button_bg", self.btn.cget("bg"))

    @property
    def normal_button_fg(self):
        return getattr(self, "_normal_button_fg", self.btn.cget("fg"))


# Menu buttons
class MenuButton(tk.Frame):
    def __init__(self, master, text, command, enabled=True, normal_fg=None,
                 hover_bg=None, hover_fg=None, hover_text=None, cursor="arrow",
                 icon=None):
        self._command = command
        self._enabled = bool(enabled)
        self._normal_bg = COLORS["menu_bg"]
        self._normal_fg = normal_fg if normal_fg is not None else COLORS["button_secondary_fg"]
        self._hover_bg = hover_bg if hover_bg is not None else COLORS["menu_hover"]
        self._hover_fg = hover_fg if hover_fg is not None else COLORS["button_secondary_fg"]
        self._text_normal = text
        self._text_hover = hover_text if hover_text is not None else text
        self._icon_accent_role = material_menu_accent_role(text)
        self._normal_cursor = cursor or "arrow"
        self._pycode_handles_mouse_click = True
        self._pycode_menu_entry = True
        self._disabled_bg = COLORS["menu_bg"]
        self._disabled_fg = COLORS["muted_text"]
        self._normal_border = button_border_color(self._normal_bg, 0.16)
        self._hover_border = hover_border_color(
            self._normal_bg, self._hover_bg, self._normal_border,
            button_border_color(self._hover_bg, 0.18 if IS_LIGHT_THEME else 0.30),
        )
        self._visual_bg = self._normal_bg if self._enabled else self._disabled_bg
        self._visual_fg = self._normal_fg if self._enabled else self._disabled_fg
        self._hovered = False
        self._kb_focus = False
        self._hover_after_id = None

        super().__init__(
            master, bg=self._visual_bg, bd=0,
            highlightthickness=0,
            highlightbackground=self._visual_bg,
            highlightcolor=self._visual_bg,
            takefocus=0, cursor=self._normal_cursor if self._enabled else "arrow",
        )
        self._icon_slot = tk.Frame(
            self, bg=self._visual_bg, width=ui_px(ICON_CONFIG["layout"]["menu_slot_width"]), bd=0,
            highlightthickness=0, cursor=self._normal_cursor,
        )
        self._icon_slot.pack(
            side="left", fill="y",
            padx=(ui_px(ICON_CONFIG["layout"]["menu_slot_pad_left"]),
                  ui_px(ICON_CONFIG["layout"]["menu_slot_pad_right"])),
        )
        self._icon_slot.pack_propagate(False)
        glyph = icon if icon else None
        self._icon_label = None
        if glyph:
            initial_icon_fg = (
                (icon_pastel_color(self._icon_accent_role) or self._visual_fg)
                if self._enabled else self._visual_fg
            )
            self._icon_label = create_material_icon_label(
                self._icon_slot, glyph, self._visual_bg, initial_icon_fg,
                cursor=self._normal_cursor, raster=True,
            )
            self._icon_label.place(relx=0.5, rely=0.5, anchor="center")
        self._text_gap_pad = 0
        if self._icon_label is not None:
            try:
                slot_right_pad = ui_px(ICON_CONFIG["layout"]["menu_slot_pad_right"])
                desired_gap = ui_px(ICON_CONFIG["layout"]["console_gap"])
                self._text_gap_pad = max(
                    0, int(round(desired_gap - slot_right_pad))
                )
            except (tk.TclError, TypeError, ValueError):
                self._text_gap_pad = 0
        self._text_label = tk.Label(
            self, text=self._text_normal, bg=self._visual_bg, fg=self._visual_fg,
            font=("Cascadia Mono", 9, "normal", "roman"),
            bd=0, highlightthickness=0,
            padx=ui_px(self._text_gap_pad), pady=ui_px(1),
            anchor="w", justify="left", cursor=self._normal_cursor,
        )
        self._text_label.pack(side="left", fill="both", expand=True)

        try:
            top = self.winfo_toplevel()
            legacy_height = getattr(top, "_pycode_legacy_menu_button_height", None)
            if legacy_height is None:
                probe = tk.Button(
                    master, text="Ag", bg=self._normal_bg, fg=self._normal_fg,
                    activebackground=self._hover_bg, activeforeground=self._hover_fg,
                    disabledforeground=self._disabled_fg, relief="flat", bd=0,
                    highlightthickness=1, takefocus=0, default="normal",
                    font=("Cascadia Mono", 9, "normal", "roman"),
                    anchor="w", justify="left", height=1,
                    padx=ui_px(10), pady=ui_px(1), cursor="arrow",
                )
                legacy_height = int(probe.winfo_reqheight())
                probe.destroy()
                setattr(top, "_pycode_legacy_menu_button_height", legacy_height)
            current_height = (
                int(self._text_label.winfo_reqheight())
                + 2 * int(self.cget("highlightthickness"))
            )
            owner = getattr(top, "_pycode_owner", None) or top
            button_size = getattr(owner, "_console_button_outer_size", None)
            target_height = int(button_size() or 0) if callable(button_size) else 0
            if target_height <= 1:
                target_height = int(legacy_height - ui_px(4))
            # Dropdown rows are 4 px shorter than the console buttons; the floor is
            # the bare line height so the label is never clipped.
            target_height = int(target_height - ui_px(4))
            text_floor = (
                int(self._text_label.winfo_reqheight())
                - 2 * int(ui_px(1))
                + 2 * int(self.cget("highlightthickness"))
            )
            target_height = max(text_floor, target_height)
            compact_height = target_height
            extra = max(0, int((compact_height - current_height + 1) // 2))
            if target_height > 1:
                self.configure(height=_dpi_px_from_current_pixels(target_height))
                self.pack_propagate(False)
            self._menu_target_height = target_height
        except (tk.TclError, AttributeError, TypeError, ValueError):
            extra = 0
            self._menu_target_height = None
        base_pad = int(ui_px(1 + extra))
        lift = 0
        try:
            lift = int(_title_ink_lift_px(self._text_label, self._text_label.cget("font")))
        except Exception:
            lift = 0
        try:
            inner_pad = max(0, base_pad - abs(lift))
            self._text_label.configure(pady=_dpi_px_from_current_pixels(inner_pad))
            self._text_label.pack_configure(pady=(
                _dpi_px_from_current_pixels(2 * max(0, -lift)),
                _dpi_px_from_current_pixels(2 * max(0, lift)),
            ))
        except Exception:
            pass
        if self._icon_label is not None:
            try:
                row_h = max(
                    int(self._text_label.winfo_reqheight()) + 2 * abs(lift),
                    int(getattr(self, "_menu_target_height", 0) or 0),
                )
                _font, em_px = _font_pixel_size(self._icon_label, MATERIAL_SYMBOL_FONT)
                slot_w = int(ui_px(ICON_CONFIG["layout"]["menu_slot_width"]))
                box = int(round(em_px)) + 2
                box += box % 2
                box = min(box, slot_w)
                if box % 2 != row_h % 2:
                    box -= 1
                self._icon_label.enable_raster(max(8, box))
            except Exception:
                pass

        for target in (self, self._icon_slot, self._icon_label, self._text_label):
            if target is None:
                continue
            target._pycode_handles_mouse_click = True
            target.bind("<Enter>", self._sync_hover_from_pointer, add="+")
            target.bind("<Leave>", self._sync_hover_from_pointer, add="+")
            target.bind("<Motion>", self._sync_hover_from_pointer, add="+")
            target.bind("<Enter>", self._ensure_disabled_arrow_cursor, add="+")
            target.bind("<Motion>", self._ensure_disabled_arrow_cursor, add="+")
            target.bind("<Button-1>", self._handle_click, add="+")
            target.bind("<ButtonRelease-1>", self._clear_focus, add="+")

    def _ensure_disabled_arrow_cursor(self, _event=None):
        if self._enabled:
            return
        for target in (self, self._icon_slot, self._icon_label, self._text_label):
            if target is None:
                continue
            try:
                if str(target.cget("cursor")) != "arrow":
                    target.configure(cursor="arrow")
            except tk.TclError:
                pass

    def _apply_visuals(self, bg=None, fg=None, border=None, cursor=None, _from_fade=False):
        if not _from_fade:
            _cancel_hover_fade(self)
        if bg is not None:
            self._visual_bg = bg
        if fg is not None:
            self._visual_fg = fg
        if border is None:
            border = self._normal_border
        active_cursor = cursor or (self._normal_cursor if self._enabled else "arrow")
        try:
            tk.Frame.configure(
                self, bg=self._visual_bg,
                highlightbackground=border, highlightcolor=border,
                cursor=active_cursor,
            )
        except tk.TclError:
            pass
        for target in (self._icon_slot, self._icon_label, self._text_label):
            if target is None:
                continue
            try:
                if isinstance(target, tk.Label):
                    target_fg = self._visual_fg
                    if target is self._icon_label and self._enabled:
                        target_fg = icon_pastel_color(self._icon_accent_role) or self._visual_fg
                    target.configure(bg=self._visual_bg, fg=target_fg,
                                     cursor=active_cursor)
                else:
                    target.configure(bg=self._visual_bg, cursor=active_cursor)
            except tk.TclError:
                pass

    def configure(self, cnf=None, **kwargs):
        if cnf is not None:
            if isinstance(cnf, dict):
                options = dict(cnf)
                options.update(kwargs)
                kwargs = options
            elif not kwargs:
                return tk.Frame.configure(self, cnf)
        if not kwargs:
            return tk.Frame.configure(self)
        options = dict(kwargs)
        text = options.pop("text", None)
        bg = options.pop("bg", options.pop("background", None))
        fg = options.pop("fg", options.pop("foreground", None))
        options.pop("activebackground", None)
        options.pop("activeforeground", None)
        options.pop("disabledforeground", None)
        options.pop("state", None)
        highlight_bg = options.pop("highlightbackground", None)
        highlight_fg = options.pop("highlightcolor", None)
        cursor = options.get("cursor", None)
        if text is not None:
            self._text_normal = str(text)
            self._text_label.configure(text=self._text_normal)
        border = highlight_bg if highlight_bg is not None else highlight_fg
        self._apply_visuals(bg=bg, fg=fg, border=border, cursor=cursor)
        frame_options = {}
        for key, value in options.items():
            if key in ("cursor", "bd", "borderwidth", "relief", "highlightthickness",
                       "takefocus", "width", "height", "padx", "pady"):
                frame_options[key] = value
        if frame_options:
            try:
                return tk.Frame.configure(self, **frame_options)
            except tk.TclError:
                pass
        return None

    config = configure

    def cget(self, key):
        key = str(key)
        if key == "text":
            return self._text_normal
        if key in ("bg", "background"):
            return self._visual_bg
        if key in ("fg", "foreground"):
            return self._visual_fg
        if key == "state":
            return "normal" if self._enabled else "disabled"
        if key == "cursor":
            return self._normal_cursor if self._enabled else "arrow"
        return tk.Frame.cget(self, key)

    def set_enabled(self, enabled):
        self._enabled = bool(enabled)
        self._hovered = False
        self._kb_focus = False
        bg = self._normal_bg if self._enabled else self._disabled_bg
        fg = self._normal_fg if self._enabled else self._disabled_fg
        self._apply_visuals(bg=bg, fg=fg, border=self._normal_border,
                            cursor=self._normal_cursor if self._enabled else "arrow")

    def set_keyboard_focus(self, on):
        on = bool(on) and self._enabled
        if on == self._kb_focus and on == self._hovered:
            return
        self._kb_focus = on
        self._hovered = on
        if on:
            self._apply_visuals(bg=self._hover_bg, fg=self._hover_fg, border=self._normal_border)
        else:
            bg = self._normal_bg if self._enabled else self._disabled_bg
            fg = self._normal_fg if self._enabled else self._disabled_fg
            self._apply_visuals(bg=bg, fg=fg, border=self._normal_border)

    def _pointer_is_inside(self):
        try:
            x, y = self.winfo_pointerx(), self.winfo_pointery()
            left, top = self.winfo_rootx(), self.winfo_rooty()
            return left <= x < left + self.winfo_width() and top <= y < top + self.winfo_height()
        except tk.TclError:
            return False

    def _keyboard_nav_blocks_hover(self):
        try:
            blocker = getattr(self.winfo_toplevel(), "_pointer_hover_blocked_by_keyboard", None)
            return bool(callable(blocker) and blocker())
        except (tk.TclError, AttributeError):
            return False

    def _sync_hover_from_pointer(self, _event=None):
        if _event is not None and self._keyboard_nav_blocks_hover():
            return
        if self._hover_after_id is not None:
            return
        try:
            self._hover_after_id = self.after_idle(self._apply_pointer_hover)
        except tk.TclError:
            self._hover_after_id = None

    def _apply_pointer_hover(self):
        self._hover_after_id = None
        if not self._enabled:
            self._ensure_disabled_arrow_cursor()
        if self._kb_focus:
            return
        if self._keyboard_nav_blocks_hover():
            return
        if self._pointer_is_inside():
            self._on_enter()
        else:
            self._on_leave()

    def _handle_click(self, _event=None):
        if self.__dict__.get("_pycode_menu_fading"):
            return "break"
        if self._enabled and self._command:
            self._pycode_preserve_command_focus = True
            try:
                self.after(500, lambda: setattr(self, "_pycode_preserve_command_focus", False))
            except tk.TclError:
                pass
            self._command()
        return "break"

    def _on_enter(self, _event=None):
        if not self._enabled or self._hovered or self.__dict__.get("_pycode_menu_fading"):
            return
        self._hovered = True
        self._fade_visuals(True)

    def _on_leave(self, _event=None):
        if not self._hovered:
            return
        self._hovered = False
        self._kb_focus = False
        self._fade_visuals(False)

    def _visual_state_colors(self, hovered):
        if hovered and self._enabled:
            return (self._hover_bg, self._hover_fg)
        if self._enabled:
            return (self._normal_bg, self._normal_fg)
        return (self._disabled_bg, self._disabled_fg)

    def _fade_visuals(self, hovered):
        target = self._visual_state_colors(hovered)
        try:
            start = (self._visual_bg, self._visual_fg)
            signature = (self._hover_bg, self._hover_fg, self._normal_bg, self._normal_fg)

            def paint(bg, fg):
                self._apply_visuals(bg=bg, fg=fg, border=self._normal_border, _from_fade=True)

            def valid():
                return (not self._kb_focus
                        and bool(self._hovered) == bool(hovered)
                        and signature == (self._hover_bg, self._hover_fg,
                                          self._normal_bg, self._normal_fg))

            if _hover_fade_colors(
                    self, start, target, paint,
                    live_end=lambda: self._visual_state_colors(bool(self._hovered)),
                    valid=valid):
                return
        except (tk.TclError, AttributeError):
            _cancel_hover_fade(self)
        self._apply_visuals(bg=target[0], fg=target[1], border=self._normal_border)

    def _clear_focus(self, _event=None):
        if getattr(self, "_pycode_preserve_command_focus", False):
            return
        try:
            if self.focus_get() is self:
                self.winfo_toplevel().focus_set()
        except tk.TclError:
            pass


def _bind_border_effect(outer, watched_widgets):
    outer._border_hover = False
    outer._border_focus = False
    outer._border_normal = COLORS["border_dark"]
    outer._border_hover_color = outer._border_normal
    outer._border_focus_color = outer._border_normal

    def is_descendant(widget, parent):
        current = widget
        while current is not None:
            if current is parent:
                return True
            current = getattr(current, "master", None)
        return False

    def refresh_hover():
        outer._border_hover = False
        refresh()

    def refresh_focus():
        try:
            focused = outer.focus_get()
            outer._border_focus = focused is not None and is_descendant(focused, outer)
        except tk.TclError:
            outer._border_focus = False
        refresh()

    def refresh():
        try:
            if getattr(outer.winfo_toplevel(), "_modal_dim_active", False):
                outer.configure(bg=getattr(outer, "_modal_dim_color",
                                           modal_dim_color(outer._border_normal, widget=outer)))
                return
        except tk.TclError:
            pass
        if outer._border_focus:
            color = outer._border_focus_color
        elif outer._border_hover:
            color = outer._border_hover_color
        else:
            color = outer._border_normal
        outer.configure(bg=color)

    def on_enter(_event=None):
        if outer._border_focus:
            refresh()

    def on_leave(_event=None):
        if not outer._border_focus:
            refresh()

    def on_focus_in(_event=None):
        try:
            if getattr(outer.winfo_toplevel(), "_modal_dim_active", False):
                return
        except tk.TclError:
            pass
        outer._border_focus = True
        refresh()

    def on_focus_out(_event=None):
        try:
            if getattr(outer.winfo_toplevel(), "_modal_dim_active", False):
                return
        except tk.TclError:
            pass
        outer.after_idle(refresh_focus)

    widgets = [outer, *watched_widgets]
    for widget in widgets:
        widget.bind("<Enter>", on_enter, add="+")
        widget.bind("<Leave>", on_leave, add="+")
        widget.bind("<FocusIn>", on_focus_in, add="+")
        widget.bind("<FocusOut>", on_focus_out, add="+")

    refresh()


def loading_bar_contrast_color(light=None):
    if light is None:
        light = ACTIVE_THEME != THEME_DARK
    return "#000000" if light else "#FFFFFF"


def create_stable_modal_shell(parent, content_padx=0, content_pady=0, min_width=None, fixed_width=None,
                              as_toplevel=False):
    previous_focus = None
    try:
        previous_focus = parent.focus_get()
    except (tk.TclError, AttributeError):
        pass

    if hasattr(parent, "_activate_modal_background"):
        try:
            if as_toplevel:
                parent._activate_modal_background(overlay_mode=True)
            else:
                parent._activate_modal_background()
        except (AttributeError, tk.TclError):
            pass

    if as_toplevel:
        outer = tk.Toplevel(
            parent,
            bg=COLORS["modal_outline"],
            bd=0,
            highlightthickness=0,
            takefocus=1,
            padx=ui_px(1),
            pady=ui_px(1),
        )
        outer.withdraw()
        outer.overrideredirect(True)
        try:
            outer.attributes("-alpha", 0.0)
        except tk.TclError:
            pass
    else:
        outer = tk.Frame(
            parent,
            bg=COLORS["modal_outline"],
            bd=0,
            highlightthickness=0,
            takefocus=1,
            padx=ui_px(1),
            pady=ui_px(1),
        )

    outer._pycode_close_callback = None
    outer._pycode_popup_outline = True
    outer._pycode_owner = getattr(parent, "_pycode_owner", None) or parent
    outer._pycode_previous_focus = previous_focus
    try:
        parent._active_modal_widget = outer
        parent._pycode_pending_modal_focus = previous_focus
    except Exception:
        pass

    inner_outline = tk.Frame(
        outer,
        bg=COLORS["border_dark"],
        bd=0,
        highlightthickness=0,
        takefocus=0,
        padx=ui_px(1),
        pady=ui_px(1),
    )
    inner_outline._pycode_popup_inner_outline = True
    inner_outline.pack(fill="both", expand=True)

    mid = tk.Frame(
        inner_outline,
        bg=COLORS["panel_bg_dark"],
        bd=0,
        highlightthickness=0,
        takefocus=0,
        padx=ui_px(6),
        pady=ui_px(6),
    )
    mid.pack(fill="both", expand=True)

    inner = tk.Frame(
        mid,
        bg=COLORS["panel_border"],
        bd=0,
        highlightthickness=0,
        takefocus=0,
        padx=ui_px(1),
        pady=ui_px(1),
    )
    inner.pack(fill="both", expand=True)

    content = tk.Frame(
        inner,
        bg=COLORS["bg_main"],
        bd=0,
        highlightthickness=0,
        takefocus=0,
        padx=ui_px(content_padx),
        pady=ui_px(content_pady),
    )
    content.pack(fill="both", expand=True)

    requested_min_width = ui_px(min_width) if min_width is not None else None
    requested_fixed_width = ui_px(fixed_width) if fixed_width is not None else None
    placed = {"done": False}

    def finalize_modal_geometry():
        if placed["done"] or getattr(outer, "_pycode_defer_modal_geometry", False):
            return
        try:
            outer.update_idletasks()
            button_owner = getattr(parent, "_pycode_owner", None) or parent
            sync_popup_buttons = getattr(button_owner, "_sync_popup_button_metrics", None)
            if callable(sync_popup_buttons):
                sync_popup_buttons(outer)
                outer.update_idletasks()
            req_width = outer.winfo_reqwidth()
            req_height = outer.winfo_reqheight()
            if requested_fixed_width is not None:
                final_width = requested_fixed_width
            elif requested_min_width is not None:
                final_width = max(req_width, requested_min_width)
            else:
                final_width = req_width

            if as_toplevel:
                outer._pycode_modal_size = (int(final_width), int(req_height))
                outer._pycode_place_over_parent(0, with_size=True)
            else:
                outer.place(
                    relx=0.5, rely=0.5, anchor="center",
                    width=_dpi_px_from_current_pixels(final_width),
                    height=_dpi_px_from_current_pixels(req_height),
                )
            placed["done"] = True
        except tk.TclError:
            pass

    def place_over_parent(offset_y=0, with_size=False):
        """Centre this top-level modal over its parent window (real pixels)."""
        size = getattr(outer, "_pycode_modal_size", None)
        if not size:
            return
        width, height = size
        pos_x = parent.winfo_rootx() + (parent.winfo_width() - width) // 2
        pos_y = parent.winfo_rooty() + (parent.winfo_height() - height) // 2 + int(offset_y)
        if with_size:
            outer.geometry(f"{width}x{height}+{pos_x}+{pos_y}")
        else:
            outer.geometry(f"+{pos_x}+{pos_y}")

    outer._pycode_place_over_parent = place_over_parent
    outer._pycode_finalize_modal_geometry = finalize_modal_geometry
    outer.after_idle(finalize_modal_geometry)
    return outer, content


def _ease_out_cubic(progress):
    return 1.0 - (1.0 - progress) ** 3


def _ease_in_out_sine(progress):
    return 0.5 - 0.5 * math.cos(math.pi * progress)


HOVER_FADE_MS = 90
_HOVER_FADE_STEPS = 12


def _cancel_hover_fade(widget):
    state = widget.__dict__.get("_pycode_hover_fade")
    widget._pycode_hover_fade = None
    if state is not None:
        try:
            state["cancel"]()
        except (tk.TclError, KeyError, TypeError):
            pass


def _hover_fade_colors(widget, start, end, apply, live_end, valid=None,
                       duration_ms=HOVER_FADE_MS):
    """Discreet colour fade from ``start`` to ``end`` (tuples of ``#RRGGBB``).

    ``apply(*colors)`` paints one frame.  ``live_end()`` returns the colours the
    widget should have *right now*; it is used to settle if something changed
    while fading (theme switch, ``valid()`` turning False).  Returns False when no
    fade was started, in which case the caller paints ``end`` itself.  Any
    previous fade on the widget is always cancelled first, so two fades never
    fight over the same widget.
    """
    _cancel_hover_fade(widget)
    if tuple(start) == tuple(end):
        return False
    try:
        top = widget.winfo_toplevel()
        tween = getattr(top, "_tween", None)
        if (not callable(tween)
                or not widget.winfo_ismapped()
                or getattr(top, "_theme_transition_in_progress", False)
                or getattr(top, "_shutting_down", False)
                or not all(_is_plain_hex(c) for c in tuple(start) + tuple(end))):
            return False
    except tk.TclError:
        return False

    last = [None]

    def settle():
        _cancel_hover_fade(widget)
        try:
            apply(*live_end())
        except tk.TclError:
            pass

    def step(eased):
        if valid is not None and not valid():
            settle()
            return
        amount = round(eased * _HOVER_FADE_STEPS) / _HOVER_FADE_STEPS
        frame = tuple(color_mix(a, b, amount) for a, b in zip(start, end))
        if frame == last[0]:
            return
        last[0] = frame
        apply(*frame)

    def done():
        widget._pycode_hover_fade = None
        if valid is None or valid():
            apply(*end)
        else:
            settle()

    widget._pycode_hover_fade = tween(duration_ms, step, done=done)
    return True


def _smooth_follow_factor(state, base=0.30, base_dt=0.010):
    """Share of the remaining distance to cover this frame, from the real frame time.

    ``base`` is the share per ``base_dt`` seconds.  A late frame covers more, an
    early one less, so the motion keeps the same speed whatever the timer jitter.
    """
    now = time.perf_counter()
    last = state.get("_follow_t_last")
    state["_follow_t_last"] = now
    dt = base_dt if last is None or now - last > 0.05 else max(0.001, now - last)
    return 1.0 - (1.0 - base) ** (dt / base_dt)


def pack_separator_with_shadow(sep, padx=0, pady=(0, 10)):
    if isinstance(pady, (tuple, list)):
        pad_top, pad_bottom = pady[0], pady[1]
    else:
        pad_top = pad_bottom = pady
    sep.pack(fill="x", padx=padx, pady=(pad_top, 0))
    shadow = tk.Frame(sep.master, bg=COLORS["modal_outline"], height=ui_px(1), bd=0,
                      highlightthickness=0)
    shadow._pycode_popup_outline = True
    shadow.pack(fill="x", padx=padx, pady=(0, pad_bottom))
    sep._pycode_shadow = shadow
    return shadow


def _build_variables_pdf_bytes_legacy(rows, title="PyCode Variables"):
    page_width, page_height = 842.0, 595.0
    margin = 40.0
    table_width = page_width - 2.0 * margin
    column_widths = (150.0, 116.0, table_width - 266.0)
    column_x = (
        margin,
        margin + column_widths[0],
        margin + column_widths[0] + column_widths[1],
    )
    font_size = 7.0
    line_height = 8.5
    bottom_margin = 34.0
    generated = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
    page_streams = []
    commands = []

    def pdf_hex(value):
        raw = str(value).encode("cp1252", errors="replace")
        return "<" + raw.hex().upper() + ">"

    def draw_text(value, x, baseline_from_top, size=font_size, bold=False):
        font_name = "F2" if bold else "F1"
        baseline = page_height - float(baseline_from_top)
        commands.append(
            f"BT /{font_name} {float(size):.2f} Tf 0 g "
            f"1 0 0 1 {float(x):.2f} {baseline:.2f} Tm {pdf_hex(value)} Tj ET"
        )

    def horizontal_rule(y, gray=0.0, width=0.45):
        py = page_height - float(y)
        commands.append(
            f"0 G {width:.2f} w {margin:.2f} {py:.2f} m "
            f"{page_width - margin:.2f} {py:.2f} l S"
        )

    def vertical_rule(x, y_top, y_bottom):
        commands.append(
            f"0 G 0.35 w {float(x):.2f} {page_height - float(y_top):.2f} m "
            f"{float(x):.2f} {page_height - float(y_bottom):.2f} l S"
        )

    def start_page():
        nonlocal commands
        commands = []
        clean_title = str(title).replace("PyCode", "").strip(" -:") or str(title)
        draw_text("PyCode", margin, 22, size=7, bold=True)
        draw_text(clean_title, margin, 40, size=12, bold=True)
        draw_text(f"Saved {generated}", margin, 53, size=7)
        table_top = 68.0
        header_height = 18.0
        draw_text("Name", column_x[0] + 6, table_top + 12, size=font_size, bold=True)
        draw_text("Type", column_x[1] + 6, table_top + 12, size=font_size, bold=True)
        draw_text("Value", column_x[2] + 6, table_top + 12, size=font_size, bold=True)
        horizontal_rule(table_top, width=0.65)
        horizontal_rule(table_top + header_height, width=0.65)
        return table_top + header_height

    def wrap_cell(value, width):
        text = str(value).replace("\t", "    ").replace("\r", " ").replace("\n", " ")
        max_chars = max(8, int((float(width) - 12.0) / (font_size * 0.60)))
        return textwrap.wrap(
            text, width=max_chars, break_long_words=True,
            break_on_hyphens=False, replace_whitespace=True,
        ) or [""]

    y = start_page()
    normalized_rows = list(rows or ())
    if not normalized_rows:
        draw_text("No variables to export.", margin + 6, y + 14)
        y += 22.0
        horizontal_rule(y, gray=0.78)
    else:
        for name, type_name, value, _kind in normalized_rows:
            cells = (str(name), str(type_name), str(value))
            wrapped = [
                wrap_cell(cells[index], column_widths[index])
                for index in range(3)
            ]
            line_count = max(len(cell_lines) for cell_lines in wrapped)
            row_height = max(16.0, line_count * line_height + 6.0)
            if y + row_height > page_height - bottom_margin:
                horizontal_rule(y, gray=0.58, width=0.7)
                for x in (column_x[1], column_x[2]):
                    vertical_rule(x, 70.0, y)
                page_streams.append("\n".join(commands).encode("ascii"))
                y = start_page()

            for column_index, cell_lines in enumerate(wrapped):
                x = column_x[column_index] + 6.0
                for line_index, line in enumerate(cell_lines):
                    draw_text(line, x, y + 12.0 + line_index * line_height)
            y += row_height
            horizontal_rule(y, gray=0.86, width=0.35)

        horizontal_rule(y, gray=0.58, width=0.7)
        for x in (column_x[1], column_x[2]):
            vertical_rule(x, 70.0, y)

    page_streams.append("\n".join(commands).encode("ascii"))

    page_ids = [5 + index * 2 for index in range(len(page_streams))]
    objects = {
        1: b"<< /Type /Catalog /Pages 2 0 R >>",
        2: (
            "<< /Type /Pages /Kids ["
            + " ".join(f"{page_id} 0 R" for page_id in page_ids)
            + f"] /Count {len(page_ids)} >>"
        ).encode("ascii"),
        3: b"<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>",
        4: b"<< /Type /Font /Subtype /Type1 /BaseFont /Courier-Bold /Encoding /WinAnsiEncoding >>",
    }
    for index, stream in enumerate(page_streams):
        page_id = page_ids[index]
        content_id = page_id + 1
        objects[page_id] = (
            f"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 {page_width:.0f} {page_height:.0f}] "
            f"/Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents {content_id} 0 R >>"
        ).encode("ascii")
        objects[content_id] = (
            f"<< /Length {len(stream)} >>\nstream\n".encode("ascii")
            + stream + b"\nendstream"
        )

    output = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = [0]
    for object_id in range(1, max(objects) + 1):
        offsets.append(len(output))
        output.extend(f"{object_id} 0 obj\n".encode("ascii"))
        output.extend(objects[object_id])
        output.extend(b"\nendobj\n")
    xref_offset = len(output)
    output.extend(f"xref\n0 {len(offsets)}\n".encode("ascii"))
    output.extend(b"0000000000 65535 f \n")
    for offset in offsets[1:]:
        output.extend(f"{offset:010d} 00000 n \n".encode("ascii"))
    output.extend(
        f"trailer\n<< /Size {len(offsets)} /Root 1 0 R >>\n"
        f"startxref\n{xref_offset}\n%%EOF\n".encode("ascii")
    )
    return bytes(output)


def _build_variables_pdf_bytes(rows, title="PyCode Variables"):
    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        from reportlab.platypus import LongTable, Paragraph, SimpleDocTemplate, Spacer, TableStyle
        from xml.sax.saxutils import escape
    except Exception:
        return _build_variables_pdf_bytes_legacy(rows, title=title)

    font_path = None
    bold_path = None
    try:
        _regular_name, font_path = _find_embedded_font("regular")
        _bold_name, bold_path = _find_embedded_font("bold")
    except Exception:
        pass
    if not font_path or not os.path.isfile(font_path):
        return _build_variables_pdf_bytes_legacy(rows, title=title)

    regular_font = "PyCodeCascadiaMono"
    bold_font = "PyCodeCascadiaMonoBold"
    try:
        if regular_font not in pdfmetrics.getRegisteredFontNames():
            pdfmetrics.registerFont(TTFont(regular_font, font_path))
        if bold_path and os.path.isfile(bold_path):
            if bold_font not in pdfmetrics.getRegisteredFontNames():
                pdfmetrics.registerFont(TTFont(bold_font, bold_path))
        else:
            bold_font = regular_font
        pdfmetrics.registerFontFamily(
            regular_font, normal=regular_font, bold=bold_font,
            italic=regular_font, boldItalic=bold_font,
        )
    except Exception:
        return _build_variables_pdf_bytes_legacy(rows, title=title)

    page_size = landscape(A4)
    page_width, page_height = page_size
    margin_x = 14 * mm
    margin_top = 13 * mm
    margin_bottom = 14 * mm
    usable_width = page_width - 2 * margin_x
    generated = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")

    buffer = io.BytesIO()
    document = SimpleDocTemplate(
        buffer, pagesize=page_size,
        leftMargin=margin_x, rightMargin=margin_x,
        topMargin=margin_top, bottomMargin=margin_bottom,
        title=str(title), author="PyCode",
    )
    title_style = ParagraphStyle(
        "PyCodeVariableTitle", fontName=bold_font, fontSize=12,
        leading=15, textColor=colors.HexColor("#202020"),
        spaceAfter=3, alignment=0,
    )
    meta_style = ParagraphStyle(
        "PyCodeVariableMeta", fontName=regular_font, fontSize=7.5,
        leading=9, textColor=colors.HexColor("#555555"), spaceAfter=8,
    )
    header_style = ParagraphStyle(
        "PyCodeVariableHeader", fontName=bold_font, fontSize=8,
        leading=10, textColor=colors.HexColor("#202020"),
    )
    cell_style = ParagraphStyle(
        "PyCodeVariableCell", fontName=regular_font, fontSize=7.5,
        leading=9.2, textColor=colors.HexColor("#202020"),
        wordWrap="CJK", splitLongWords=1,
    )

    def cell(value, style):
        text = str(value).replace("\t", "    ").replace("\r", " ")
        text = escape(text).replace("\n", "<br/>")
        return Paragraph(text or " ", style)

    story = [
        Paragraph(escape(str(title)), title_style),
        Paragraph("Saved " + escape(generated), meta_style),
    ]
    table_data = [[
        cell("Name", header_style),
        cell("Type", header_style),
        cell("Value", header_style),
    ]]
    for name, type_name, value, _kind in list(rows or ()):
        table_data.append([
            cell(name, cell_style),
            cell(type_name, cell_style),
            cell(value, cell_style),
        ])
    if len(table_data) == 1:
        table_data.append([cell("No variables to export.", cell_style), cell("", cell_style), cell("", cell_style)])

    column_widths = (usable_width * 0.23, usable_width * 0.17, usable_width * 0.60)
    table = LongTable(
        table_data, colWidths=column_widths, repeatRows=1,
        hAlign="LEFT", splitByRow=1,
    )
    table.setStyle(TableStyle([
        ("GRID", (0, 0), (-1, -1), 0.45, colors.HexColor("#555555")),
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E9ECEF")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LEFTPADDING", (0, 0), (-1, -1), 6),
        ("RIGHTPADDING", (0, 0), (-1, -1), 6),
        ("TOPPADDING", (0, 0), (-1, -1), 5),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    story.extend((table, Spacer(1, 2)))

    def draw_page(canvas, doc):
        canvas.saveState()
        canvas.setFont(regular_font, 7)
        canvas.setFillColor(colors.HexColor("#666666"))
        canvas.drawRightString(page_width - margin_x, 7 * mm, f"Page {doc.page}")
        canvas.restoreState()

    document.build(story, onFirstPage=draw_page, onLaterPages=draw_page)
    return buffer.getvalue()


def _build_variables_xlsx_bytes(rows, title="PyCode Variables"):
    import zipfile
    import xml.etree.ElementTree as ET

    main_ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    rel_ns = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
    package_rel_ns = "http://schemas.openxmlformats.org/package/2006/relationships"
    content_ns = "http://schemas.openxmlformats.org/package/2006/content-types"
    ET.register_namespace("", main_ns)
    ET.register_namespace("r", rel_ns)

    def q(ns, name):
        return "{" + ns + "}" + name

    root_types = ET.Element(q(content_ns, "Types"))
    ET.SubElement(root_types, q(content_ns, "Default"), {"Extension": "rels", "ContentType": "application/vnd.openxmlformats-package.relationships+xml"})
    ET.SubElement(root_types, q(content_ns, "Default"), {"Extension": "xml", "ContentType": "application/xml"})
    ET.SubElement(root_types, q(content_ns, "Override"), {"PartName": "/xl/workbook.xml", "ContentType": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"})
    ET.SubElement(root_types, q(content_ns, "Override"), {"PartName": "/xl/worksheets/sheet1.xml", "ContentType": "application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"})
    ET.SubElement(root_types, q(content_ns, "Override"), {"PartName": "/xl/styles.xml", "ContentType": "application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"})
    ET.SubElement(root_types, q(content_ns, "Override"), {"PartName": "/xl/sharedStrings.xml", "ContentType": "application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"})

    package_rels = ET.Element(q(package_rel_ns, "Relationships"))
    ET.SubElement(package_rels, q(package_rel_ns, "Relationship"), {
        "Id": "rId1", "Type": "http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument", "Target": "xl/workbook.xml"
    })

    workbook = ET.Element(q(main_ns, "workbook"))
    sheets = ET.SubElement(workbook, q(main_ns, "sheets"))
    ET.SubElement(sheets, q(main_ns, "sheet"), {"name": "Variables", "sheetId": "1", q(rel_ns, "id"): "rId1"})
    workbook_rels = ET.Element(q(package_rel_ns, "Relationships"))
    ET.SubElement(workbook_rels, q(package_rel_ns, "Relationship"), {
        "Id": "rId1", "Type": "http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet", "Target": "worksheets/sheet1.xml"
    })
    ET.SubElement(workbook_rels, q(package_rel_ns, "Relationship"), {
        "Id": "rId2", "Type": "http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles", "Target": "styles.xml"
    })
    ET.SubElement(workbook_rels, q(package_rel_ns, "Relationship"), {
        "Id": "rId3", "Type": "http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings", "Target": "sharedStrings.xml"
    })

    styles = ET.Element(q(main_ns, "styleSheet"))
    fonts = ET.SubElement(styles, q(main_ns, "fonts"), {"count": "2"})
    f0 = ET.SubElement(fonts, q(main_ns, "font")); ET.SubElement(f0, q(main_ns, "sz"), {"val": "10"}); ET.SubElement(f0, q(main_ns, "name"), {"val": "Cascadia Mono"})
    f1 = ET.SubElement(fonts, q(main_ns, "font")); ET.SubElement(f1, q(main_ns, "b")); ET.SubElement(f1, q(main_ns, "sz"), {"val": "10"}); ET.SubElement(f1, q(main_ns, "name"), {"val": "Cascadia Mono"})
    fills = ET.SubElement(styles, q(main_ns, "fills"), {"count": "2"})
    fill0 = ET.SubElement(fills, q(main_ns, "fill")); ET.SubElement(fill0, q(main_ns, "patternFill"), {"patternType": "none"})
    fill1 = ET.SubElement(fills, q(main_ns, "fill")); pf = ET.SubElement(fill1, q(main_ns, "patternFill"), {"patternType": "solid"}); ET.SubElement(pf, q(main_ns, "fgColor"), {"rgb": "FFE9ECEF"}); ET.SubElement(pf, q(main_ns, "bgColor"), {"indexed": "64"})
    borders = ET.SubElement(styles, q(main_ns, "borders"), {"count": "2"})
    border0 = ET.SubElement(borders, q(main_ns, "border")); [ET.SubElement(border0, q(main_ns, side)) for side in ("left", "right", "top", "bottom", "diagonal")]
    border1 = ET.SubElement(borders, q(main_ns, "border"))
    for side in ("left", "right", "top", "bottom"):
        part = ET.SubElement(border1, q(main_ns, side), {"style": "thin"}); ET.SubElement(part, q(main_ns, "color"), {"rgb": "FFB7B7B7"})
    ET.SubElement(border1, q(main_ns, "diagonal"))
    cell_styles = ET.SubElement(styles, q(main_ns, "cellStyleXfs"), {"count": "1"}); ET.SubElement(cell_styles, q(main_ns, "xf"), {"numFmtId": "0", "fontId": "0", "fillId": "0", "borderId": "0"})
    xfs = ET.SubElement(styles, q(main_ns, "cellXfs"), {"count": "2"})
    ET.SubElement(xfs, q(main_ns, "xf"), {"numFmtId": "0", "fontId": "0", "fillId": "0", "borderId": "1", "xfId": "0", "applyBorder": "1"})
    ET.SubElement(xfs, q(main_ns, "xf"), {"numFmtId": "0", "fontId": "1", "fillId": "1", "borderId": "1", "xfId": "0", "applyFont": "1", "applyFill": "1", "applyBorder": "1", "applyAlignment": "1"})
    cell_styles2 = ET.SubElement(styles, q(main_ns, "cellStyles"), {"count": "1"}); ET.SubElement(cell_styles2, q(main_ns, "cellStyle"), {"name": "Normal", "xfId": "0", "builtinId": "0"})

    def excel_col(index):
        result = ""
        while index:
            index, remainder = divmod(index - 1, 26)
            result = chr(65 + remainder) + result
        return result

    normalized = [("Name", "Type", "Value")]
    normalized.extend((str(name), str(type_name), str(value)) for name, type_name, value, _kind in list(rows or ()))
    shared_values = []
    shared_index = {}
    for row_values in normalized:
        for value in row_values:
            clean_value = str(value)[:32767]
            if clean_value not in shared_index:
                shared_index[clean_value] = len(shared_values)
                shared_values.append(clean_value)
    shared_strings = ET.Element(q(main_ns, "sst"), {
        "count": str(sum(len(row) for row in normalized)),
        "uniqueCount": str(len(shared_values)),
    })
    for value in shared_values:
        item = ET.SubElement(shared_strings, q(main_ns, "si"))
        text_node = ET.SubElement(item, q(main_ns, "t"))
        text_node.set("{http://www.w3.org/XML/1998/namespace}space", "preserve")
        text_node.text = value

    worksheet = ET.Element(q(main_ns, "worksheet"))
    views = ET.SubElement(worksheet, q(main_ns, "sheetViews")); view = ET.SubElement(views, q(main_ns, "sheetView"), {"workbookViewId": "0"})
    ET.SubElement(view, q(main_ns, "pane"), {"ySplit": "1", "topLeftCell": "A2", "activePane": "bottomLeft", "state": "frozen"})
    ET.SubElement(view, q(main_ns, "selection"), {"pane": "bottomLeft", "activeCell": "A2", "sqref": "A2"})
    ET.SubElement(worksheet, q(main_ns, "sheetFormatPr"), {"defaultRowHeight": "18"})
    columns = ET.SubElement(worksheet, q(main_ns, "cols"))
    for index, width in enumerate((28, 20, 100), 1):
        ET.SubElement(columns, q(main_ns, "col"), {"min": str(index), "max": str(index), "width": str(width), "customWidth": "1"})
    sheet_data = ET.SubElement(worksheet, q(main_ns, "sheetData"))
    for row_index, row_values in enumerate(normalized, 1):
        row_node = ET.SubElement(sheet_data, q(main_ns, "row"), {"r": str(row_index)})
        for col_index, value in enumerate(row_values, 1):
            address = f"{excel_col(col_index)}{row_index}"
            cell_node = ET.SubElement(row_node, q(main_ns, "c"), {"r": address, "s": "1" if row_index == 1 else "0", "t": "s"})
            ET.SubElement(cell_node, q(main_ns, "v")).text = str(shared_index[str(value)[:32767]])
    ET.SubElement(worksheet, q(main_ns, "autoFilter"), {"ref": f"A1:C{max(1, len(normalized))}"})
    ET.SubElement(worksheet, q(main_ns, "pageMargins"), {"left": "0.25", "right": "0.25", "top": "0.5", "bottom": "0.5", "header": "0.2", "footer": "0.2"})

    def xml_bytes(element, default_namespace=None):
        if default_namespace:
            ET.register_namespace("", default_namespace)
        return ET.tostring(element, encoding="utf-8", xml_declaration=True)

    output = io.BytesIO()
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        archive.writestr("[Content_Types].xml", xml_bytes(root_types, content_ns))
        archive.writestr("_rels/.rels", xml_bytes(package_rels, package_rel_ns))
        archive.writestr("xl/workbook.xml", xml_bytes(workbook, main_ns))
        archive.writestr("xl/_rels/workbook.xml.rels", xml_bytes(workbook_rels, package_rel_ns))
        archive.writestr("xl/styles.xml", xml_bytes(styles, main_ns))
        archive.writestr("xl/sharedStrings.xml", xml_bytes(shared_strings, main_ns))
        archive.writestr("xl/worksheets/sheet1.xml", xml_bytes(worksheet, main_ns))
    return output.getvalue()


