def install_smooth_canvas_scroll(canvas, scheduler, wheel_widgets=(), pixels_per_notch=60):
    state = {"offset": 0.0, "target": 0.0, "after": None}

    def metrics():
        try:
            raw = canvas.cget("scrollregion")
            parts = tuple(float(value) for value in str(raw).split()) if raw else ()
            if len(parts) == 4:
                total = max(1.0, parts[3] - parts[1])
            else:
                bbox = canvas.bbox("all")
                total = max(1.0, float(bbox[3] - bbox[1])) if bbox else 1.0
            viewport = max(1.0, float(canvas.winfo_height()))
            total = max(total, viewport)
            return total, viewport, max(0.0, total - viewport)
        except (tk.TclError, TypeError, ValueError, IndexError):
            return 1.0, 1.0, 0.0

    def cancel():
        pending = state.get("after")
        if pending is not None:
            try:
                scheduler.after_cancel(pending)
            except tk.TclError:
                pass
            state["after"] = None

    def sync(cancel_pending=False):
        if cancel_pending:
            cancel()
        total, _viewport, limit = metrics()
        try:
            first = float(canvas.yview()[0])
        except (tk.TclError, TypeError, ValueError, IndexError):
            first = 0.0
        offset = min(limit, max(0.0, first * total))
        state["offset"] = offset
        state["target"] = offset
        return offset

    def apply_offset(value):
        total, _viewport, limit = metrics()
        value = min(max(0.0, float(value)), limit)
        try:
            if limit <= 0.0:
                canvas.yview_moveto(0.0)
            elif value >= limit - 0.5:
                canvas.yview_moveto(1.0)
            else:
                canvas.yview_moveto(value / total)
            first = float(canvas.yview()[0])
            state["offset"] = min(limit, max(0.0, first * total))
        except (tk.TclError, TypeError, ValueError, ZeroDivisionError):
            state["offset"] = value

    def tick():
        state["after"] = None
        diff = state["target"] - state["offset"]
        if abs(diff) < 1.0:
            apply_offset(state["target"])
            return
        step = diff * _smooth_follow_factor(state)
        if abs(step) < 1.0:
            step = 1.0 if diff > 0 else -1.0
        apply_offset(state["offset"] + step)
        try:
            state["after"] = scheduler.after(10, tick)
        except tk.TclError:
            state["after"] = None

    def scroll_by(pixels):
        if state["after"] is None:
            sync()
        _total, _viewport, limit = metrics()
        state["target"] = min(
            max(0.0, state["target"] + float(pixels)), limit
        )
        if state["after"] is None:
            tick()

    def on_wheel(event):
        try:
            number = getattr(event, "num", None)
            if number == 4:
                notches = -1.0
            elif number == 5:
                notches = 1.0
            elif getattr(event, "delta", 0):
                notches = -float(event.delta) / 120.0
                if abs(notches) < 0.01:
                    notches = -1.0 if event.delta > 0 else 1.0
            else:
                return "break"
            scroll_by(notches * float(pixels_per_notch))
        except (tk.TclError, TypeError, ValueError):
            pass
        return "break"

    def scrollbar_command(*args):
        if not args:
            return
        cancel()
        try:
            canvas.yview(*args)
        except (tk.TclError, TypeError, ValueError):
            pass
        sync()

    for widget in (canvas, *tuple(wheel_widgets)):
        try:
            for sequence in ("<MouseWheel>", "<Button-4>", "<Button-5>"):
                widget.bind(sequence, on_wheel, add="+")
        except tk.TclError:
            pass

    return {
        "state": state,
        "wheel": on_wheel,
        "scroll_by": scroll_by,
        "scrollbar_command": scrollbar_command,
        "sync": sync,
        "cancel": cancel,
    }


class ModalTitle(tk.Canvas):
    SHADOW_COLOR_DARK = "#000000"
    SHADOW_COLOR_LIGHT = "#FFFFFF"

    def __init__(self, master, text, font=None, bg=None, fg=None):
        from tkinter import font as tkfont
        font = font or ("Cascadia Mono", 11, "normal", "roman")
        bg = bg if bg is not None else COLORS["bg_main"]
        fg = fg if fg is not None else COLORS["fg_strong"]
        measure_font = tkfont.Font(root=master, font=font)
        text_w = int(measure_font.measure(text))
        title_line_h = int(measure_font.metrics("linespace"))
        width = text_w + ui_px(8)
        height = title_line_h + ui_px(4)
        super().__init__(
            master, width=_dpi_px_from_current_pixels(width),
            height=_dpi_px_from_current_pixels(height),
            bg=bg, bd=0, highlightthickness=0, takefocus=0,
        )
        center_x = width / 2.0
        center_y = (height - 1) / 2.0
        self._shadow_item = self.create_text(
            center_x, center_y + 1, text=text, font=font,
            fill=(self.SHADOW_COLOR_LIGHT if IS_LIGHT_THEME else self.SHADOW_COLOR_DARK),
            tags=("pycode_title_shadow",),
        )
        self._text_item = self.create_text(
            center_x, center_y, text=text, font=font, fill=fg,
            tags=("pycode_title_text",),
        )
        self._pycode_theme_refresh = self.refresh_theme

    def refresh_theme(self):
        try:
            self.configure(bg=COLORS["bg_main"])
            self.itemconfigure(
                self._shadow_item,
                fill=(self.SHADOW_COLOR_LIGHT if IS_LIGHT_THEME else self.SHADOW_COLOR_DARK),
            )
            self.itemconfigure(self._text_item, fill=COLORS["fg_strong"])
        except tk.TclError:
            pass


def bind_modal_escape(root_widget, callback):
    def visit(widget):
        try:
            widget.bind("<KeyPress-Escape>", lambda _e, cb=callback: (cb(), "break")[1], add="+")
            for child in widget.winfo_children():
                visit(child)
        except tk.TclError:
            pass

    visit(root_widget)


class _LineActiveState:
    __slots__ = ("states", "active_line", "version")

    def __init__(self):
        self.states = []
        self.active_line = None
        self.version = 0

    def resize(self, line_count):
        line_count = max(1, int(line_count))
        old_count = len(self.states)
        if old_count == line_count:
            return False
        if line_count > old_count:
            self.states.extend([0] * (line_count - old_count))
        else:
            del self.states[line_count:]
        if self.active_line is not None and not 1 <= self.active_line <= line_count:
            self.active_line = None
        self.version += 1
        return True

    def set_active(self, line):
        line = max(1, min(int(line), max(1, len(self.states))))
        previous = self.active_line
        if previous == line and self.states and self.states[line - 1] == 1:
            return previous, line, False

        if previous is not None and 1 <= previous <= len(self.states):
            self.states[previous - 1] = 0

        self.states[line - 1] = 1
        self.active_line = line
        self.version += 1
        return previous, line, True

    def clear_all(self):
        for i in range(len(self.states)):
            self.states[i] = 0
        self.active_line = None
        self.version += 1


class WrapEdgeCaret:
    TICK_MS = 40

    def __init__(self, text, is_blocked=None):
        self.text = text
        self._is_blocked = is_blocked or (lambda: False)
        self._armed_index = None
        self._saved_width = None
        self._after_id = None
        self._phase_started = 0.0
        self._space_width = {}
        self._bar = tk.Frame(text, bd=0, highlightthickness=0, takefocus=0)
        self._tag = f"WrapEdgeCaret{id(self)}"
        text.bindtags((self._tag,) + tuple(text.bindtags()))
        text.bind_class(self._tag, "<Button-1>", self._on_press)
        text.bind_class(self._tag, "<ButtonRelease-1>", self._on_release)
        text.bind_class(self._tag, "<KeyPress>", self._on_key)
        text.bind_class(self._tag, "<FocusOut>", lambda _e: self.disarm())
        text.bind_class(self._tag, "<Destroy>", lambda _e: self._cancel_tick())

    # Events
    def _on_press(self, _event):
        self.disarm()

    def _on_release(self, event):
        y = int(event.y)
        try:
            self.text.after_idle(lambda: self._evaluate(y=y))
        except tk.TclError:
            pass

    def _on_key(self, event):
        state = int(getattr(event, "state", 0) or 0)
        if state & 0x4 or state & 0x20000 or state & 0x8:
            return
        keysym = event.keysym
        char = event.char or ""
        if keysym == "Right" or (len(char) == 1 and char.isprintable()):
            try:
                before = self.text.index("insert")
                self.text.after_idle(lambda: self._evaluate(before=before))
            except tk.TclError:
                pass

    # Geometry
    def _at_boundary(self, index, y=None):
        t = self.text
        if int(index.split(".")[1]) == 0:
            return False
        prev = t.index(f"{index}-1c")
        prev_box = t.bbox(prev)
        here_box = t.bbox(index)
        if prev_box is None or here_box is None:
            return False
        if here_box[1] <= prev_box[1]:
            return False
        if y is not None and not (prev_box[1] <= y < prev_box[1] + prev_box[3]):
            return False
        return True

    def _evaluate(self, before=None, y=None):
        t = self.text
        try:
            if (self._is_blocked() or str(t.cget("state")) != "normal"
                    or t.tag_ranges("sel")):
                self.disarm()
                return
            index = t.index("insert")
            if before is not None and t.compare(index, "<=", before):
                self.disarm()
                return
            if not self._at_boundary(index, y):
                self.disarm()
                return
            self._arm(index)
        except tk.TclError:
            self.disarm()

    # Cycle de vie
    def _arm(self, index):
        t = self.text
        if self._saved_width is None:
            self._saved_width = _dpi_px_from_current_pixels(t.cget("insertwidth"))
            t.configure(insertwidth=0)
        self._armed_index = index
        self._phase_started = time.monotonic()
        self._cancel_tick()
        self._tick()

    def disarm(self):
        self._armed_index = None
        self._cancel_tick()
        try:
            self._bar.place_forget()
        except tk.TclError:
            pass
        if self._saved_width is not None:
            try:
                self.text.configure(insertwidth=_dpi_px_from_current_pixels(self._saved_width))
            except tk.TclError:
                pass
            self._saved_width = None

    def _cancel_tick(self):
        if self._after_id is not None:
            try:
                self.text.after_cancel(self._after_id)
            except tk.TclError:
                pass
            self._after_id = None

    def _tick(self):
        self._after_id = None
        index = self._armed_index
        if index is None:
            return
        t = self.text
        try:
            try:
                focused = t.focus_displayof() is t
            except (KeyError, tk.TclError):
                focused = False
            ok = (focused and not self._is_blocked()
                  and str(t.cget("state")) == "normal"
                  and not t.tag_ranges("sel")
                  and t.index("insert") == index
                  and self._at_boundary(index))
            if not ok:
                self.disarm()
                return
            self._place(index)
            self._after_id = t.after(self.TICK_MS, self._tick)
        except tk.TclError:
            self.disarm()

    def _measure_space(self):
        font_name = str(self.text.cget("font"))
        width = self._space_width.get(font_name)
        if width is None:
            from tkinter import font as tkfont
            width = tkfont.Font(root=self.text, font=font_name).measure(" ")
            self._space_width[font_name] = width
        return width

    def _place(self, index):
        t = self.text
        prev = t.index(f"{index}-1c")
        box = t.bbox(prev)
        if box is None:
            self._bar.place_forget()
            return
        bx, by, bw, bh = box
        x = bx + (self._measure_space() if t.get(prev) == " " else bw)
        width = max(1, int(self._saved_width or 1))
        x = max(0, min(x - width // 2, t.winfo_width() - width - 1))
        visible = True
        try:
            on_ms = int(t.cget("insertontime"))
            off_ms = int(t.cget("insertofftime"))
        except (tk.TclError, ValueError):
            on_ms, off_ms = 600, 300
        if on_ms > 0 and off_ms > 0:
            elapsed = (time.monotonic() - self._phase_started) * 1000.0
            visible = (elapsed % (on_ms + off_ms)) < on_ms
        if visible:
            self._bar.configure(
                bg=t.cget("insertbackground"),
                width=_dpi_px_from_current_pixels(width),
                height=_dpi_px_from_current_pixels(bh),
            )
            self._bar.place(x=x, y=by)
            self._bar.lift()
        else:
            self._bar.place_forget()


_RIGHT_CLICK_BUTTON_CLASSES = frozenset((
    "Button", "TButton", "Checkbutton", "TCheckbutton",
    "Radiobutton", "TRadiobutton", "Menubutton", "TMenubutton",
))
_RIGHT_CLICK_ENTRY_CLASSES = frozenset((
    "Entry", "TEntry", "TCombobox", "Spinbox", "TSpinbox",
))


def _right_click_translation_kind(widget):
    """'button' / 'entry' when a right click should act like a left click."""
    try:
        widget_class = widget.winfo_class()
    except (tk.TclError, AttributeError):
        return None
    if widget_class in _RIGHT_CLICK_ENTRY_CLASSES:
        return "entry"
    if widget_class in _RIGHT_CLICK_BUTTON_CLASSES:
        return "button"
    current = widget
    for _depth in range(8):
        if (isinstance(current, (HoverButton, MenuButton))
                or getattr(current, "_pycode_right_click_as_left", False)):
            return "button"
        current = getattr(current, "master", None)
        if current is None:
            break
    if widget_class == "Label":
        try:
            if widget.bind("<Button-1>"):
                return "button"
        except tk.TclError:
            pass
    return None


def _install_right_click_as_left_click(root):
    """Replay right clicks on buttons and small entries as left clicks.

    Text areas, canvases, scrollbars and the editor/console context menus keep
    their own right-click behavior because only whitelisted widgets match.
    """
    pressed = {"widget": None}

    def fire(widget, sequence, event):
        try:
            if not widget.winfo_exists():
                return
            widget.event_generate(
                sequence,
                x=int(event.x_root - widget.winfo_rootx()),
                y=int(event.y_root - widget.winfo_rooty()),
                rootx=int(event.x_root), rooty=int(event.y_root),
            )
        except tk.TclError:
            pass

    def on_press(event):
        widget = getattr(event, "widget", None)
        if not isinstance(widget, tk.Misc) or _right_click_translation_kind(widget) is None:
            pressed["widget"] = None
            return None
        pressed["widget"] = widget
        fire(widget, "<ButtonPress-1>", event)
        return None

    def on_release(event):
        widget = pressed["widget"]
        pressed["widget"] = None
        if widget is not None:
            fire(widget, "<ButtonRelease-1>", event)
        return None

    root.bind_all("<ButtonPress-3>", on_press, add="+")
    root.bind_all("<ButtonRelease-3>", on_release, add="+")



def _debug_overlay_synced(method):
    """Re-mirror bracket highlights on breakpoint rows after the method ran."""
    def wrapper(self, *args, **kwargs):
        try:
            return method(self, *args, **kwargs)
        finally:
            if getattr(self, "_debug_breakpoint_marks", None):
                self._sync_debug_overlay_variants()
    wrapper.__name__ = method.__name__
    wrapper.__doc__ = method.__doc__
    return wrapper


class ModernEditor(tk.Tk):
    def __init__(self):
        super().__init__()

        self._startup_veil = None
        self._startup_veil_after_id = None
        self._editor_height_calibration_after_id = None
        self._editor_height_calibration_attempts = 0
        self.configure(bg=COLORS["bg_main"])
        try:
            self.attributes("-alpha", 0.0)
            self.after(3000, self._ensure_window_opaque)
        except tk.TclError:
            pass
        try:
            self.withdraw()
        except tk.TclError:
            pass

        self._spare_runners = {}
        self._adopted_root_runner = None
        self._file_open_veil = None
        # A frozen --onefile build must not start an idle multiprocessing child
        # just to pre-warm the next Run. On managed Windows machines, App Control
        # may deny that child executable before the user asks to run any code.
        if not (sys.platform == "win32" and getattr(sys, "frozen", False)):
            try:
                self.after(2500, lambda: self._spawn_spare_runner("editor"))
            except tk.TclError:
                pass

        try:
            sys.setswitchinterval(0.0005)
        except (AttributeError, ValueError):
            pass

        self._dpi = get_window_dpi(self) if sys.platform == "win32" else BASE_DPI
        if not self._dpi or self._dpi <= 0:
            self._dpi = BASE_DPI
        self._dpi_scale = self._dpi / BASE_DPI
        self._dpi_startup = float(self._dpi)
        self._dpi_startup_scale = float(self._dpi_scale)
        self._dpi_monitor_current = float(self._dpi)
        global UI_SCALE, UI_DPI
        UI_DPI = self._dpi_startup
        UI_SCALE = self._dpi_startup_scale
        try:
            self.tk.call("tk", "scaling", self._dpi / 72.0)
        except tk.TclError:
            pass

        if sys.platform == "win32":
            dpi_awareness = get_window_dpi_awareness(self)
            if dpi_awareness == 2:
                try:
                    from tkinter import messagebox
                    messagebox.showwarning(
                        "PyCode - Multi-monitor DPI",
                        "This window was created in Per-Monitor DPI mode despite PyCode's "
                        "compatibility settings. In this mode, Windows expects WM_DPICHANGED "
                        "handling that Tk 8.6 and PyCode's dimension-scaling layer cannot "
                        "safely synchronize.\n\n"
                        "Make sure the executable manifest does not force Per-Monitor DPI, "
                        "and disable any DPI scaling override configured in the Windows "
                        "compatibility properties.",
                        parent=self,
                    )
                except Exception:
                    pass
        self._dpi_native_hook_installed = False

        self.title("PyCode - Edit (Untitled.py)")
        self.configure(bg=COLORS["bg_main"])
        self.geometry(f"{ui_px(850)}x{ui_px(538)}")
        self.resizable(False, False)
        self._dpi_recheck_after_id = None
        self._dpi_poll_after_id = None
        self.bind("<Configure>", self._on_window_configure_dpi, add="+")
        self.bind("<Configure>", self._on_notification_window_configure, add="+")
        self.bind_all("<Map>", self._capture_mapped_toplevel_dpi_geometry, add="+")

        # File state
        self.file_path = None
        self.file_name = "Untitled.py"
        self.last_modified = "Not saved"
        self.current_menu = None
        self._active_menu_button = None
        self._modal_cursor_restore = {}
        self._modal_cursor_lock_active = False
        self._modal_root_cursor_restore = None
        self._modal_input_state = {}
        self._modal_dim_active = False
