        self._modal_dim_tag_state = {}
        self._modal_enforce_after_id = None
        self.bind_all("<FocusIn>", self._modal_focus_changed, add="+")
        self.bind_all("<FocusOut>", self._modal_focus_changed, add="+")
        self._window_veil_after_ids = {}
        self.bind_all("<Unmap>", self._window_veil_on_unmap, add="+")
