    def _present_startup_veil(self):
        try:
            if not self.winfo_exists():
                return
            self.update_idletasks()
            try:
                geometry_part = self.geometry().split("+", 1)[0]
                width_text, height_text = geometry_part.split("x", 1)
                width, height = int(width_text), int(height_text)
                if width <= 1:
                    width = int(self.winfo_reqwidth())
                if height <= 1:
                    height = int(self.winfo_reqheight())
                screen_width = int(self.winfo_screenwidth())
                screen_height = int(self.winfo_screenheight())
                x = max(0, (screen_width - width) // 2)
                y = max(0, (screen_height - height) // 2)
                self.geometry(f"{width}x{height}+{x}+{y}")
            except (tk.TclError, TypeError, ValueError):
                pass
            self.configure(bg=COLORS["bg_main"])
            veil = tk.Frame(
                self,
                bg=self.cget("bg"),
                borderwidth=0,
                highlightthickness=0,
            )
            self._window_veil_fill(veil, self._window_veil_capture(self))
            veil.place(x=0, y=0, relwidth=1, relheight=1)
            veil.lift()
            self._startup_veil = veil
            self.deiconify()
            self.update_idletasks()
            try:
                self._editor_height_calibration_attempts = 0
                self._editor_height_calibration_after_id = self.after(
                    20, self._calibrate_editor_height_to_ten_lines
                )
            except tk.TclError:
                self._editor_height_calibration_after_id = None
            self._startup_veil_after_id = self.after(160, self._remove_startup_veil_when_settled)
        except tk.TclError:
            self._remove_startup_veil()

    def _remove_startup_veil_when_settled(self):
        """Lift the veil only once the first-run height calibration has finished,
        so the window is never seen changing size after it appears."""
        self._startup_veil_after_id = None
        now = time.perf_counter()
        started = getattr(self, "_startup_veil_wait_started", None)
        if started is None:
            started = self._startup_veil_wait_started = now
        if self._editor_height_calibration_after_id is not None and now - started < 0.6:
            try:
                self._startup_veil_after_id = self.after(16, self._remove_startup_veil_when_settled)
                return
            except tk.TclError:
                pass
        self._remove_startup_veil()

    def _remove_startup_veil(self):
        self._startup_veil_after_id = None
        veil = getattr(self, "_startup_veil", None)
        self._startup_veil = None
        if veil is not None:
            try:
                if veil.winfo_exists():
                    veil.destroy()
            except tk.TclError:
                pass
        self._ensure_window_opaque(flush=True)

    def _ensure_window_opaque(self, flush=False):
        try:
            if flush:
                self.update_idletasks()
            self.attributes("-alpha", 1.0)
        except tk.TclError:
            pass

    def _capture_dpi_toplevel_geometry(self, window):
        try:
            if not window.winfo_exists():
                return
            width = int(window.winfo_width())
            height = int(window.winfo_height())
            if width <= 1 or height <= 1:
                geometry = str(window.geometry()).split("+", 1)[0]
                if "x" in geometry:
                    width_text, height_text = geometry.split("x", 1)
                    width = int(width_text)
                    height = int(height_text)
            if width <= 1 or height <= 1:
                return
            scale = max(0.01, float(UI_SCALE))
            window._pycode_dpi_base_geometry = (width / scale, height / scale)
        except (tk.TclError, AttributeError, TypeError, ValueError):
            pass

    def _capture_mapped_toplevel_dpi_geometry(self, event=None):
        try:
            widget = getattr(event, "widget", None)
            if widget is None:
                return
            top = widget.winfo_toplevel()
            if top is self:
                return
            try:
                self.after(120, lambda w=top: self._capture_dpi_toplevel_geometry(w))
            except tk.TclError:
                pass
        except (tk.TclError, AttributeError):
            pass

    def _poll_window_dpi(self):
        self._dpi_poll_after_id = None
        try:
            if not self.winfo_exists():
                return
            dpi = get_window_dpi(self)
            observed_dpi = float(getattr(self, "_dpi_monitor_current", self._dpi_startup) or self._dpi_startup)
            if dpi > 0 and abs(float(dpi) - observed_dpi) >= 0.5:
                self._refresh_window_dpi(dpi, preserve_native_geometry=False)
            self._dpi_poll_after_id = self.after(80 if sys.platform == "win32" else 250, self._poll_window_dpi)
        except tk.TclError:
            self._dpi_poll_after_id = None

    def _console_selection_is_only_empty_lines(self, first, last):
        try:
            selected = self.console.get(first, last)
            if selected and selected.strip():
                return False

            first_line = int(str(first).split('.')[0])
            last_probe = self.console.index(last)
            last_line = int(str(last_probe).split('.')[0])

            for line_no in range(first_line, last_line + 1):
                line_start = f"{line_no}.0"
                line_end = self.console.index(f"{line_start} lineend")
                line_text = self.console.get(line_start, line_end)

                if self.console.compare(line_end, "<", first):
                    continue
                if self.console.compare(line_start, ">=", last):
                    continue

                if line_text.strip():
                    return False
            return True
        except (tk.TclError, AttributeError, ValueError):
            return False

    def _console_event_on_traceback_link(self, event):
        try:
            names = self.console.tag_names(self.console.index(f"@{event.x},{event.y}"))
        except (tk.TclError, AttributeError):
            return False
        return any(
            name in ("traceback_file_link", "traceback_line_link")
            or str(name).startswith(("traceback_file_action_", "traceback_line_action_", "traceback_action_"))
            for name in names
        )

    def _handle_console_link_multiclick(self, event):
        # Double/triple clicks on a link must not select a word or take the focus.
        return "break" if self._console_event_on_traceback_link(event) else None

    def _handle_console_click(self, event):
        if self._console_event_on_traceback_link(event):
            # The link handler already moved the focus to the editor line; the
            # console must neither take it back nor place its caret under the click.
            return "break"
        waiting = bool(getattr(self, "waiting_for_input", False))
        if self._modal_dim_active or (self._console_is_busy() and not waiting):
            try:
                self.console.tag_remove("sel", "1.0", tk.END)
                self.console.tag_remove("console_inactive_selection", "1.0", tk.END)
            except tk.TclError:
                pass
            return "break"
        try:
            self.console.focus_set()
        except tk.TclError:
            return "break"
        return None

    def _guard_console_selection_while_busy(self, event=None):
        if not self._console_is_busy() or getattr(self, "waiting_for_input", False):
            return None
        try:
            self.console.tag_remove("sel", "1.0", tk.END)
            self.console.tag_remove("console_inactive_selection", "1.0", tk.END)
        except tk.TclError:
            pass
        return "break"

    def _handle_empty_console_button_click(self, event=None):
        if getattr(self, "_modal_dim_active", False):
            return "break"
        if event is None:
            return None

        try:
            index = self.console.index(f"@{event.x},{event.y}")
            line = self.console.index(f"{index} linestart")
            line_end = self.console.index(f"{index} lineend")
            content = self.console.get(line, line_end)

            if not content.strip():
                self.console.tag_remove("sel", "1.0", tk.END)
                self.console.tag_remove("console_inactive_selection", "1.0", tk.END)
                self.console.mark_set("insert", index)
                self.console.see(index)
                # Returning "break" skips Tk's default click binding, which is what
                # gives the widget the keyboard focus. Without this, an empty input
                # line could never take the focus back once it had been lost.
                if (not self._console_is_busy()
                        or getattr(self, "waiting_for_input", False)):
                    try:
                        self.console.focus_set()
                    except tk.TclError:
                        pass
                return "break"
        except (tk.TclError, AttributeError):
            return "break"

        return None

    def _reject_empty_console_selection(self, event=None):
        if getattr(self, "_modal_dim_active", False):
            return "break"
        try:
            if self.console.tag_ranges("sel"):
                first = self.console.index("sel.first")
                last = self.console.index("sel.last")
                if self._console_selection_is_only_empty_lines(first, last):
                    self.console.tag_remove("sel", "1.0", tk.END)
                    self.console.tag_remove("console_inactive_selection", "1.0", tk.END)
                    return "break"
        except (tk.TclError, AttributeError):
            pass
        return None

    def _handle_console_mouse_release(self, event=None):
        if self._reject_empty_console_selection(event) == "break":
            return "break"
        return None

    def _on_window_configure_dpi(self, event=None):
        if event is not None and getattr(event, "widget", self) is not self:
            return
        pending = getattr(self, "_dpi_recheck_after_id", None)
        if pending is not None:
            try:
                self.after_cancel(pending)
            except tk.TclError:
                pass
        try:
            self._dpi_recheck_after_id = self.after(100, self._refresh_window_dpi)
        except tk.TclError:
            self._dpi_recheck_after_id = None

    def _refresh_window_dpi(
            self, requested_dpi=None, preserve_native_geometry=False,
            transition_generation=None):
        try:
            dpi = float(requested_dpi or get_window_dpi(self))
        except (tk.TclError, TypeError, ValueError):
            return
        if dpi <= 0:
            return
        previous_monitor_dpi = float(
            getattr(self, "_dpi_monitor_current", getattr(self, "_dpi_startup", BASE_DPI))
            or BASE_DPI
        )
        if abs(dpi - previous_monitor_dpi) < 0.5:
            return
        self._dpi_monitor_current = dpi

        if LOCK_UI_DIMENSIONS:
            return

        current_dpi = float(getattr(self, "_dpi", BASE_DPI) or BASE_DPI)
        if abs(dpi - current_dpi) < 0.5:
            return
        self._refresh_window_dpi_impl(
            requested_dpi=dpi,
            preserve_native_geometry=False,
            transition_generation=None,
        )

    def _refresh_window_dpi_impl(
            self, requested_dpi=None, preserve_native_geometry=False,
            transition_generation=None):
        global UI_SCALE, UI_DPI
        try:
            if (transition_generation is not None and
                    transition_generation != getattr(self, "_dpi_transition_generation", None)):
                return

            self._dpi_recheck_after_id = None
            dpi = float(requested_dpi or get_window_dpi(self))
            if dpi <= 0:
                return
            old_dpi = float(getattr(self, "_dpi", BASE_DPI) or BASE_DPI)
            rect_dpi = getattr(self, "_dpi_native_rect_applied_dpi", None)
            if rect_dpi is not None and abs(float(rect_dpi) - dpi) < 0.5:
                preserve_native_geometry = True

            if abs(dpi - old_dpi) < 0.5:
                if preserve_native_geometry:
                    self._sync_toplevel_geometry_for_dpi(
                        self, max(0.5, dpi / BASE_DPI), sync_fixed_hints=True
                    )
                    self.__dict__.pop("_dpi_native_rect_applied_dpi", None)
                return

            new_scale = max(0.5, dpi / BASE_DPI)

            top_levels = [self]
            pending = list(self.winfo_children())
            while pending:
                child = pending.pop()
                try:
                    pending.extend(child.winfo_children())
                except tk.TclError:
                    pass
                if isinstance(child, tk.Toplevel):
                    top_levels.append(child)
            for top in top_levels:
                if not hasattr(top, "_pycode_dpi_base_geometry"):
                    try:
                        width = max(1, int(top.winfo_width()))
                        height = max(1, int(top.winfo_height()))
                        capture_scale = new_scale if (top is self and preserve_native_geometry) else max(
                            0.01, old_dpi / BASE_DPI
                        )
                        top._pycode_dpi_base_geometry = (width / capture_scale, height / capture_scale)
                    except (tk.TclError, TypeError, ValueError):
                        pass

            self._dpi = dpi
            self._dpi_scale = new_scale
            UI_DPI = dpi
            UI_SCALE = new_scale
            try:
                self.tk.call("tk", "scaling", dpi / 72.0)
            except tk.TclError:
                pass

            _apply_dpi_widget_scale(new_scale)
            try:
                self.update_idletasks()
            except tk.TclError:
                pass

            for top in top_levels:
                if top is self and preserve_native_geometry:
                    self._sync_toplevel_geometry_for_dpi(
                        top, new_scale, sync_fixed_hints=True,
                        preserve_existing_geometry=True
                    )
                else:
                    self._sync_toplevel_geometry_for_dpi(
                        top, new_scale,
                        sync_fixed_hints=(top is self or self._is_fixed_toplevel(top))
                    )

            self.__dict__.pop("_dpi_native_rect_applied_dpi", None)
            try:
                self.update_idletasks()
                self.after_idle(self._align_header_search_with_line_entry)
                self.after_idle(self.update_line_numbers)
                self.after_idle(lambda: self._schedule_console_syntax_refresh(0))
            except (tk.TclError, AttributeError):
                pass
        except (tk.TclError, AttributeError, OSError, TypeError, ValueError):
            pass

    @staticmethod
    def _is_fixed_toplevel(window):
        try:
            resizable = window.resizable()
            return not bool(resizable[0]) and not bool(resizable[1])
        except (tk.TclError, AttributeError, TypeError, IndexError):
            return False

    def _sync_toplevel_geometry_for_dpi(
            self, window, scale, sync_fixed_hints=False, preserve_existing_geometry=False):
        try:
            if not window.winfo_exists():
                return
            if preserve_existing_geometry:
                width = max(1, int(window.winfo_width()))
                height = max(1, int(window.winfo_height()))
            else:
                base_geometry = getattr(window, "_pycode_dpi_base_geometry", None)
                if not base_geometry:
                    return
                width = max(1, int(round(float(base_geometry[0]) * scale)))
                height = max(1, int(round(float(base_geometry[1]) * scale)))

            if sync_fixed_hints and self._is_fixed_toplevel(window):
                window.minsize(width, height)
                window.maxsize(width, height)

            if not preserve_existing_geometry:
                window.geometry(f"{width}x{height}")
        except (tk.TclError, AttributeError, TypeError, ValueError):
            pass

    def create_header(self):
        self._header_height = ui_px(48)
        self._header_bg = COLORS["header_bg"]
        self.header_top_spacer = tk.Frame(
            self,
            bg=self._header_bg,
            height=ui_px(4),
            bd=0,
            highlightthickness=0,
        )
        self.header_top_spacer.pack(side="top", fill="x", pady=0, padx=0)

        self.header_frame = tk.Frame(
            self,
            bg=self._header_bg,
            height=self._header_height,
        )
        self.header_frame.pack(side="top", fill="x", pady=0, padx=0)
        self.header_frame.pack_propagate(False)

        self.logo_frame = tk.Frame(
            self.header_frame,
            bg=self._header_bg,
            width=1,
            height=self._header_height,
            bd=0,
            highlightthickness=0,
        )
        self._logo_side_pad_left = ui_px(6)
        self._logo_side_pad_right = ui_px(8)
        self.logo_frame.pack(side="left", fill="y", padx=0, pady=0)
        self.logo_frame.pack_propagate(False)

        self.logo_label = None
        self.logo_image = None
        self.logo_text_fallback = False
        self._logo_images_by_theme = {}
        self._logo_dim_images_by_theme = {}
        self._logo_dim_image_backgrounds = {}
        self._logo_pil_images_by_theme = {}
        self._logo_paths_by_theme = {}
        try:
            dark_logo_path = resource_path("PyCode Logo Text.png")
            light_logo_path = resource_path("PyCode Logo Text Light.png")
            if not os.path.isfile(light_logo_path):
                light_logo_path = dark_logo_path

            for logo_theme, img_path in (
                    (THEME_DARK, dark_logo_path), (THEME_GLOW, light_logo_path)):
                self._logo_paths_by_theme[logo_theme] = img_path
                try:
                    if Image is not None and ImageTk is not None:
                        with Image.open(img_path) as source:
                            pil_image = source.convert("RGBA")
                        self._logo_pil_images_by_theme[logo_theme] = pil_image.copy()
                        self._logo_images_by_theme[logo_theme] = ImageTk.PhotoImage(
                            pil_image, master=self
                        )
                        try:
                            dimmed_rgba = _build_dimmed_logo_rgba(
                                pil_image, THEME_PALETTES.get(logo_theme, _PALETTE_DARK).get("header_bg", "#181818")
                            )
                            self._logo_dim_images_by_theme[logo_theme] = ImageTk.PhotoImage(
                                dimmed_rgba, master=self
                            )
                            self._logo_dim_image_backgrounds[logo_theme] = (
                                THEME_PALETTES.get(logo_theme, _PALETTE_DARK).get("header_bg", "#181818")
                            )
                        except Exception:
                            pass
                    else:
                        self._logo_images_by_theme[logo_theme] = tk.PhotoImage(
                            master=self, file=img_path
                        )
                except Exception:
                    continue

            if THEME_DARK not in self._logo_images_by_theme and THEME_GLOW in self._logo_images_by_theme:
                self._logo_images_by_theme[THEME_DARK] = self._logo_images_by_theme[THEME_GLOW]
                self._logo_paths_by_theme[THEME_DARK] = self._logo_paths_by_theme.get(THEME_GLOW)
            if THEME_GLOW not in self._logo_images_by_theme and THEME_DARK in self._logo_images_by_theme:
                self._logo_images_by_theme[THEME_GLOW] = self._logo_images_by_theme[THEME_DARK]
                self._logo_paths_by_theme[THEME_GLOW] = self._logo_paths_by_theme.get(THEME_DARK)
            if THEME_DARK not in self._logo_pil_images_by_theme and THEME_GLOW in self._logo_pil_images_by_theme:
                self._logo_pil_images_by_theme[THEME_DARK] = self._logo_pil_images_by_theme[THEME_GLOW].copy()
            if THEME_GLOW not in self._logo_pil_images_by_theme and THEME_DARK in self._logo_pil_images_by_theme:
                self._logo_pil_images_by_theme[THEME_GLOW] = self._logo_pil_images_by_theme[THEME_DARK].copy()

            if Image is not None and ImageTk is not None:
                for logo_theme in (THEME_DARK, THEME_GLOW):
                    if logo_theme in self._logo_dim_images_by_theme:
                        continue
                    source_rgba = self._logo_pil_images_by_theme.get(logo_theme)
                    if source_rgba is None:
                        continue
                    header_bg = THEME_PALETTES.get(logo_theme, _PALETTE_DARK).get(
                        "header_bg", "#181818"
                    )
                    try:
                        dimmed_rgba = _build_dimmed_logo_rgba(source_rgba, header_bg)
                        self._logo_dim_images_by_theme[logo_theme] = ImageTk.PhotoImage(
                            dimmed_rgba, master=self
                        )
                        self._logo_dim_image_backgrounds[logo_theme] = header_bg
                    except Exception:
                        pass

            active_logo_theme = THEME_GLOW if IS_LIGHT_THEME else THEME_DARK
            self.logo_image = self._logo_images_by_theme.get(active_logo_theme)
            if self.logo_image is None:
                raise FileNotFoundError("No PyCode logo image could be loaded")

            self.logo_label = tk.Label(
                self.logo_frame, image=self.logo_image,
                bg=self._header_bg, bd=0
            )
            self.logo_label.pack(
                side="left", anchor="center",
                padx=(self._logo_side_pad_left, self._logo_side_pad_right)
            )
        except Exception:
            self.logo_text_fallback = True
            self.logo_label = tk.Label(
                self.logo_frame, text="PyCode", bg=self._header_bg,
                fg=COLORS["fg_strong"], font=("Cascadia Mono", 16, "bold")
            )
            self.logo_label.pack(
                side="left", anchor="center",
                padx=(self._logo_side_pad_left, self._logo_side_pad_right)
            )

        try:
            self.update_idletasks()
            logo_width = max(1, self.logo_label.winfo_reqwidth() + self._logo_side_pad_left + self._logo_side_pad_right)
            self.logo_frame.configure(
                width=_dpi_px_from_current_pixels(logo_width), height=self._header_height
            )
        except tk.TclError:
            pass

        self.search_frame = tk.Frame(
            self.header_frame,
            bg=self._header_bg,
            width=260,
            height=self._header_height,
            bd=0,
            highlightthickness=0,
        )
        self.search_frame.place(
            relx=1.0,
            rely=0.5,
            anchor="e",
            width=260,
            height=self._header_height,
        )
        self.search_frame.pack_propagate(False)

        self.search_var = tk.StringVar()
        self.search_var.trace_add("write", self.perform_instant_search)
        self.search_start_idx = "1.0"

        self.search_bar_frame = tk.Frame(
            self.search_frame,
            bg=COLORS["modal_outline"],
            bd=0, highlightthickness=0, padx=1, pady=1,
        )
        self.search_bar_frame._pycode_popup_outline = True
        self.search_bar_outline_frame = tk.Frame(
            self.search_bar_frame, bg=COLORS["border_dark"],
            bd=0, highlightthickness=0, padx=1, pady=1,
        )
        self.search_bar_outline_frame._pycode_popup_inner_outline = True
        self.search_bar_outline_frame.pack(fill="both", expand=True)
        self.search_bar_content_frame = tk.Frame(
            self.search_bar_outline_frame, bg=COLORS["info_bg"],
            bd=0, highlightthickness=0,
        )
        self.search_bar_content_frame.pack(fill="both", expand=True)
        self.search_bar_frame.place(relx=1.0, rely=0.5, anchor="e")

        self.search_entry = tk.Entry(
            self.search_bar_content_frame,
            bg=COLORS["info_bg"],
            fg=COLORS["info_text"],
            insertbackground=COLORS["fg_caret"],
            insertwidth=1,
            insertborderwidth=0,
            font=("Cascadia Mono", 10, "normal", "roman"),
            relief="flat",
            borderwidth=0,
            highlightthickness=0,
            exportselection=False,
            width=24
        )
        self.search_entry.pack(side="left", fill="both", expand=True, padx=0, pady=0)
        self.search_ghost_frame, self.search_ghost_icon, self.search_ghost_text = create_search_ghost(
            self.search_bar_content_frame, "Search...", COLORS["info_bg"]
        )
        # The magnifier has its own left-hand slot. It no longer sits above
